// ギリシャ編 23話版の会話の場面(story/gr23_extract.py でアニメの台本から機械で抜き出したもの。ここは直接直さない)
//  正本: マイドライブ/テリオンアニメ/台本_ギリシャ編_23話版/第NN話.md。直す時は台本を直してから抜き出し直す。
const GR_EP={};
const GR_BT={};
GR_SC.g01_01=[{w:null,t:"2100年の地球。"},{w:null,t:"西暦2100年。研究所で生まれた生き物「テリオン」は、世界じゅうの町で、人と暮らしている。",v:"01_0022"},{w:null,t:"大きな街のビルの壁に、テリオンどうしの勝負の配信。"},{w:null,t:"日本の地図。"},{w:null,t:"日本を、のぞいて。",v:"01_0025"}];
GR_SC.g01_02=[{w:null,t:"ギリシャ。オリーブの村、オリーヴァ。",v:"01_0028"},{w:null,t:"青い海。白い家の坂道に、屋台が並ぶ。"},{w:null,t:"坂の上から、スーツケースを引いた男の子が下りてくる。"},{w:null,t:"オリーブの屋台のおばさん（日差しで色が変わるうすい上着の、2100年の普段着）が、ヤマトに声をかける。"},{w:"x",n:"屋台のおばさん",t:"あんた、ひとりかい？　そんな大きな荷物引いて、どこから来たの。",v:"01_0032"},{w:"hero",t:"日本から。じいちゃんと一緒に来たんだけど、空港でおれがトイレに行ってるあいだに、いなくなっちゃった。",v:"01_0033"},{w:"x",n:"屋台のおばさん",t:"いなくなった？　置いていかれたのかい。",v:"01_0034"},{w:"hero",t:"メッセージは「村で待ってろ」って、これだけ。ホテルの名前のとこで切れてるし、三時間前から返事もこねーんだよ。",v:"01_0035"},{w:"x",n:"屋台のおばさん",t:"あらまあ。ほら、オリーブお食べ。腹がへってると、よけい腹が立つからね。",v:"01_0036"},{w:null,t:"ヤマト、オリーブを一つつまむ。"},{w:"x",n:"屋台のおばさん",t:"あっ、また、あの泥棒！　こらー！　今日はいくつ持ってった！",v:"01_0038"},{w:"hero",f:"surprised",t:"なにあれ！？　しっぽ、燃えてんじゃん！",v:"01_0039"},{w:null,t:"坂の下で、急ブレーキの音。"},{w:null,t:"車から、二人組が降りてくる。"},{w:null,t:"市場の人たちが、さっと道をあける。"},{w:"x",n:"八百屋のおじさん",t:"ヴィクターだ……。",v:"01_0043"},{w:"x",n:"屋台のおばさん",t:"あんた、こっちに下がってな。あいつら、テリオンをさらっていく連中だよ。先週は、パン屋の猫の子が連れていかれた。",v:"01_0044"},{w:null,t:"マルコ、鳥の子の店番がいる屋台の前を通りかかる。"},{w:"marco",t:"これも、もらっとくっす。",v:"01_0046"},{w:"x",n:"八百屋のおじさん",t:"おい、それはうちの——！",v:"01_0047"},{w:"nina",t:"なんか言った？　おじさん。",v:"01_0048"},{w:null,t:"ニーナ、おじさんの屋台のトマトの山を、足でけとばす。"},{w:"nina",t:"あたしらの用は、あの狐。持ち主のいないテリオンは、拾った者のもの。ね、マルコ。",v:"01_0050"},{w:"marco",t:"そうっす。チップの入ってない子は、高く売れるっす。",v:"01_0051"},{w:null,t:"ニーナ、手首の画面を動かす。"},{w:"nina",t:"右！　右から回って！",v:"01_0053"},{w:"marco",t:"右って、どっちの右っすか！",v:"01_0054"},{w:"nina",t:"あんたの右！",v:"01_0055"},{w:null,t:"狐、マルコの頭を踏み台にして、まっすぐ坂の上へ。"},{w:null,t:"狐が、ヤマトの顔に正面からぶつかる。"},{w:null,t:"狐、ヤマトのおなかの上に着地する。目と目が合う。"},{w:"hero",f:"hurt",t:"うわっ、熱っ……！",v:"01_0059"},{w:null,t:"狐、ヤマトの顔を踏んで、跳んでいく。"},{w:null,t:"ヤマト、起き上がる。ふてくされた顔が、どこにもない。"},{w:"hero",f:"smile",t:"すっげー！！　おばちゃん、荷物見てて！",v:"01_0062"},{w:"x",n:"屋台のおばさん",t:"ちょっと、あんた！　ヴィクターの前に出ちゃだめだって！",v:"01_0063"},{w:null,t:"ヤマト、服を散らかしたまま、走りだす。"},{w:null,t:"第1話　テリオン・ワールド",v:"01_0066"}];
GR_SC.g01_03=[{w:null,t:"狐。そのうしろにドローン三機。"},{w:"marco",t:"ニーナさん、なんか、子どもがついてきてるっす。",v:"01_0073"},{w:"nina",t:"子どもなんか、ほっときな。狐をつかまえるのが先だよ。",v:"01_0074"},{w:"hero",t:"おーい、待てよー！　ちょっとさわるだけだって！",v:"01_0075"},{w:"x",n:"子ども1",t:"あの子、ヴィクターより速いよ！",v:"01_0076"},{w:null,t:"ドローンが網を落とす。狐、ふり向きざまに、しっぽから小さな火をとばす。"},{w:"marco",t:"あー！　また網、燃やされたっす！　これで今週、五枚目っすよ！",v:"01_0078"},{w:"nina",t:"だから、上から落とせって言ってんでしょ！",v:"01_0079"},{w:null,t:"狐のしっぽが、今度はヤマトに向く。"},{w:"hero",f:"hurt",t:"あちっ！　……すげえ、今の見た！？　火、とばした！",v:"01_0081"},{w:"x",n:"子ども2",t:"前髪、焦げてるよ！",v:"01_0082"},{w:"hero",t:"いいって、前髪なんか！　それより、今の火、見たかよ！",v:"01_0083"},{w:null,t:"狐の口から、半分焦げたオリーブが一つ落ちる。"}];
GR_SC.g01_04=[{w:null,t:"村の上の、古い神殿のあと。",v:"01_0087"},{w:null,t:"坂のてっぺん。"},{w:null,t:"狐、その木の根もとに逃げこむ。くわえてきたオリーブを、しっぽの火の上に乗せる。"},{w:null,t:"根もとに入ったとたん、しっぽの火が、ぼっと一回りふくらむ。"},{w:null,t:"ヤマト、息を切らして追いつく。"},{w:null,t:"狐が、根もとから一歩だけ枯れ草の上へ出る。"},{w:null,t:"ヤマト、目をまるくして、それを見ている。……が、すぐ顔がゆるむ。"},{w:"hero",t:"おまえ、ここが好きなのか？　大丈夫、おれ、あいつらの仲間じゃないから。ほら、なんにもしないって。",v:"01_0094"},{w:null,t:"ヤマト、右手をのばす。"},{w:"hero",t:"よーし、いい子だ。そのまま、そのまま……。",v:"01_0096"},{w:"hero",f:"hurt",t:"いってえええ！！　なんでだよ！　今、いい感じだったじゃん！",v:"01_0098"},{w:null,t:"狐は木の上へ跳び上がって、知らん顔でオリーブの続きを食べる。"},{w:null,t:"ヤマト、右手を押さえて、顔をしかめる。"}];
GR_SC.g01_05=[{w:null,t:"石段の下から、ごろごろと音。"},{w:"elly",t:"あ、いたいた！　ねえ、これ、きみのでしょ？　オリーブのおばさんから預かってきたよ。",v:"01_0104"},{w:"hero",t:"あ……ありがと。わざわざ持ってきてくれたの？",v:"01_0105"},{w:"elly",t:"おばさんが「男の子が荷物置いて、狐を追っかけてった」って、大さわぎしてたんだもん。……って、ちょっと、その右手！　赤くなってるじゃない！",v:"01_0106"},{w:"hero",t:"ああ、これ？　なでようとしたら、狐にガブッとやられた。",v:"01_0107"},{w:"elly",t:"やられたのに、なんでそんな、うれしそうなの！　ほら、すわって！",v:"01_0108"},{w:null,t:"ヤマト、木の根もとに座らされる。エリー、ヤマトの右手を取って、カバンを開ける。"},{w:"elly",t:"しみるよ。がまんしてね。",v:"01_0110"},{w:"hero",t:"いっ……！　しみる、しみる！",v:"01_0111"},{w:"elly",t:"あの子、フォルンっていうの。この丘に住んでる野良の狐の子。村の人はみんなそう呼んでる。だれにもさわらせないんだよ。",v:"01_0112"},{w:"elly",t:"わたしなんか、三年、毎日クッキー持ってきてるのに、一回もなでさせてもらったことないんだから。",v:"01_0113"},{w:null,t:"根もとの石のくぼみに、クッキーが一枚。"},{w:"hero",t:"フォルンか。かっこいい名前じゃん。",v:"01_0115"},{w:null,t:"木の上で、フォルンの耳が、ぴくっとこっちを向く。"},{w:"elly",t:"さっきの黒い車の二人、見た？　あれが、ヴィクター。持ち主のいないテリオンを、つかまえて売ってるの。フォルン、何回もねらわれてるんだよ。",v:"01_0117"},{w:"hero",t:"警察とか、なにもしねーの？",v:"01_0118"},{w:"elly",t:"村には、おまわりさんがひとりしかいないの。それも、おじいちゃんだから、追いかけっこなんて無理だもん。",v:"01_0119"},{w:"elly",t:"で、きみは？　観光？",v:"01_0120"},{w:"hero",t:"観光っていうか……日本から、けさ着いたとこ。",v:"01_0121"},{w:null,t:"エリーの手が止まる。"},{w:"elly",t:"ちょっと待って。日本から来た、男の子。きみ、もしかして、ヤマト？",v:"01_0123"},{w:"hero",t:"え、なんでおれの名前知ってんの。",v:"01_0124"},{w:"elly",t:"わたし、エリー！　うち、ホテルやってるの！　きみのおじいちゃんから電話があって、空港まで迎えに行ったんだよ！　三時間待ったんだからね、三時間！",v:"01_0125"},{w:"hero",t:"じいちゃん、それ、おれにひと言も言ってない。",v:"01_0126"},{w:null,t:"ヤマト、手首の画面をつける。"},{w:"elly",t:"名前のとこで切れてるけど、このホテル、うちのことだよ。",v:"01_0128"},{w:"hero",t:"なんで、そこで切れるんだよ……。",v:"01_0129"},{w:"elly",t:"で、おじいちゃんは？",v:"01_0130"},{w:"hero",t:"知らない。空港でトイレに行って、もどったら、もういなかったんだ。",v:"01_0131"},{w:"elly",f:"surprised",t:"ええっ！？　それ、すっごく大変なことじゃない！",v:"01_0132"},{w:"hero",t:"いつものことだよ。じいちゃん、急に消えるの、得意だから。",v:"01_0133"},{w:null,t:"ヤマトは、話しながらも、木の上のフォルンばかり見ている。"},{w:"elly",t:"もう。心配してるの、わたしだけみたいじゃない。",v:"01_0135"}];
GR_SC.g01_06=[{w:null,t:"ヤマト、ポケットをさぐる。"},{w:"hero",t:"これ、さっきあいつが落としたやつ。",v:"01_0142"},{w:"elly",t:"それで、どうするの？",v:"01_0143"},{w:"hero",t:"今度は、手をのばさない。こっちから手を出すから、やられたんだと思う。",v:"01_0144"},{w:null,t:"ヤマト、オリーブを手のひらに乗せて、ひざの上に置く。"},{w:null,t:"フォルン、木から下りてくる。"},{w:"elly",t:"（小声で）ほら、やっぱり食べない。",v:"01_0147"},{w:"hero",t:"（小声で）しっ。",v:"01_0148"},{w:null,t:"フォルン、オリーブをくわえて、自分のしっぽの火の上に落とす。"},{w:null,t:"くわえ直して、ヤマトの手のひらの上で、かりっと食べる。"},{w:"hero",t:"食った。おれの手の上で、食った！",v:"01_0151"},{w:"elly",f:"surprised",t:"うそでしょ……。焦がしたのが好きだったの？　わたし、三年間、クッキーだったんだけど！",v:"01_0152"},{w:"hero",t:"クッキーは焦がせねーもんな。",v:"01_0153"},{w:"elly",t:"焦がせるよ！　オーブンで！",v:"01_0154"},{w:null,t:"エリー、カバンの中のクッキーの箱を見る。"}];
GR_SC.g01_07=[{w:null,t:"ブーンと、羽の音。"},{w:"marco",t:"はあ、はあ……坂、長すぎっす……。",v:"01_0159"},{w:"nina",t:"いた。……なんで子どもが、狐にエサやってんのよ。",v:"01_0160"},{w:null,t:"フォルン、身がまえる。耳がうしろに倒れる。"},{w:"nina",t:"おい、おチビちゃん。その狐、よこしな！",v:"01_0162"},{w:"hero",t:"嫌だ！　おまえら、誰だ？",v:"01_0163"},{w:"nina",t:"あたしらは、泣く子も黙るマフィア・ヴィクターよ。痛い目見る前に、さっさとよこしな。",v:"01_0164"},{w:"hero",t:"マフィン？　なんだそれ！",v:"01_0165"},{w:"elly",t:"マフィアよ！　こいつら、テリオンをさらっていってる悪いやつらなの！　村の子も、何びきも連れていかれたんだから！",v:"01_0166"},{w:"marco",t:"人聞き悪いっすね。持ち主のいない子を、拾ってるだけっすよ。",v:"01_0167"},{w:"nina",t:"マルコ、しゃべってないで、囲みな！",v:"01_0168"},{w:null,t:"三機のドローンが、フォルンを三方から囲む。"},{w:"elly",t:"ヤマト！",v:"01_0170"},{w:null,t:"ヤマトの肩ごしに、フォルンの目が、網と二人組を見る。"},{w:"marco",t:"あー！　六枚目っす！",v:"01_0172"},{w:null,t:"ヤマト、立ち上がる。"},{w:"hero",t:"マフィンかマフィアか知らねーけど、フォルンは、さっきおれが出会った友達だ！　ぜってー渡さねー！　おまえらこそ、あっち行け！",v:"01_0174"},{w:"nina",t:"友達ねえ。その手のばんそうこう、狐にやられたんでしょ。",v:"01_0175"},{w:"nina",t:"しょうがない。口で言っても分からないようだから、力ずくで頂くことにするか。",v:"01_0176"},{w:null,t:"オリーブの林の中から、がさがさと音。"},{w:"nina",t:"林に先回りさせといて正解だったね。やれ、クマッパ！",v:"01_0178"},{w:null,t:"フォルン、ヤマトの足もとから、すっと前に出る。二本のしっぽを立てて、クマッパをにらむ。"},{w:"elly",t:"フォルンが、ヤマトの前に出た……。",v:"01_0180"},{w:"hero",f:"smile",t:"いっしょにやってくれんのか？　よし、望むところだ！　いっけー、フォルン！",v:"01_0181"},{w:null,t:"神殿の柱のかげに、市場の子どもたちが三人、しゃがんで並ぶ。"}];
GR_SC.g01_09=[{w:null,t:"柱のかげから、市場の子どもたちが走ってくる。"},{w:"x",n:"子ども1",t:"ヴィクターに、勝っちゃった！",v:"01_0239"},{w:"x",n:"子ども3",t:"泥棒狐、すげー！",v:"01_0240"},{w:"x",n:"子ども2",t:"泥棒じゃないよ、もう。ヒーローだよ。",v:"01_0241"},{w:null,t:"ニーナ、ひっくり返ったクマッパを抱き上げる。目を回したまま。"},{w:"nina",t:"よくやったよ。休みな。",v:"01_0243"},{w:null,t:"ニーナ、目を回したクマッパを、両腕でかかえ直す。"},{w:"nina",t:"覚えときな、おチビちゃん。ヴィクターに逆らって、ただで済んだやつはいないんだから。",v:"01_0245"},{w:"hero",t:"何回来たって、同じだ！　なあ、フォルン！",v:"01_0246"},{w:null,t:"フォルン、ヤマトの前を素通りして、マルコの前へ。しっぽを、ぴんと立てる。"},{w:"marco",t:"あ。",v:"01_0248"},{w:null,t:"ぽっ。マルコのお尻に、小さな火。"},{w:"marco",t:"あちちちちっ！　ニーナさーん！",v:"01_0250"},{w:"nina",t:"バカ、走るな！　置いてくよ！",v:"01_0251"},{w:null,t:"二人組、石段を転げるように逃げていく。子どもたちが、声をそろえて笑う。"},{w:null,t:"ヤマト、にやにやしながら、フォルンに手をのばす。"},{w:"hero",f:"smile",t:"やったな、フォルン！　ほら、ちょっとだけ——",v:"01_0254"},{w:null,t:"フォルン、喉の奥で、ぐるる。ヤマト、手を引っこめる。"},{w:"elly",t:"まだ、なでさせてはくれないみたいね。",v:"01_0256"},{w:"hero",t:"ちぇっ。いいよ、そのうちな。",v:"01_0257"},{w:null,t:"エリー、スーツケースを持ち上げる。"},{w:"elly",t:"さ、ホテル行こ。お姉ちゃん、ずっと待ってるから。",v:"01_0259"},{w:null,t:"二人、坂を下りはじめる。"}];
GR_SC.g01_10=[{w:null,t:"坂の下に止めた黒塗りのロボタクシー。"},{w:"marco",t:"ボスに、なんて言うっすか？　狐、とれませんでしたって言うんすか？",v:"01_0264"},{w:null,t:"ニーナ、手首の画面に、ドローンが撮った写真を出す。少年の前に立って、しっぽを立てる狐。"},{w:"nina",t:"だれにもなつかない野良が、会ったばっかりの子どもをかばって、自分から前に出た。そんな話、聞いたことないよ。",v:"01_0266"},{w:"marco",t:"それ、まずいやつっすか。",v:"01_0267"},{w:"nina",t:"まずいどころか。ボスが一番ほしがる話だよ。手ぶらで帰っても、これなら怒られずにすむってわけ。",v:"01_0268"},{w:null,t:"ニーナ、送り先を選ぶ。"}];
GR_SC.g01_11=[{w:null,t:"その夜。坂の上の、小さなホテル。",v:"01_0273"},{w:null,t:"ホテルの一階のはしの、小さな部屋。"},{w:null,t:"ヤマト、戸を開ける。"},{w:"elly",t:"その図鑑、お姉ちゃんが置いといてくれたの。「日本の子なら、きっと読むから」って。",v:"01_0276"},{w:"hero",t:"お姉ちゃんって、さっき受付にいた人？",v:"01_0277"},{w:"elly",t:"そう、アナ。このホテル、お姉ちゃんが一人でやってるの。きみの焦げた前髪見て、笑いこらえてたでしょ。",v:"01_0278"},{w:null,t:"ヤマト、図鑑をひらく。"},{w:"hero",t:"日本だけ、白いんだな。",v:"01_0280"},{w:"elly",t:"日本って、テリオン、いないんでしょ？",v:"01_0281"},{w:"hero",t:"いない。画面でしか見たことなかった。さわったのも、ガブッとやられたのも、今日が初めて。",v:"01_0282"},{w:null,t:"窓の外。ぶどう畑の柵の上に、フォルンが丸くなっている。"},{w:"elly",t:"見て。あの子、ここまでついてきてる。",v:"01_0284"},{w:"hero",t:"友達だからな。",v:"01_0285"},{w:"elly",t:"なでさせてもらえないのに？",v:"01_0286"},{w:"hero",f:"angry",t:"うっせ。",v:"01_0287"},{w:null,t:"エリー、笑って戸を閉める。"},{w:null,t:"スーツケースの中身を、ベッドにあける。"},{w:null,t:"ヤマト、戸を開けて、ろうかのエリーを呼びとめる。"},{w:"hero",t:"エリー、ちょっと見て。おれの画面に、知らないアプリが入ってる。",v:"01_0291"},{w:"elly",t:"知らないアプリ？　自分で入れたの、忘れてるだけじゃないの？",v:"01_0292"},{w:"hero",t:"入れてないって。こんなの、見たこともない。……じいちゃんかな。空港で、おれの画面いじってたし。",v:"01_0293"},{w:null,t:"アイコンを押しても、何も開かない。"},{w:null,t:"柵の上のフォルンの耳が、ヤマトではなく、手首の画面の方へ、ぴんと向く。"}];
GR_BT[1]={mid:[[{w:"nina",t:"クマッパ、つる！",v:"01_0186"},{w:"hero",t:"届いてない！　もっと近くだ、フォルン！",v:"01_0189"},{w:"elly",t:"毒！　あのつる、毒があるの！",v:"01_0191"},{w:"nina",t:"林の中は、クマッパの庭よ。入ってきたら、つるだらけ。",v:"01_0192"},{w:"hero",t:"負けんな、フォルン！　行け！　行けって！",v:"01_0193"}],[{w:"x",n:"子ども2",t:"当たった！",v:"01_0195"},{w:"hero",t:"逃げたぞ！　追え、フォルン！",v:"01_0197"},{w:"hero",t:"なにやってんだよ、行けって！",v:"01_0199"},{w:"elly",t:"ヤマト、だめ！　林の中、つるだらけだよ！",v:"01_0200"},{w:null,t:"ヤマトの口が、「行け」の形のまま止まる。"},{w:"elly",t:"ヤマト？",v:"01_0204"},{w:"hero",t:"あそこだと、火が大きくなるんだ。さっき、見た。",v:"01_0205"}],[{w:"elly",t:"え？",v:"01_0206"},{w:"hero",t:"だから、あいつ、自分であそこに行ったんだ。おれが「行け」ばっか言ってたのに。",v:"01_0207"},{w:null,t:"ヤマト、口を閉じる。"},{w:"nina",t:"出てこないなら、待つだけ。こっちは毒がある。じわじわ弱るのを待てばいい。",v:"01_0209"},{w:"marco",t:"ニーナさん、狐、首まで紫になってきたっす。",v:"01_0210"},{w:null,t:"ヤマト、身を乗り出しかける。……やめる。"},{w:"hero",t:"まだだ、フォルン。そこにいろ。",v:"01_0215"}],[{w:"nina",t:"ちっ……。",v:"01_0217"},{w:null,t:"ニーナのゴーグルが、それを見る。"},{w:"nina",t:"クマッパ、毒が切れた！　もう一回かけてきな！　そばまで行けば届く！",v:"01_0221"},{w:null,t:"ヤマトの目が、クマッパの手もとに行く。"},{w:"hero",t:"エリー、見ろ。林の外だと、つる、短い。",v:"01_0224"},{w:"elly",t:"ほんとだ……。",v:"01_0225"},{w:"hero",t:"今だ、フォルン！",v:"01_0227"},{w:"nina",t:"なにしてんの、立ちな、クマッパ！",v:"01_0230"}]],post:[{w:null,t:"クマッパ、枯れ草の上で、あおむけにひっくり返る。目がぐるぐる。"},{w:null,t:"枯れ草に火が走りかける。フォルンがしっぽをひと振りする。"},{w:"elly",f:"smile",t:"勝った……。",v:"01_0234"},{w:"hero",f:"surprised",t:"勝った！！　フォルン、勝ったぞ！　見た！？　今の見た！？",v:"01_0235"}]};
GR_EP[1]={"t": "テリオン・ワールド", "sc": [["g01_01", "語り", 0], ["g01_02", "オリーヴァ村・市場の坂（昼）", 0], ["g01_03", "坂道の追いかけっこ", 0], ["g01_04", "神殿のあとの丘", 0], ["g01_05", "同じ場所・女の子", 0], ["g01_06", "同じ場所・手のひらのオリーブ", 0], ["g01_07", "丘・ヴィクター", 0], ["g01_08", "勝負", 1], ["g01_09", "勝負のあと", 0], ["g01_10", "黒塗りのロボタクシーの中（夕方）", 0], ["g01_11", "坂の上のホテル・一階のはしの部屋（夜）", 0]]};
GR_SC.g02_01=[{w:null,t:"オリーヴァ村。坂の上のホテルの朝。",v:"02_0025"},{w:null,t:"裏のぶどう畑。"},{w:null,t:"畑のはしのベンチに、うすくて軽い、温度を保つ掛け物にくるまったヤマト。"},{w:null,t:"ベンチの前の柵の上で、フォルンが丸くなっている。"},{w:null,t:"エリーが、パンとオリーブの皿を持ってのぞきこむ。"},{w:"elly",t:"ヤマト？　まさか、ひと晩じゅうここにいたの？",v:"02_0030"},{w:"hero",t:"寝てない！　見張ってたんだよ。ヴィクター、また来るかもしれないだろ。",v:"02_0031"},{w:"elly",t:"よだれ、ついてるけど。",v:"02_0032"},{w:"hero",f:"serious",t:"……これは、夜つゆ。",v:"02_0033"},{w:null,t:"フォルン、あくびをして起き上がる。"},{w:"hero",t:"なあ、今の見た？　投げて、しっぽで焼いて、食う。かっけえ……。",v:"02_0035"},{w:"elly",t:"毎朝やってるよ、あれ。",v:"02_0036"},{w:null,t:"ヤマト、エリーの皿からオリーブを一つつまむ。"},{w:"hero",t:"おれもできる。見てて。",v:"02_0038"},{w:"elly",t:"しっぽ、ないでしょ。",v:"02_0039"},{w:"hero",t:"口でキャッチするんだよ。",v:"02_0040"},{w:null,t:"ヤマト、オリーブを高く投げる。上を向いて、口を大きく開けて待つ。"},{w:null,t:"オリーブ、ヤマトのおでこに当たって、ぽんとはねる。柵の上の、フォルンのしっぽの火に落ちる。"},{w:"elly",t:"……おいしそうに食べてるね、きみのオリーブ。",v:"02_0043"},{w:"hero",f:"serious",t:"……今のは、フォルンにあげたの。",v:"02_0044"},{w:null,t:"エリー、皿で口をかくして、肩をふるわせている。"},{w:null,t:"二階の窓が、ばんと開く。"},{w:"ana",t:"エリー！　お客さんの朝ごはん！　日本の子の分も！　早く！",v:"02_0047"},{w:"elly",t:"はーい、お姉ちゃん！",v:"02_0048"},{w:null,t:"第2話　オリーブの丘",v:"02_0050"}];
GR_SC.g02_02=[{w:null,t:"白い壁の小さな食堂。"},{w:null,t:"台所でフライパンをふるのも、運ぶのも、つぐのも、アナ一人。"},{w:"hero",t:"（パンをほおばりながら）なあ、ここ、料理を運ぶロボットいないの？　日本じゃ全部ロボットだよ。",v:"02_0058"},{w:"elly",t:"うちのロボットは、お皿洗いと掃除だけ。あとは、お姉ちゃんが一人でやってるの。",v:"02_0059"},{w:"ana",t:"（台所から）運ぶロボットまで入れたら、借りたお金、返せなくなるの！　聞こえてるからね！",v:"02_0060"},{w:null,t:"アナ、皿を三枚いっぺんに持って出てくる。"},{w:"ana",t:"きのうの前髪の子ね。明るいとこで見ると、もっとひどいわ。",v:"02_0062"},{w:"hero",t:"これ、狐に焦がされたんだよ。",v:"02_0063"},{w:"ana",t:"知ってる。村じゅうの話よ。ヴィクターとやり合って、勝ったんだって？",v:"02_0064"},{w:"hero",f:"smile",t:"勝ったよ！　フォルンがさ、根もとでぶわーって火を——",v:"02_0065"},{w:"ana",t:"はいはい、あとで聞く。冷めないうちに食べな。",v:"02_0066"},{w:null,t:"アナ、もう次の客の方へ行っている。"},{w:"hero",f:"serious",t:"……聞く気ねーじゃん。",v:"02_0068"},{w:"elly",t:"お姉ちゃん、朝はいつもああなの。",v:"02_0069"},{w:null,t:"エリーの長い髪のかげから、うす茶色の、まんまるの毛玉が、そっと顔を出す。"},{w:"hero",f:"surprised",t:"うわっ！　なにそれ、いつからいたの！？",v:"02_0071"},{w:"elly",t:"ずっといたよ。ピリポン。うちの子。きのうは、お姉ちゃんと留守番してたの。",v:"02_0072"},{w:null,t:"エリー、パンを小さくちぎって、肩のピリポンにわたす。"},{w:"hero",f:"surprised",t:"ちっちぇえ！　よろしくな、ピリ——",v:"02_0074"},{w:null,t:"ヤマトが顔を近づける。"},{w:"elly",t:"こわがりなの。知らない人の前だと、すぐかくれちゃう。",v:"02_0076"},{w:"hero",t:"なあ、さわってもいい？　ふわふわか確かめたい。",v:"02_0077"},{w:"elly",t:"だめ。とくに寝てる時は、ぜったいだめ。びりってするから。",v:"02_0078"},{w:"hero",t:"さわらねーよ。",v:"02_0079"}];
GR_SC.g02_03=[{w:null,t:"古いソファと、壁の大きな画面。"},{w:null,t:"ソファで、客のおじいさんが、空中に出したニュースの画面を読んでいる。"},{w:null,t:"エリーはカウンターでアナに何か頼まれている。"},{w:null,t:"ヤマト、カウンターのエリーを見る。"},{w:null,t:"ひざの鳥の子が、つつくのを止めて、ヤマトを見る。"},{w:"hero",t:"（小声で）ちょっとだけ。ふわふわか、確かめるだけだから。",v:"02_0087"},{w:null,t:"指先が、毛にふれる。ピリポンの目が、ぱちっと開く。"},{w:null,t:"ピリポンの毛が、ぜんぶ逆立つ。"},{w:null,t:"ヤマトの前髪が、まっすぐ上に立つ。"},{w:null,t:"ピリポン、ソファの背もたれのうしろにかくれる。"},{w:null,t:"エリーがもどってくる。"},{w:"elly",f:"serious",t:"……さわった？",v:"02_0093"},{w:"hero",t:"さわってない。",v:"02_0094"},{w:null,t:"ヤマトの前髪から、まだ、ぱちっと小さな火花。"},{w:"elly",t:"さわったでしょ。両方焦げてるもん。",v:"02_0096"},{w:"hero",f:"serious",t:"……ちょっとだけ。",v:"02_0097"},{w:"elly",t:"さっき「さわらねーよ」って言ったの、だれ？",v:"02_0098"},{w:null,t:"エリー、手をのばす。"},{w:"elly",f:"sad",t:"（ピリポンに）ごめんね。この人、勝手にさわるの。",v:"02_0100"},{w:null,t:"画面のお知らせが切りかわる。"},{w:"hero",t:"あ、あの車！　きのうのやつだ。",v:"02_0102"},{w:null,t:"アナが、カウンターから出てくる。"},{w:"ana",t:"ヴィクターよ。パン屋の猫の子も、八百屋さんの鳥の子も、あいつら。",v:"02_0104"},{w:"hero",t:"警察は？　なんで捕まえねーの？",v:"02_0105"},{w:"ana",t:"持ち主のいる子なら、警察も探してくれる。でも、持ち主のいない子は「いなくなっただけ」で終わり。八百屋さんの鳥の子だって、登録してなかったから。",v:"02_0106"},{w:"hero",t:"じゃあ、フォルンは……。",v:"02_0107"},{w:"ana",t:"野良でしょ、あの狐。さらわれても、だれも探してくれないわね。",v:"02_0108"},{w:"hero",t:"だったら、おれが持ち主になる！　登録って、どこでやんの？",v:"02_0109"},{w:"ana",t:"持ち主の登録は、十五から。あんた、いくつ。",v:"02_0110"},{w:"hero",f:"serious",t:"……十一。",v:"02_0111"},{w:"ana",t:"残念でした。",v:"02_0112"},{w:null,t:"アナ、ヤマトの肩をぽんとたたいて、台所へもどる。ヤマト、口をとがらせて、ソファにどさっと座る。"},{w:null,t:"画面が、また切りかわる。"},{w:null,t:"画面「白い都テリオン大会　参加者募集　年れい不問」。"},{w:null,t:"ヤマト、ソファから、がばっと立ち上がる。"},{w:"hero",t:"エリー、これ！　年れいにかかわらずって書いてある！",v:"02_0117"},{w:"elly",f:"serious",t:"……ほんとだ。",v:"02_0118"},{w:"hero",f:"surprised",t:"優勝したら、十一でも登録できるってことだろ！？　白い都って、どこ？",v:"02_0119"},{w:"elly",t:"アテネのこと。ここから、ずっと東だよ。車で行っても、一日じゃ着かないくらい。",v:"02_0120"},{w:"hero",t:"遠っ……。",v:"02_0121"},{w:null,t:"ヤマト、画面の「年れいにかかわらず」の字から、目をはなさない。"},{w:"elly",t:"とにかく、先におばあちゃんち、行かなきゃ。きのうから、あんたを連れてこいって言われてるの。",v:"02_0123"},{w:"hero",t:"なんで、おれなの？　会ったこともないのに。",v:"02_0124"},{w:"elly",t:"わたしも、理由は聞いてないの。行けば分かるよ。",v:"02_0125"},{w:null,t:"エリー、ヤマトの腕を引く。"},{w:null,t:"アナが、画面の横に重ねてある電子ペーパーのちらしを一枚ぬいて、ヤマトの手にねじこむ。"},{w:"ana",t:"持ってきな。お客さんの分、いっぱいあるから。……本気にするんじゃないよ。",v:"02_0128"},{w:"hero",t:"する！",v:"02_0129"},{w:"ana",t:"……でしょうね。",v:"02_0130"}];
GR_SC.g02_04=[{w:null,t:"昼。村の畑は、今も人の手で実をとる。",v:"02_0136"},{w:null,t:"白い家のあいだを、オリーブの林が段々にのぼっていく。"},{w:null,t:"ヤマト、ちらしをにぎったまま歩いている。"},{w:"hero",t:"なあ、あれ、全部、手でとってんの？　2100年だぜ？",v:"02_0139"},{w:"elly",t:"うん。人の手でとったっていうだけで、すっごく高く売れるの。遠くのお金持ちの国の人しか買えないくらい。",v:"02_0140"},{w:"hero",t:"へえ……。じゃあ、フォルンが盗んでたの、高いやつじゃん。",v:"02_0141"},{w:"elly",t:"そう。だから村の人、みんな怒ってたの。",v:"02_0142"},{w:null,t:"畑の上の道を、銀色の車が音もなく走っていく。"},{w:"hero",t:"あ、ロボタクシー！　あれ乗ってけば、白い都まですぐじゃん！",v:"02_0144"},{w:"elly",t:"乗らないよ。あれ、乗った人がいつどこに行ったか、ぜんぶ記録されるの。",v:"02_0145"},{w:"hero",t:"それが、なに？",v:"02_0146"},{w:"elly",t:"その記録、お金で買ってる人たちがいるんだって。お姉ちゃんが言ってた。",v:"02_0147"},{w:"hero",f:"serious",t:"……ヴィクター？",v:"02_0148"},{w:null,t:"エリー、うなずく。"},{w:null,t:"二人のうしろを、フォルンが段々の石垣の上を伝ってついてくる。"},{w:null,t:"畑のおばさんが、フォルンに気づいて手を止める。"},{w:"x",n:"畑のおばさん",t:"あっ、泥棒狐——",v:"02_0152"},{w:null,t:"おばさん、言いかけて、エリーの方を見る。"},{w:"elly",t:"おばさん、この子、きのうヴィクターを追っぱらったんだよ。",v:"02_0154"},{w:"x",n:"畑のおばさん",t:"聞いたよ。……しょうがないね。一個だけだよ。",v:"02_0155"},{w:null,t:"おばさん、作業着の胸ポケットからオリーブを一つ出して、石垣の上に置く。フォルン、においをかいで、しっぽの火の上で転がしてから、かりっと食べる。"},{w:"x",n:"畑のおばさん",t:"焼いて食べるのかい。ぜいたくな泥棒だこと。",v:"02_0157"},{w:null,t:"おばさん、口のはしを上げて、また実をしごきはじめる。"}];
GR_SC.g02_05=[{w:null,t:"村のいちばん上の丘。",v:"02_0161"},{w:null,t:"オリーブ畑のまん中に、石でかこんだ小さなため池。"},{w:null,t:"フォルン、池のふちへ。水に顔を近づける。"},{w:"hero",t:"はは、びびってやんの。……あれ？",v:"02_0164"},{w:null,t:"ヤマト、池と、フォルンのしっぽを見くらべる。"},{w:"hero",t:"今、水のそばで、火がちっちゃくなったよな。",v:"02_0166"},{w:"elly",t:"炎の子は、水がきらいなんだよ。図鑑にのってなかった？",v:"02_0167"},{w:"hero",t:"まだ半分しか読んでねーもん。",v:"02_0168"},{w:"elly",t:"この池の水で、丘の畑、ぜんぶやってるの。雨、ちょっとしかふらないから。",v:"02_0169"},{w:null,t:"池の向こう、丘の頂上に、白い大きな建物のあと。"},{w:"hero",t:"あれ、なに？　でっけー。",v:"02_0171"},{w:"elly",t:"昔の研究所。おばあちゃん、若いころ、あそこで働いてたんだって。",v:"02_0172"},{w:"hero",t:"なんの研究？",v:"02_0173"},{w:"elly",t:"聞いても、「むかしむかしの話」しか言わないの。入っちゃだめって、それだけ。",v:"02_0174"},{w:null,t:"くずれた丸屋根のすきまから、空が見える。"},{w:null,t:"フォルンの耳が、建物の方へ、ぴくっと動く。それから、すぐ、ヤマトの足もとを通って先へ行く。"}];
GR_SC.g02_06=[{w:null,t:"丘の向こうの、石の家。",v:"02_0179"},{w:null,t:"小さな石の家。"},{w:"elly",t:"おばあちゃーん！　つれてきたよ！",v:"02_0181"},{w:"oba",t:"はいはい。……あんたが、ヤマトだね。",v:"02_0182"},{w:"hero",t:"こんにちは！　ヤマトです！",v:"02_0183"},{w:null,t:"おばあさん、ヤマトの顔をじっと見る。"},{w:"oba",t:"……両方、焦げてるね。",v:"02_0185"},{w:"hero",t:"こっちは狐で、こっちはピリポン。",v:"02_0186"},{w:"oba",t:"あら。あの子、寝てる時にさわると、怒るんだよ。",v:"02_0187"},{w:"elly",t:"ほらね！",v:"02_0188"},{w:"hero",f:"serious",t:"……先に言ってくれよ。",v:"02_0189"},{w:null,t:"おばあさん、くっくっと笑って、家の中へ入っていく。"},{w:null,t:"家の中。研究の記録の板と、データの箱が、どこにでも積んである。"},{w:null,t:"棚のすみの小さな画面に、昔の絵本の一ページ。"},{w:null,t:"ヤマトの目は、すぐ、となりの写真の画面に行く。"},{w:"hero",t:"これ、さっきの研究所？　この女の人、おばあちゃん？",v:"02_0194"},{w:"oba",t:"さあ、どうだったかね。むかしむかしの話だよ。",v:"02_0195"},{w:null,t:"おばあさんが、お茶を三つ持ってくる。"},{w:"oba",t:"きのうの夜、アナから電話があったよ。ヴィクターを追い返したんだって？",v:"02_0197"},{w:"hero",t:"うん！　でも、ニーナってやつが「覚えときな」って。",v:"02_0198"},{w:"oba",t:"あの連中は、ねらった子はあきらめないよ。今度は、もっと大勢で来るね。",v:"02_0199"},{w:null,t:"ヤマト、くしゃくしゃのちらしをテーブルに置く。"},{w:"hero",t:"だから、これ。優勝したら、フォルンの持ち主になれる。持ち主になったら、さらわれても、みんな探してくれるんだろ。",v:"02_0201"},{w:null,t:"おばあさん、ちらしの「年れいにかかわらず」の字を見る。それから、ヤマトの手を見る。"},{w:"oba",t:"……エリー。一緒に行っておいで。",v:"02_0203"},{w:"elly",t:"うん。いいよ。",v:"02_0204"},{w:null,t:"エリー、クッキーをかじりながら返事をする。"},{w:"hero",f:"surprised",t:"え、いいの！？　白い都、遠いんだろ？",v:"02_0206"},{w:"elly",t:"遠いよ。でも、行ってみたかったんだ。わたし、村の外、ほとんど出たことないから。",v:"02_0207"},{w:"oba",t:"あしたの昼は、ホテルにいない方がいいね。",v:"02_0208"},{w:"elly",t:"お昼なら、ちょうど競技場の案内の仕事あるよ。",v:"02_0209"},{w:"oba",t:"じゃあ、その仕事に行っておいで。",v:"02_0210"},{w:"elly",t:"今夜、出る？",v:"02_0211"},{w:null,t:"窓の外。庭の洗濯物の上を、黒いドローンが一台、ゆっくり横切る。"},{w:"oba",t:"（空を、あごでさす）ほら。ヴィクターのドローンだよ。きのうの夜から、ずっと村の上を回ってる。今夜はだめ。……あしたの夜。森の道なら、上から見えない。",v:"02_0213"},{w:null,t:"おばあさん、手首の画面を指で二回たたく。"},{w:"oba",t:"今、あんたのスマホに送っといたよ。消すんじゃないよ。",v:"02_0215"},{w:"elly",t:"（カバンからスマホを出して）なにこれ？　ファイルが一個だけ届いてるけど、中身は何なの？",v:"02_0216"},{w:"oba",t:"開いても、あんたには分かんないよ。古いもんだからね。",v:"02_0217"},{w:null,t:"エリー、スマホをカバンにしまう。"},{w:"oba",t:"それとね、ついでに、あのヴィクターって連中、ちょっと、こらしめておいで。",v:"02_0219"},{w:"hero",f:"surprised",t:"ついで！？",v:"02_0220"},{w:"elly",t:"いいよー。",v:"02_0221"},{w:"hero",f:"surprised",t:"いいの！？　相手、マフィアだぞ！？",v:"02_0222"},{w:"elly",t:"だって、パン屋さんの猫の子、まだ帰ってきてないもん。",v:"02_0223"},{w:null,t:"ヤマト、身を乗り出す。"},{w:null,t:"おばあさんの手が、お茶のカップを持ったまま、止まる。"},{w:null,t:"時計の形の、小さなアイコン。"},{w:"hero",f:"sad",t:"あ、ごめんなさい。これ、じいちゃんが勝手に入れたっぽいアプリで、押しても開かないんです。",v:"02_0227"},{w:null,t:"おばあさん、カップを置く。いつもの顔。"},{w:"oba",t:"……古い形の時計だね。消さずに、大事にしな。",v:"02_0229"},{w:null,t:"窓の外。庭のオリーブの木の根もとで、フォルンが、しっぽの火で落ちた実を焼いている。"},{w:null,t:"おばあさん、フォルンを見る。それから、棚の写真の、焦げたパンをかかげた若い男を、ちらっと見る。"}];
GR_SC.g02_07=[{w:null,t:"その夜。",v:"02_0234"},{w:null,t:"ヤマト、リュックにものをつめている。"},{w:null,t:"図鑑の終わりのページの、ギリシャの地図。"},{w:null,t:"戸口に、パジャマのエリー。"},{w:"elly",t:"その線、海の上、通ってるよ。",v:"02_0238"},{w:"hero",t:"泳ぐ。",v:"02_0239"},{w:"elly",t:"フォルン、水きらいなのに？",v:"02_0240"},{w:"hero",f:"serious",t:"……じゃあ、回る。",v:"02_0241"},{w:"elly",t:"出るのは、あしたの夜だからね。お姉ちゃんには、ないしょ。言ったら、ぜったい止めるから。",v:"02_0242"},{w:"hero",t:"分かった。",v:"02_0243"},{w:null,t:"エリー、自分の部屋へもどりかけて、止まる。"},{w:"elly",t:"それと、ヤマト。ピリポンに、もう勝手にさわらないでね。",v:"02_0245"},{w:"hero",t:"さわらねーよ。",v:"02_0246"},{w:null,t:"エリーの肩のピリポンが、ヤマトを見て、ぱちっ。"},{w:null,t:"ヤマト、ちりちりの前髪を手で押さえる。"}];
GR_SC.g02_08=[{w:null,t:"同じころ、遠くの丘。",v:"02_0251"},{w:null,t:"丘の上。若い男が一人、古い小さな望遠鏡で星を見ている。顔は半分しか見えない。"},{w:null,t:"男の手首の画面が鳴る。"},{w:"victor",n:"ヴィクター（画面の声）",t:"アレク、仕事だ。オリーヴァ村で、狐を一匹つかまえてこい。ニーナとマルコが、しくじったんだ。",v:"02_0254"},{w:null,t:"画面のすみに、少年の前に立って、しっぽを立てる狐の写真。"},{w:"victor",n:"ヴィクター（画面の声）",t:"狐には、子どもがくっついている。じゃまなら、子どもごと連れてきていい。",v:"02_0256"},{w:null,t:"男、望遠鏡から目を離さないまま、写真を開かずに、画面を指で消す。"},{w:null,t:"それから、ゆっくり望遠鏡を下ろす。"}];
GR_EP[2]={"t": "オリーブの丘", "sc": [["g02_01", "ホテルの裏・ぶどう畑のはし（朝）", 0], ["g02_02", "ホテルの食堂（朝）", 0], ["g02_03", "ロビー（朝）", 0], ["g02_04", "村の道（昼）", 0], ["g02_05", "丘の上・ため池と研究所あと（昼）", 0], ["g02_06", "おばあさんの家（昼）", 0], ["g02_07", "ホテルのヤマトの部屋（夜）", 0], ["g02_08", "どこかの丘（夜）", 0]]};
GR_SC.g03_01=[{w:null,t:"まっ暗な石の通路。"},{w:null,t:"つきあたりの壁のあたりから、大きな生き物の寝息のような、低い音。"},{w:null,t:"天井から、砂がひとすじ、寝息に合わせて、さらさらと落ちる。"},{w:null,t:"第3話　古代の競技場",v:"03_0019"}];
GR_SC.g03_02=[{w:null,t:"次の日の朝。",v:"03_0025"},{w:null,t:"白い小さなホテルの玄関。"},{w:null,t:"エリー、小さな白い肩かけカバン。"},{w:"hero",t:"なあ、なんで昼、ホテルにいちゃだめなんだ？",v:"03_0028"},{w:"elly",t:"おばあちゃんが言ってたでしょ。ヴィクターが来るかもって。",v:"03_0029"},{w:"hero",t:"来たって平気だよ。おれとフォルンで、やっつけてやる。",v:"03_0030"},{w:"elly",t:"おとといだって、ぎりぎりだったのに？",v:"03_0031"},{w:"hero",t:"……あれは、わざとぎりぎりにしたんだよ。作戦だ。",v:"03_0032"},{w:null,t:"玄関から、アナが、朝ごはんを作っていたフライパンを持ったまま出てくる。"},{w:"ana",t:"エリー、仕事なんだから、ちゃんと案内しなさいよ。お客さん、迷子にしないでね。",v:"03_0034"},{w:"elly",t:"はーい。",v:"03_0035"},{w:"ana",t:"ヤマトは……前髪、まだ焦げてるね。",v:"03_0036"},{w:null,t:"ヤマト、前髪を両手で押さえる。"},{w:null,t:"玄関から、ドイツ人の夫婦が出てくる。"},{w:"elly",t:"（夫婦に、ドイツ語で何か言う。夫婦が笑う）",v:"03_0039"},{w:"hero",f:"serious",t:"……今の、何語？",v:"03_0040"},{w:"elly",t:"ドイツ語だよ。あのお客さん、ドイツから来たんだって。",v:"03_0041"},{w:"hero",t:"エリーって、何ヶ国語しゃべれんの？",v:"03_0042"},{w:"elly",t:"ちょっとだけなら、たくさん話せるよ！",v:"03_0043"},{w:null,t:"塀の上で、フォルンがあくびをする。"}];
GR_SC.g03_03=[{w:null,t:"村の外れ。三千年前の競技場。",v:"03_0047"},{w:null,t:"オリーブの林を抜けると、石を積んだ古い入口のアーチ。"},{w:null,t:"観光客がたくさん。"},{w:"hero",f:"serious",t:"……え、ここ？　ただの広場じゃん。",v:"03_0050"},{w:"x",n:"案内のロボット",t:"ここは、世界で最初のオリンピックが開かれた場所です。",v:"03_0051"},{w:"hero",f:"serious",t:"……マジか。",v:"03_0052"},{w:"elly",t:"ほらね。すごい所だって、言ったでしょ。",v:"03_0053"},{w:null,t:"アーチの下は、すりへった石だたみ。"},{w:null,t:"エリー、夫婦の前に立つ。案内の仕事の顔。"},{w:"elly",t:"（夫婦に）この走る所の長さはね、昔の、すっごい力持ちの人の、足の大きさ六百こ分なんだって。",v:"03_0056"},{w:null,t:"夫婦、うなずいて、向こうのはしまでを見わたす。"},{w:"hero",t:"足六百こ？　じゃあ、おれが数えてやる。",v:"03_0058"},{w:null,t:"ヤマト、スタートの線につま先を合わせる。"},{w:"hero",t:"いち。に。さん……。",v:"03_0060"},{w:null,t:"……足が、だんだん速くなる。"},{w:"hero",f:"serious",t:"……ひゃくはち。ひゃくきゅう……。",v:"03_0062"},{w:null,t:"ふり返る。まだ、走る所の五分の一も来ていない。"},{w:"hero",f:"serious",t:"……そいつ、足、何センチあんの？",v:"03_0064"},{w:"elly",t:"ヤマトの足が小さいんだよ。",v:"03_0065"},{w:"hero",t:"小さくねーよ！　おれ、クラスで二番目にでかいんだぞ！",v:"03_0066"},{w:"elly",t:"クラス、何人？",v:"03_0067"},{w:"hero",f:"serious",t:"……六人。",v:"03_0068"},{w:null,t:"ドイツ人の夫婦が、くすくす笑う。"}];
GR_SC.g03_04=[{w:null,t:"ヤマト、走ってもどってくる。"},{w:"hero",t:"エリー、かけっこで勝負しようぜ。向こうの端まで。",v:"03_0073"},{w:"elly",t:"えー。わたし、仕事中なんだけど。",v:"03_0074"},{w:"hero",t:"あ、負けるのがこわいんだ。",v:"03_0075"},{w:"elly",t:"……いいよ。そこまで言うなら、走ってあげる。",v:"03_0076"},{w:null,t:"エリー、スタートの線に並ぶ。"},{w:"elly",t:"よーい……。",v:"03_0078"},{w:null,t:"ヤマト、前のめりになる。"},{w:null,t:"ヤマト、とび出す。"},{w:"elly",t:"まだ「ドン」って言ってないよ。",v:"03_0081"},{w:null,t:"ヤマト、三歩目でふり返る。"},{w:"hero",t:"え、まだ——",v:"03_0083"},{w:null,t:"ふり返ったまま足がもつれて、顔から土につっこむ。"},{w:"elly",t:"ドン。",v:"03_0085"},{w:null,t:"エリーが、のんびり走りだす。"},{w:"hero",t:"ずりーぞ！　今のは、なしだろ！",v:"03_0087"},{w:null,t:"ヤマト、とび起きて追いかける。"},{w:null,t:"観光客から、ぱらぱらと拍手。"},{w:"hero",t:"（息を切らして）……おれ、二番。",v:"03_0090"},{w:"elly",t:"ヤマトは三番だよ。一番は、フォルンだもん。",v:"03_0091"}];
GR_SC.g03_05=[{w:null,t:"ドイツ人のだんなさんが、カメラを持って、ヤマトの方へまっすぐ歩いてくる。"},{w:null,t:"ヤマト、土だらけの顔をそででふく。"},{w:null,t:"だんなさん、ヤマトの手にカメラをのせる。"},{w:"hero",f:"serious",t:"……え。",v:"03_0097"},{w:"elly",t:"フォルンと、三人で撮りたいんだって。",v:"03_0098"},{w:"hero",t:"おれは？",v:"03_0099"},{w:"elly",t:"ヤマトは、撮る人。",v:"03_0100"},{w:null,t:"ヤマト、夫婦とフォルンの方を向いて、カメラをかまえる。"}];
GR_SC.g03_06=[{w:null,t:"正午。",v:"03_0107"},{w:null,t:"枯れかけた草の土手。"},{w:null,t:"エリー、アイスを食べている。"},{w:null,t:"エリーのカバンの中で、スマホが、ぴこんと鳴る。"},{w:"elly",f:"serious",t:"……ヴィクターが、ホテルに来たって。",v:"03_0111"},{w:"hero",t:"ほんとに来たんだ。……アナさん、だいじょうぶ？",v:"03_0112"},{w:"elly",t:"お姉ちゃんなら、だいじょうぶ。フライパン、持ってたもん。",v:"03_0113"},{w:"hero",t:"フライパンで勝てんの？",v:"03_0114"},{w:"elly",t:"勝てるよ。お姉ちゃん、怒ると、すっごくこわいんだもん。",v:"03_0115"},{w:null,t:"エリー、スマホに「わかった」と打って、カバンにしまう。"},{w:null,t:"ヤマト、手首の画面を見る。"},{w:"hero",t:"あ、じいちゃんのアプリが光ってる。きのうは、押しても開かなかったのに。",v:"03_0118"},{w:"elly",t:"今度は、開くんじゃない？",v:"03_0119"},{w:"hero",t:"押してみる。……また、何も起きなかったりして。",v:"03_0120"},{w:null,t:"ヤマト、アイコンを、指でとんと押す。"},{w:null,t:"手首の画面から、うすい光が宙に広がって、地図の形になる。"},{w:null,t:"地図の上に、小さな光の印が、四つ。"},{w:"hero",f:"surprised",t:"うわ、うわ、なにこれ！　じいちゃんのアプリ、こんなことできたの！？",v:"03_0124"},{w:"elly",t:"ここ、ネットもつながってないのに……。",v:"03_0125"},{w:null,t:"印の一つは、今いる場所と重なっている。"},{w:null,t:"もう一つは、村のいちばん上の丘。"},{w:"elly",t:"あ、そこ、おばあちゃんが前に働いてた所の近くだよ。",v:"03_0128"},{w:null,t:"残りの二つは、地図のずっとはし。"},{w:"hero",t:"この真下って……下に何かあんの？",v:"03_0130"},{w:null,t:"ヤマト、土手のすそを見る。"},{w:"hero",f:"serious",t:"……ちょっと、中を見てくるだけ。",v:"03_0132"},{w:"elly",t:"ちょっとって、どれくらい？",v:"03_0133"},{w:"hero",t:"入口から、見えるとこまで。",v:"03_0134"},{w:"elly",t:"中、まっ暗だよ。",v:"03_0135"},{w:"hero",t:"じゃあ、見えるとこまで、全部。",v:"03_0136"},{w:null,t:"フォルンが、先に柵の下をくぐる。"}];
GR_SC.g03_07=[{w:null,t:"競技場の、真下。",v:"03_0140"},{w:null,t:"ひんやりした石の通路。フォルンのしっぽの火が明かりになる。"},{w:"elly",t:"ヤマト、もう、見えるとこ、過ぎてるよ。",v:"03_0142"},{w:"hero",t:"フォルンが明るいから、ずっと見えてる。",v:"03_0143"},{w:null,t:"つきあたりに、大きな石の扉。"},{w:null,t:"扉のふちに、細かい文字がびっしり。"},{w:"hero",f:"serious",t:"……でっか。",v:"03_0146"},{w:"elly",f:"serious",t:"……これ、古いギリシャの字だ。",v:"03_0147"},{w:null,t:"エリー、文字を指でなぞって、声に出して読む。"},{w:"elly",f:"surprised",t:"えっとね……ここで寝てる子、起こさないでね、だって。",v:"03_0149"},{w:null,t:"エリーの声が、通路にひびいて、消える。"},{w:null,t:"……足の下の、ずっと深い所から、低い音が一つだけ返ってくる。"},{w:null,t:"天井から、砂がひとすじ落ちる。"},{w:null,t:"ヤマトは角を見上げている。"},{w:"elly",t:"……ヤマト。なんだか、いやな感じがする。今日は、もう帰ろ。",v:"03_0158"},{w:"hero",f:"serious",t:"……うん。",v:"03_0159"}];
GR_SC.g03_08=[{w:null,t:"来た通路をもどる。"},{w:"x",n:"若い男",t:"立ち入り禁止って、入口の表示に出てただろ。",v:"03_0163"},{w:"hero",t:"読めなかった。",v:"03_0164"},{w:"x",n:"若い男",t:"その下に、英語でも同じことが書いてある。",v:"03_0165"},{w:"hero",t:"英語も読めない。",v:"03_0166"},{w:"x",n:"若い男",t:"字が読めなくても、絵を見れば分かるだろ。×がついてる。",v:"03_0167"},{w:null,t:"男、あごで、入口の表示の×の絵をさす。"},{w:"hero",f:"serious",t:"……絵は、見てない。",v:"03_0169"},{w:"elly",t:"わたし、ぜんぶ読めたよ。奥の扉のも。",v:"03_0170"},{w:null,t:"男、だまる。"},{w:null,t:"男の目が、ヤマトの足もとのフォルンに止まる。"},{w:"x",n:"若い男",t:"その狐を、ここに置いていけ。",v:"03_0173"},{w:"hero",t:"やだね。お前、だれだよ。",v:"03_0174"},{w:null,t:"男、手首を返す。"},{w:"elly",f:"serious",t:"……この人、ヴィクターだ。",v:"03_0176"},{w:"hero",t:"フォルンは、だれのでもねーよ。お前らのでも、おれのでもない。",v:"03_0177"},{w:"x",n:"若い男",t:"だから、おれたちがもらっていく。",v:"03_0178"},{w:null,t:"男、手首の画面を指で一回たたく。通路の出口の明るい四角に、黒いドローンが一台、すうっと下りてくる。"},{w:null,t:"フォルンのしっぽの火が、ぼっと大きくなる。"},{w:null,t:"出口の外から、人の声。"},{w:"x",n:"案内のロボット",t:"（出口から）そちらは、立ち入り禁止です。",v:"03_0182"},{w:null,t:"男、出口の人だかりを見る。"},{w:"x",n:"若い男",t:"……今日は、人が多すぎるな。",v:"03_0184"},{w:null,t:"男、画面をもう一回たたく。"},{w:null,t:"男、二人とフォルンの横をすりぬけて、オリーブの林の方へ出ていく。"},{w:"elly",f:"serious",t:"……今の人、こわかった。",v:"03_0187"},{w:"hero",t:"……でも、あいつのワニ、あごが、ちょっと曲がってた。",v:"03_0188"},{w:"elly",t:"そこ見てたの？",v:"03_0189"},{w:"hero",t:"うん、ちゃんと見てた。",v:"03_0190"},{w:null,t:"林の入口で、男が一度だけふり返る。"}];
GR_EP[3]={"t": "古代の競技場", "sc": [["g03_01", "地下（だれもいない）", 0], ["g03_02", "ホテルの前（朝）", 0], ["g03_03", "古代の競技場（昼前）", 0], ["g03_04", "スタートの線", 0], ["g03_05", "記念撮影", 0], ["g03_06", "土手の上（正午）", 0], ["g03_07", "地下の扉", 0], ["g03_08", "通路の出口", 0]]};
GR_SC.g04_01=[{w:null,t:"同じ日の夕方。村の裏の森。",v:"04_0029"},{w:null,t:"小川べりの平たい岩に、背の高い若い男が一人、ひざを立てて座っている。"},{w:null,t:"小川の中を、頭に卵のからをかぶった緑のワニの子が、ぐるぐる回って泳いでいる。"},{w:null,t:"ワニの子が、岸の白っぽい乾いた石の上へ上がる。"},{w:null,t:"男、かばんから、やわらかく煮た魚の包みを出す。"},{w:null,t:"手首の画面が鳴る。"},{w:"victor",n:"ヴィクター（画面の声）",t:"アレク。昼の競技場は、どうだった。狐は取れたのか。",v:"04_0035"},{w:"alek",t:"いえ、まだです。観光客が多すぎて、あそこで手を出したら目立ちます。だから、今夜、森で待ち伏せします。",v:"04_0036"},{w:"victor",n:"ヴィクター（画面の声）",t:"それでいい。今回は、狐と一緒に、あの子どもも連れてこい。",v:"04_0037"},{w:"alek",t:"子どもも、ですか？　おれが聞いていたのは、狐を一匹連れてくる仕事だけです。子どもまで連れていく理由は、何なんですか。",v:"04_0038"},{w:"victor",n:"ヴィクター（画面の声）",t:"理由は、お前が知らなくていい。言われたとおりにやれ。",v:"04_0039"},{w:"alek",t:"子どもを連れて歩けば、どうしても目立ちます。騒がれたら、仕事がやりにくくなりますよ。",v:"04_0040"},{w:"victor",n:"ヴィクター（画面の声）",t:"面倒でも、やれ。……忘れるなよ。そのワニに入れたチップは、こっちでいつでも止められるんだからな。",v:"04_0041"},{w:null,t:"通話が切れる。"},{w:null,t:"ワニの子が、男のひざに、ぬれた頭をのせる。"},{w:null,t:"男、ワニの子の頭に手を置く。"},{w:null,t:"第4話　夜の森",v:"04_0046"}];
GR_SC.g04_02=[{w:null,t:"その夜。",v:"04_0052"},{w:null,t:"ホテルの裏口の戸が、そっと開く。"},{w:"hero",t:"……エリー、その手に持ってる、でっかいの、なに？",v:"04_0054"},{w:"elly",t:"虫よけだよ。夜の森って、虫がいっぱいいるから、これがないと顔じゅう刺されちゃうんだもん。",v:"04_0055"},{w:"hero",t:"でっか。そんなにあったら、一年分くらいあるだろ。",v:"04_0056"},{w:"elly",t:"ううん、これで一晩分だよ。この森の虫、すごいんだから。",v:"04_0057"},{w:null,t:"エリー、戸のすきまに、うすい電子メモをはさむ。"},{w:"hero",t:"「ちょっと出かけます」って書いて、白い都まで行くの？　ちょっとどころじゃないだろ。",v:"04_0059"},{w:"elly",t:"いいの。お姉ちゃん、長い字は読まないから、短く書いた方が、ちゃんと読んでくれるんだもん。",v:"04_0060"},{w:null,t:"塀の上から、フォルンが、とん、と下りてくる。"}];
GR_SC.g04_03=[{w:null,t:"ぶどう畑を抜けた先の、暗い森。"},{w:null,t:"かえるの声。"},{w:"elly",t:"この道なら、木の枝にかくれて、空のドローンから見えないんだって。だから、この道にしなさいって、おばあちゃんが言ってた。",v:"04_0066"},{w:"hero",t:"ドローンって、まだ村の上を回ってんの？　もう、あきらめたかと思ってた。",v:"04_0067"},{w:"elly",t:"ううん、まだいるよ。夕方も、三台いたもん。",v:"04_0068"},{w:null,t:"光る板のまわりに、羽虫がわっと集まる。"},{w:"hero",t:"うわ、うわ、来んな！　虫、こっち来んなって！",v:"04_0070"},{w:null,t:"エリー、スプレーをかまえて、ぷしゅー。"},{w:"hero",t:"おれにかけんなよ！　目にしみるだろ！",v:"04_0072"},{w:"elly",t:"だって、ヤマトの頭に、虫がいっぱいついてたんだもん。",v:"04_0073"},{w:null,t:"フォルンだけは、森の奥をじっと見ている。耳が前を向いている。"},{w:null,t:"小川べりの平たい岩。"},{w:null,t:"ヤマト、光る板を頭の上にかかげて、腰をひねったまま、止まる。"},{w:"alek",t:"……そこで、何をしてるんだ。さっきから、ずっと変な動きをしてるけど。",v:"04_0077"},{w:"hero",t:"……虫をはらってたんだよ。明かりに集まってきて、うっとうしかったから。",v:"04_0078"},{w:"alek",t:"虫をはらってるようには見えなかった。どう見ても、踊ってただろ。",v:"04_0079"},{w:"hero",t:"……はらいながら、ちょっとだけ踊ってた。悪いかよ。",v:"04_0080"},{w:null,t:"ヤマト、光る板を下ろす。顔の前の最後の一匹を、手ではらう。"},{w:"hero",t:"……お前、昼に競技場にいたやつだろ。いつから、ここにいたんだよ。",v:"04_0082"},{w:"alek",t:"夕方から、ずっとここで待ってた。お前らがこの森に来るのは、分かってたからな。",v:"04_0083"},{w:"elly",t:"なんで、わたしたちがこの道を通るって分かったの？　だれにも言ってないのに。",v:"04_0084"},{w:"alek",t:"昼の道は、どこもカメラだらけだ。空にはドローンも飛んでる。狐を連れて、だれにも見られずに村を出るなら、夜のこの森を通るしかない。",v:"04_0085"},{w:null,t:"男、望遠鏡から目をはなさない。"},{w:"hero",f:"serious",t:"……さっきから、望遠鏡で何を見てんの？",v:"04_0087"},{w:"alek",t:"星を見てる。今夜は、空がよく晴れてるからな。",v:"04_0088"},{w:"hero",t:"星って、どの星だよ。いっぱいあるじゃん。",v:"04_0089"},{w:"alek",t:"……どの星かは、お前に教える必要はない。",v:"04_0090"},{w:"hero",t:"なんだよ、それ。教えてくれたっていいだろ！",v:"04_0091"},{w:null,t:"男、望遠鏡の筒をていねいにちぢめて、かばんにもどす。"}];
GR_SC.g04_04=[{w:"alek",t:"その狐を、こっちに渡せ。おれは、そのためにここで待ってたんだ。",v:"04_0095"},{w:"hero",t:"やだね。フォルンは、だれにも渡さないって決めてんだよ。",v:"04_0096"},{w:"alek",t:"それと、お前もおれと一緒に来てもらう。",v:"04_0097"},{w:"hero",t:"……は？　おれ？　なんで、おれまで行かなきゃいけないんだよ。",v:"04_0098"},{w:"elly",t:"そうだよ。ヤマトまで連れていって、どうするつもりなの？",v:"04_0099"},{w:"alek",t:"理由は、おれも知らない。上から、そう言われただけだ。",v:"04_0100"},{w:"hero",t:"上って、ヴィクターのことだろ。フォルンをさらって、どこかに売るつもりなんだろ。",v:"04_0101"},{w:"alek",t:"……それを決めるのは、おれじゃない。おれは、言われたものを運ぶだけだ。",v:"04_0102"},{w:"hero",t:"自分で決めてなくても、手伝ってんなら同じじゃん！",v:"04_0103"},{w:null,t:"男、だまる。"},{w:"elly",t:"その子も、ヴィクターのお仕事、手伝わされてるの？　なんだか、かわいそう。",v:"04_0105"},{w:"alek",t:"……こいつは、この仕事とは関係ない。だから、こいつのことは言うな。",v:"04_0106"},{w:"hero",t:"関係なくねーだろ。いつも一緒にいるんだから、お前の相棒だろ。",v:"04_0107"},{w:"alek",t:"……話は、もう終わりだ。網を使っても、どうせその狐が燃やすんだろ。ニーナとマルコから聞いてる。だから、勝負で決める。おれが勝ったら、狐とお前を連れていく。",v:"04_0108"},{w:"hero",f:"smile",t:"じゃあ、おれが勝ったら、どうすんだよ。",v:"04_0109"},{w:"alek",t:"……おれは、黙って帰る。上には、「森にはだれもいなかった」と報告する。",v:"04_0110"},{w:null,t:"男の目が、一瞬だけ、ヤマトの顔に止まる。それから、はなれる。"},{w:"elly",t:"ヤマト、だめだよ。相手はヴィクターなんだよ。何をしてくるか、分からないもん。",v:"04_0112"},{w:"hero",t:"逃げたって、どうせまた追っかけてくるんだろ。だったら、ここで勝って終わらせる。",v:"04_0113"},{w:null,t:"エリー、しゃがんで、ワニの子の頭の卵のからを見る。"},{w:"elly",t:"（ワニの子に）こんばんは、タマゴちゃん。頭のから、かわいいね。",v:"04_0115"},{w:"alek",t:"……こいつは、タマゴじゃない。ちゃんと、名前がある。",v:"04_0116"},{w:"elly",t:"じゃあ、なんていう名前なの？　教えてよ。",v:"04_0117"},{w:"alek",t:"……名前は、あとで教える。お前らが、おれに勝ったらな。",v:"04_0118"}];
GR_SC.g04_05=[{w:null,t:"ヤマト、光る板を手前の切り株の上に置く。"},{w:null,t:"右を、小川が奥から手前へまっすぐ流れている。"},{w:null,t:"男、ワニの子を小川に放す。"},{w:"hero",f:"smile",t:"（エリーに）フォルンは、木の下で戦わせる。おととい、それで勝ったんだ。木の根もとだと、フォルンの火が、でかくなるんだよ。",v:"04_0124"},{w:"elly",f:"serious",t:"……うん、わかった。",v:"04_0125"},{w:null,t:"エリーは、小川を見ている。"},{w:null,t:"エリーの肩のピリポンが、エリーの髪のかげで、ぶるぶる震えている。"},{w:"elly",t:"ピリポン。こわかったら、わたしのそばにいて。それだけでいいから。",v:"04_0128"},{w:null,t:"ピリポン、エリーの腕をつたって、足もとの草の上に、ぽてっと下りる。"},{w:"alek",t:"……二体で来るのか。別に、かまわない。どっちにしても、結果は同じだ。",v:"04_0130"},{w:null,t:"フォルン、大きな木の根もとへ歩いていく。しっぽの火が、ぼっとふくらむ。"},{w:"alek",t:"準備ができたなら、いつでも来い。",v:"04_0132"}];
GR_SC.g04_07=[{w:null,t:"ピリポン、固まっている。"},{w:"elly",t:"すごいよ、ピリポン。こわかったのに、よくがんばったね。",v:"04_0206"},{w:null,t:"アレク、ひっくり返ったワニの子のそばにひざをつく。曲がったあごに、手をそえる。"},{w:null,t:"耳のうしろのうろこのすき間から、小さなチップが、ころっと落ちる。"},{w:"elly",t:"その黒いの、なに？　その子の耳から、落ちてきたよね。",v:"04_0209"},{w:"alek",t:"ヴィクターのチップだ。これが入ってると、こいつがどこにいても、向こうに居場所が分かる。……向こうの気分ひとつで、こいつを動けなくすることもできる。",v:"04_0210"},{w:"elly",t:"止めるって……どういうこと？",v:"04_0211"},{w:"alek",t:"体が固まって、動けなくなるんだ。息をするだけで、何もできない。",v:"04_0212"},{w:"hero",f:"serious",t:"……でも、それ、真ん中から割れてるじゃん。",v:"04_0213"},{w:"alek",t:"……ああ。さっきの雷で、割れたんだろうな。",v:"04_0214"},{w:null,t:"乾いた草の上で、ワニの子の背中のうろこが、白っぽくかわいていく。"},{w:null,t:"ヤマト、小川へ走る。"},{w:"alek",t:"……お前、何をしてるんだ。そいつは、さっきまでお前の敵だったんだぞ。",v:"04_0217"},{w:"hero",t:"だって、こいつ、体がかわいて苦しそうじゃん。敵とか、もう関係ないだろ。",v:"04_0218"},{w:null,t:"アレク、それを見ている。割れたチップをにぎった手が、ひざの上で止まっている。"},{w:null,t:"エリーも、ピリポンを肩にのせて、両手で水をすくいに走る。"},{w:null,t:"三回目の水がかかった時、ワニの子が目を開ける。"},{w:null,t:"アレクの手首の画面が鳴る。"},{w:"victor",n:"ヴィクター（画面の声）",t:"アレク。狐と子どもは、どうした。",v:"04_0223"},{w:null,t:"アレク、ヤマトを見る。"},{w:"alek",t:"……狐も子どもも、見つかりませんでした。",v:"04_0225"},{w:"victor",n:"ヴィクター（画面の声）",t:"……一晩中か。",v:"04_0226"},{w:"alek",t:"はい。一晩中待っていましたが、森には、だれも来ませんでした。",v:"04_0227"},{w:"victor",n:"ヴィクター（画面の声）",t:"……ワニのチップの反応が、消えたぞ。",v:"04_0228"},{w:"alek",t:"さっき、クロッコが川で暴れたときに、取れてこわれたみたいです。",v:"04_0229"},{w:"victor",n:"ヴィクター（画面の声）",t:"……そうか。",v:"04_0230"},{w:null,t:"通話が切れる。"},{w:null,t:"アレク、手首の画面を外す。"},{w:null,t:"止まる。もどってくる。"},{w:null,t:"それから、小川へ投げる。"},{w:"hero",t:"……え、捨てちゃっていいの？　仕事に使うやつだろ。",v:"04_0235"},{w:"alek",t:"これも、持ってると居場所が向こうに分かるんだ。……お前らの画面やスマホも、場所を知らせる機能は切っとけ。",v:"04_0236"},{w:null,t:"アレク、ヤマトの手首の画面を、あごでさす。"},{w:null,t:"ヤマト、少しだけ考えて、手首の画面の設定を開く。"},{w:null,t:"エリー、カバンからスマホを出して見る。"},{w:"elly",f:"serious",t:"……お姉ちゃんから、電話が十二回も来てる。",v:"04_0240"},{w:null,t:"エリー、スマホの電源を切って、カバンの底にしまう。"},{w:null,t:"アレク、ぐったりしたワニの子を抱き上げる。"},{w:"elly",t:"その子、休ませなきゃ。お水も、いっぱいいるよ。……うち、すぐそこだから。",v:"04_0243"},{w:"hero",t:"え、もどんの？　せっかく出てきたのに。",v:"04_0244"},{w:"elly",f:"surprised",t:"でも、この子、このままじゃ歩けないよ。お水につけて、休ませてあげないと。",v:"04_0245"},{w:"hero",f:"serious",t:"……わかったよ。今夜は、もどる。",v:"04_0246"},{w:null,t:"アレク、何も言わない。でも、エリーが歩きだすと、そのあとについてくる。"}];
GR_SC.g04_08=[{w:null,t:"夜ふけ。坂の上のホテル。",v:"04_0250"},{w:null,t:"玄関の明かりだけが、ついている。"},{w:null,t:"門の内側に、アナが、腕を組んで立っている。"},{w:"ana",t:"……こんな夜中に、二人とも、どこに行ってたの？",v:"04_0253"},{w:"elly",f:"surprised",t:"……えっと、ちょっと、そこまで。",v:"04_0254"},{w:"ana",t:"ちょっと出かけただけで、そんなに泥だらけになるの？　電話、十二回もしたんだけど。",v:"04_0255"},{w:"elly",t:"知ってる。ちゃんと数えたもん。",v:"04_0256"},{w:"ana",t:"数えたなら、出なさい。……で、あの人は、だれなの？",v:"04_0257"},{w:null,t:"門の外の、石の塀のそば。"},{w:"alek",t:"（ヤマトの手首を見て）……お前の手首の画面。昼に、競技場の土手で、地図みたいな光を出してたな。",v:"04_0259"},{w:null,t:"ヤマト、手首の画面を手で押さえる。"},{w:"hero",f:"serious",t:"……え、あれ、見てたのかよ。",v:"04_0261"},{w:"alek",t:"ああ。土手の上が光ったから、望遠鏡で見てた。",v:"04_0262"},{w:null,t:"アレクの目が、ヤマトのリュックの横ポケットに行く。"},{w:"alek",t:"白い都まで、行くつもりなのか。",v:"04_0264"},{w:"hero",t:"行くよ。地図で見たら、まっすぐ行けば、すぐだし。",v:"04_0265"},{w:"alek",t:"まっすぐ行ったら、海に落ちるぞ。",v:"04_0266"},{w:"elly",t:"ほらね。だから、海の上を通ってるって言ったでしょ。",v:"04_0267"},{w:"alek",t:"……道なら、おれが知ってる。ヴィクターの車が通らない道もな。……案内、してやろうか。",v:"04_0268"},{w:"hero",f:"serious",t:"……でも、おれら、お金ないよ。",v:"04_0269"},{w:"alek",t:"……ただでやるとは、言ってない。",v:"04_0270"},{w:"elly",t:"じゃあ、いくらなの？",v:"04_0271"},{w:null,t:"アレク、指を折りかける。"},{w:"elly",t:"クッキー、一枚なら出せるよ。",v:"04_0273"},{w:"alek",t:"……クッキーは、いらない。",v:"04_0274"},{w:"hero",t:"オリーブ、五つでどう？",v:"04_0275"},{w:null,t:"フォルンの耳が、ぴくっとヤマトの方へ向く。"},{w:"alek",t:"……それ、その狐のオリーブだろ。",v:"04_0277"},{w:"hero",f:"serious",t:"……じゃあ、四つ。",v:"04_0278"},{w:null,t:"フォルン、ヤマトのリュックの前に、どすっと座りこむ。"},{w:"hero",f:"serious",t:"……三つ。",v:"04_0280"},{w:null,t:"フォルン、そっぽを向いたまま、しっぽでヤマトのすねを、ぺしっとたたく。"},{w:null,t:"エリー、塀の下にしゃがむ。"},{w:"elly",f:"smile",t:"（ワニの子に）約束だよ。わたしたち、勝ったんだから、名前、教えて。",v:"04_0283"},{w:"alek",t:"……こいつの名前は、クロッコだ。",v:"04_0284"},{w:"elly",t:"じゃあ、クロッコちゃんだね。",v:"04_0285"},{w:"alek",t:"……ちゃんは、つけなくていい。",v:"04_0286"},{w:"hero",f:"serious",t:"……案内、たのむよ。……おれ、ヤマト。",v:"04_0287"},{w:"alek",t:"……おれは、アレクだ。",v:"04_0288"},{w:"elly",t:"お姉ちゃん、この人、今夜泊めてあげて！　この子を、休ませなきゃいけないの。",v:"04_0289"},{w:null,t:"アナ、電子メモを持ったまま、アレクを上から下まで見る。"},{w:"ana",t:"……で、一泊いくら払えるの？",v:"04_0291"},{w:null,t:"アレク、何もついていない自分の手首を見る。"}];
GR_BT[4]={mid:[[{w:"alek",t:"クロッコ、水をかけろ。",v:"04_0138"},{w:"hero",t:"フォルン、撃ち返せ！",v:"04_0142"},{w:"alek",t:"クロッコ、もぐれ。もう一回、水をかけろ。",v:"04_0144"},{w:"hero",t:"出んな！　そこにいろ！　そこが一番、火がでかいんだから！",v:"04_0146"},{w:null,t:"ヤマト、その耳を見る。"},{w:"alek",t:"木の下にいても、水は届くぞ。……クロッコ、手前に回れ。",v:"04_0149"}],[{w:"elly",t:"きゃっ！",v:"04_0152"},{w:null,t:"アレクの目が、はじめてヤマトからはなれる。"},{w:"alek",t:"……クロッコ、下がれ。その雷の子から離れろ。",v:"04_0158"},{w:"elly",f:"surprised",t:"ヤマト、フォルンの火が、どんどん小さくなってる！　このままじゃ、消えちゃうよ！",v:"04_0162"},{w:null,t:"ヤマト、口を閉じる。"},{w:null,t:"ヤマトの右手の指が、一本ずつ折れていく。"},{w:"hero",t:"エリー。",v:"04_0165"},{w:"elly",t:"なに？　どうしたの？",v:"04_0166"},{w:"hero",t:"炎は、森を燃やすだろ。……森は、水を吸う。さっき、苔が水を吸ってた。……で、水は、炎を消す。",v:"04_0167"}],[{w:"hero",f:"serious",t:"……これ、じゃんけんになってるじゃん。",v:"04_0169"},{w:"elly",f:"serious",t:"……ほんとだ。全部、つながってる。",v:"04_0170"},{w:null,t:"ヤマトの目が、エリーの足のかげのピリポンに行く。"},{w:null,t:"ヤマトの目が、小川から、左の、白っぽい石の地面へ行く。"},{w:"hero",t:"フォルン！　もう、木の下にいなくていい！",v:"04_0174"},{w:"hero",t:"（石の地面の奥を指さして）あそこまで下がれ！　川から、いちばん遠いとこまでだ！",v:"04_0176"},{w:"alek",t:"石の上に逃げたって、勝負の終わりは同じだ。",v:"04_0179"},{w:"hero",t:"逃げてねーよ。来られるもんなら、来てみろよ。",v:"04_0180"},{w:null,t:"エリー、石の地面のフォルンを見る。それから、足のかげで震えているピリポンの背中に、そっと手を置く。"}],[{w:"elly",t:"ピリポン、もう少しだけ前に出よう。わたしも一緒に行くから。",v:"04_0182"},{w:null,t:"エリー、ピリポンと一緒に、小道の左のはしまで歩く。"},{w:null,t:"アレク、石の地面の奥のフォルンを見る。しっぽの火が、まだ小さい。"},{w:"alek",t:"……狐は、もう弱ってる。今なら一発で終わる。クロッコ、川から上がって、追いかけろ。",v:"04_0185"},{w:null,t:"アレクの顔が、わずかに動く。"},{w:"alek",t:"クロッコ、もどれ！　川までもどるんだ！",v:"04_0191"},{w:"elly",f:"serious",t:"……ピリポン、いける？",v:"04_0193"},{w:"elly",t:"ピリポン、ぱちって！",v:"04_0197"},{w:"hero",t:"フォルン、今だ！",v:"04_0199"}]],post:[{w:null,t:"ワニの子が、炎に押されて吹き飛び、小道の草の上を転がって、ひっくり返る。目を回して、起き上がらない。"},{w:null,t:"ひっくり返ったワニの子の耳のうしろのうろこを、雷の残りが、ちりちりっと走る。"}]};
GR_EP[4]={"t": "夜の森", "sc": [["g04_01", "森の小川（夕方）", 0], ["g04_02", "ホテルの裏口（夜）", 0], ["g04_03", "森の道（夜）", 0], ["g04_04", "口げんか", 0], ["g04_05", "向かい合う", 0], ["g04_06", "勝負（2Dアニメ）", 1], ["g04_07", "勝負のあと", 0], ["g04_08", "ホテルの門（夜ふけ）", 0]]};
GR_SC.g05_01=[{w:null,t:"坂のとちゅうに、黒塗りのロボタクシーが止まっている。"},{w:null,t:"うしろの席。"},{w:null,t:"画面の字。「アレク　応答なし」「オリーヴァ村　狐　まだ」。"},{w:"nina",t:"マルコ、起きて。仕事が来たよ。",v:"05_0031"},{w:"marco",t:"……それ、アレクの仕事っすよね。おれら、もう外されたじゃないっすか。",v:"05_0032"},{w:"nina",t:"そのアレクが、きのうの夜から返事しないんだって。だから、こっちに回ってきたの。",v:"05_0033"},{w:null,t:"マルコ、帽子を少しだけ上げる。"},{w:"marco",t:"……めんどくさいっすね。朝ごはん、まだなのに。",v:"05_0035"},{w:null,t:"マルコの足もとで、黒い体にオレンジの点の散った、小さなヤモリの子が、目をあける。"},{w:null,t:"耳のうしろで、ヴィクターのマークの小さなチップが、ちかっと光る。"},{w:null,t:"第5話　夜明けの火",v:"05_0039"}];
GR_SC.g05_02=[{w:null,t:"坂の上のホテル。四日目の朝。",v:"05_0045"},{w:null,t:"ぶどう畑のはしの道具小屋から、アレクが、うすい掛け物をたたみながら出てくる。"},{w:null,t:"二階の窓から、アナが顔を出す。"},{w:"ana",t:"おはよう。じゃあ、ひと晩分の宿代ね。20ジェムコイン。",v:"05_0048"},{w:"alek",t:"すみません、今は払えないんです。支払いに使っていた画面を、きのうの夜、川に投げ捨ててしまったので。",v:"05_0049"},{w:"ana",t:"画面を、川に？　……じゃあ、裏の用水路の泥かき。それでいいから。",v:"05_0050"},{w:"alek",t:"泥かきなら、ロボットの方が早くないですか。",v:"05_0051"},{w:"ana",t:"ロボットは、ぬかるみに足を取られて動けなくなるの。",v:"05_0052"},{w:"alek",t:"……はい。分かりました。",v:"05_0053"},{w:null,t:"小屋の横の石の水おけ。クロッコが体をしずめて、目をつむっている。"}];
GR_SC.g05_03=[{w:null,t:"朝ごはんのテラス。"},{w:null,t:"テーブルのあいだを、丸い小さなロボットがすべって回る。"},{w:null,t:"テラスの手すりの向こう、裏の畑。"},{w:"hero",t:"でさ、相手、水なわけ。こっちは炎だろ。ふつうは、負けるじゃん。",v:"05_0060"},{w:"x",n:"客の子A",t:"えっ、負けちゃうの？",v:"05_0061"},{w:"hero",t:"ふつうはね。でも、そこでおれが気づいちゃったわけ。",v:"05_0062"},{w:null,t:"ヤマト、指を立てて、炎、森、水、と一本ずつ折っていく。"},{w:"hero",t:"全部、じゃんけんみたいになってんの。だから、勝てる場所に下がればいいって。",v:"05_0064"},{w:"x",n:"客の子B",t:"じゃあ、じゃんけんで勝ったってこと？",v:"05_0065"},{w:"hero",f:"smile",t:"じゃんけんみたいなもんで、勝ったの。",v:"05_0066"},{w:"elly",t:"（パンをちぎりながら）気づいたの、負けそうになってからだったよね。",v:"05_0067"},{w:"hero",t:"負けそうになってからでも、気づいたもんは気づいたの。",v:"05_0068"},{w:null,t:"テーブルのはしで、フォルンがしっぽの火の上でオリーブを転がしている。"},{w:null,t:"ヤマト、いちばん大きい焼きオリーブを、ひょいとつまむ。"},{w:"hero",t:"これは、作戦を考えたおれの分ね。",v:"05_0071"},{w:null,t:"フォルンのしっぽの火が、ぼっとふくらむ。"},{w:"hero",t:"あっ、ち、ち、ち——",v:"05_0073"},{w:null,t:"オリーブが手のひらの上でおどる。"},{w:null,t:"フォルン、宙のオリーブを口で受けとめる。"},{w:null,t:"子どもたちが、どっと笑う。"},{w:"hero",f:"serious",t:"……今のは、わざとだからな。",v:"05_0077"},{w:"x",n:"客の子C",t:"えー、ほんとにわざとなの？",v:"05_0078"},{w:"hero",t:"ほんとに、わざと。……まあ、次にだれが来ても、おれとフォルンなら——",v:"05_0079"},{w:null,t:"テラスの入口に、アナが立っている。"},{w:"ana",t:"ヤマト。門のところに、あんたにお客さんが来てる。",v:"05_0081"}];
GR_SC.g05_04=[{w:null,t:"門の外に、マルコ。"},{w:"marco",t:"どうも。ヴィクターのマルコっす。この前は、どうも。……あの狐、ここにいますよね。",v:"05_0085"},{w:null,t:"ヤマトの足もとで、フォルンの耳が立つ。"},{w:null,t:"マルコの目が、フォルンから、そのうしろへ行く。"},{w:"marco",t:"……アレクさん？　なにしてんすか、そんなとこで。",v:"05_0088"},{w:"alek",t:"見て分かりませんか。泥かきですよ、泥かき！",v:"05_0089"},{w:"marco",t:"いや、それは見れば分かるんすけど。……まあ、いいや。そういうの報告すんの、めんどくさいんで。",v:"05_0090"},{w:null,t:"坂の下で、ニーナの画面が、かしゃっと鳴る。"},{w:"marco",t:"一対一で、どうすか。そっちが勝ったら、おれは手を引きます。おれが勝ったら、狐はもらっていきます。",v:"05_0092"},{w:"hero",t:"いいよ。受けてやる。",v:"05_0093"},{w:null,t:"アレク、泥だらけのまま、畑から門へ走ってくる。"},{w:"alek",t:"おい、ヤマト、待て！　勝手に決めるな！",v:"05_0095"},{w:"hero",f:"angry",t:"なんでだよ。きのうの夜だって、ちゃんと勝ったじゃん。",v:"05_0096"},{w:null,t:"マルコの肩のヤモリが、口をあける。"},{w:null,t:"エリーの肩のピリポンが、エリーの髪の中に、頭からもぐりこむ。"},{w:"elly",t:"……ピリポン、ああいう大きい火は、こわくてだめなの。",v:"05_0099"},{w:"alek",t:"あのヤモリは、勝負の中で進化できるんだ。お前の狐は、まだ一回も進化したことがないだろ。進化されたら、同じ炎でも押し負けるぞ！",v:"05_0100"},{w:"hero",t:"進化とか、関係ないって。どっちも炎なんだから、あとは気合いだろ。",v:"05_0101"},{w:null,t:"アレク、水おけを見る。クロッコは、目をつむったまま。"},{w:"alek",t:"気合いでどうにかなるか！　……クロッコも、まだ戦えないんだ。だから待てって言ってるんだよ！",v:"05_0103"},{w:null,t:"ヤマトは、もう門の外に出ている。"},{w:"marco",t:"場所は、どこでもいいっすけど。……裏の畑にしましょうか。林の木の下なら、すずしいんで。",v:"05_0105"}];
GR_SC.g05_05=[{w:null,t:"ぶどう棚の前で、マルコが畑を見わたす。"},{w:null,t:"手前は、乾いた草の畑。"},{w:null,t:"マルコ、林の木の下に木箱を置いて、座る。"},{w:null,t:"ヤマト、フォルンを手前の畑のまん中に立たせる。"},{w:null,t:"アレクとエリーが、ぶどう棚の下に立つ。"},{w:"marco",t:"じゃ、始めましょうか。こっちは、いつでもいいっすよ。",v:"05_0116"}];
GR_SC.g05_09=[{w:null,t:"フォルンの体から、光がすうっと引いていく。"},{w:null,t:"マルコ、オキヤモを両腕でかかえ上げて、重そうに肩にかつぎ直す。"},{w:"marco",t:"……約束は約束なんで、今日は帰ります。",v:"05_0194"},{w:"nina",t:"マルコ、今の、ボスに送る写真、撮った？",v:"05_0195"},{w:"marco",t:"ニーナさんが、坂の下でもう撮ってたじゃないっすか。おれは、もういいっす。",v:"05_0196"},{w:null,t:"マルコ、帰りかけて、アレクの前で止まる。"},{w:"marco",t:"アレクさん。……抜けるんなら、もっと遠くまで行った方がいいっすよ。うちのボス、しつこいんで。",v:"05_0198"},{w:"alek",t:"……分かってます。忠告、ありがとうございます。",v:"05_0199"},{w:null,t:"マルコ、坂を下りていく。肩の上で、オキヤモのしっぽがぶらぶらゆれる。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。さっきまで見上げていた顔が、ひざの高さにある。"},{w:null,t:"フォルン、首をくるっと回して、ヤマトの右手の指なし手袋を、ぱくっとくわえて引きぬく。"},{w:"hero",t:"おい、それ、おれの手袋だって。",v:"05_0203"},{w:null,t:"フォルン、手袋をぶらぶらさせながら、畑の外へすたすた出ていく。"},{w:"hero",t:"返せって！　なでさせてくれないのに、手袋は取るのかよ！",v:"05_0205"}];
GR_SC.g05_10=[{w:null,t:"ロビーの画面に、広告。"},{w:null,t:"ヤマト、その前に立っている。"},{w:null,t:"アレクがうしろに来る。"},{w:"alek",t:"ニーナが写真を送ったんだ。昼までには、ヴィクターの車がもっと来るぞ。今のうちに、村を出た方がいい。",v:"05_0213"},{w:null,t:"パンの袋をつめていたエリーの手が、一瞬だけ止まる。"},{w:"hero",t:"白い都まで、どれくらいかかんの？",v:"05_0215"},{w:"alek",t:"歩きなら、二週間くらいだ。",v:"05_0216"},{w:"hero",f:"serious",t:"……歩き？　ロボタクシーとか、乗らないの？",v:"05_0217"},{w:null,t:"門の前を、ロボタクシーがすうっと通る。ヤマト、手を上げかける。"},{w:"alek",t:"乗るなって！　乗った記録から、居場所がヴィクターにばれるだろ。",v:"05_0219"},{w:null,t:"アレク、水おけからクロッコを出して、背中にかつぐ。クロッコ、目はあけない。"},{w:"ana",t:"おばあちゃんから、電話があったよ。……どうせ、止めても行くんでしょ。",v:"05_0221"},{w:null,t:"エリー、目をそらして、笑う。"},{w:"ana",t:"スマホの電源は、切ったままでいいから。",v:"05_0223"},{w:"ana",t:"そのかわり毎晩、だれかの画面を借りて、電話してきなさい。",v:"05_0224"},{w:"elly",f:"serious",t:"……うん。毎晩、かける。",v:"05_0225"},{w:null,t:"アナ、上着のポケットから、手のひらほどのうすい板を出す。"},{w:"ana",t:"それと、これ。名前のつかない、使い切りのジェムコインのカード。",v:"05_0227"},{w:"elly",t:"カード？　なんで、スマホで払っちゃだめなの？",v:"05_0228"},{w:"ana",t:"スマホで払うと、居場所がばれるでしょ。これは名前が残らないの。",v:"05_0229"},{w:"hero",f:"smile",t:"（のぞきこんで）すげえ。これで、アイス何個ぶん？",v:"05_0230"},{w:"ana",t:"アイスに使うんじゃないの。ごはんと宿に使いなさい。",v:"05_0231"},{w:null,t:"エリー、カードを両手で受け取って、肩かけカバンの内ポケットにしまう。"},{w:null,t:"アナ、アレクの方を向く。"},{w:"ana",t:"（アレクに）宿代は、泥かきでちゃらにしてあげる。",v:"05_0234"},{w:"ana",t:"そのかわりカードの分は、帰ってきたら働いて返してね。",v:"05_0235"},{w:null,t:"アレク、背すじをのばして、アナに頭を下げる。"},{w:"alek",t:"はい。必ず、働いて返しに来ます。",v:"05_0237"},{w:null,t:"アレク、ヤマトとエリーの方を向く。"},{w:"alek",t:"昼でも、森の道を行くぞ。上から見えにくいからな。",v:"05_0239"},{w:null,t:"三人とフォルンが、ぶどう畑の先の森の道へ。"},{w:null,t:"ヤマト、一度ふり返る。"}];
GR_SC.g05_11=[{w:null,t:"昼前の光が、小川の底までさしこんでいる。"},{w:null,t:"画面が、水の中でぽうっと光る。"},{w:null,t:"黒いドローンが一機、低く飛んでくる。"},{w:null,t:"赤い光が、岸のぬかるみで止まる。"},{w:null,t:"ドローンが高く上がる。"}];
GR_BT[5]={mid:[[{w:"hero",t:"フォルン、林の中だ！　まっすぐ突っこめ！",v:"05_0119"},{w:null,t:"ヤマトの目が、一瞬だけ、細くなった火に行く。"},{w:"marco",t:"スミヤモ、焼いちゃって。",v:"05_0123"},{w:"marco",t:"あーあ、怒らせちゃった。スミヤモ、もう本気出していいっすよ。",v:"05_0128"},{w:"alek",t:"……だから言っただろ！　進化されたら、押し負けるって！",v:"05_0130"},{w:"hero",t:"出ろ！　フォルン、林から出ろ！",v:"05_0133"},{w:null,t:"アレクは何も言わない。組んだ腕の指が、ひじをつかんでいる。"}],[{w:null,t:"マルコ、木箱から腰を上げて、のびをする。"},{w:"marco",t:"あー、もういいっす。これ以上焦がすと、あとでボスがうるさいんで。オキヤモ、止まれ。",v:"05_0139"},{w:"marco",t:"……オキヤモ？　止まれって言ってるんすけど。",v:"05_0142"},{w:null,t:"ニーナの手首の画面が鳴る。"},{w:"nina",t:"……ボスが、チップに直接、命令を入れてる。こっちからは、止められない。",v:"05_0144"},{w:null,t:"マルコ、ニーナの画面をのぞきこんだまま、だまる。"},{w:"marco",t:"もういいって。止まってくださいよ。",v:"05_0150"},{w:null,t:"アレク、ぶどう棚の下から一歩出る。"},{w:"alek",t:"ヤマト、もうやめさせろ！　これ以上は、無理だ！",v:"05_0154"},{w:null,t:"ヤマト、ぶどう棚の前から、用水路の手前の乾いた土まで走り出る。"},{w:"hero",t:"フォルン！　おい、フォルン！",v:"05_0156"},{w:null,t:"マルコの口が、あいたまま。"}],[{w:null,t:"ヤマトの目が、火の玉の飛んだあとを追う。"},{w:"hero",f:"serious",t:"……フォルン。水をまたぐな。そこから撃て。",v:"05_0174"}]],post:[{w:null,t:"オキヤモが吹き飛ばされて、ぬかるみの上にあおむけに倒れる。"},{w:null,t:"倒れたオキヤモの耳のうしろで、チップがまだ光っている。"},{w:"marco",t:"……もういいって。お前、もう十分がんばったよ。",v:"05_0185"},{w:null,t:"マルコ、畑を歩いていって、ぬかるみに入る。"},{w:"nina",t:"……ボスから、もういいって来た。今なら止められる。",v:"05_0188"}]};
GR_EP[5]={"t": "夜明けの火", "sc": [["g05_01", "村を見下ろす坂（夜明け）", 0], ["g05_02", "ホテルの裏・道具小屋（朝）", 0], ["g05_03", "ホテルのテラス（朝）", 0], ["g05_04", "ホテルの門", 0], ["g05_05", "ホテルの裏の畑・向かい合う", 0], ["g05_06", "勝負・突っこむ（2Dアニメ）", 1], ["g05_07", "勝負・止まらない（2Dアニメ）", 1], ["g05_08", "勝負・水をまたがない（2Dアニメ）", 1], ["g05_09", "勝負のあと", 0], ["g05_10", "ホテルのロビーと門（昼前）", 0], ["g05_11", "ホテル裏の森の小川", 0]]};
GR_SC.g06_01=[{w:null,t:"オリーヴァ村を出た三人は、丘のオリーブの木の下で夜を明かした。",v:"06_0020"},{w:null,t:"丘の中腹。古いオリーブの木の下に、銀色のうすいシートが一枚。"},{w:null,t:"ヤマトだけ、シートからはみ出して、草の上で大の字。"},{w:null,t:"フォルンは、シートのはしで丸くなっている。しっぽの火だけが、シートの外に出ている。"},{w:null,t:"丘の下の道。"},{w:null,t:"アレク、目をあける。"},{w:null,t:"アレク、フォルンのしっぽをつかんで、シートの中へ押しこむ。"},{w:null,t:"アレク、ヤマトの足首をつかんで、シートの下へずるずる引きずりこむ。"},{w:null,t:"ドローンが丘を上がってきて、オリーブの木の上で止まる。"},{w:null,t:"アレク、シートのはしを持ち上げて、長く息を吐く。"},{w:"hero",t:"（寝ぼけて）……なに。もう朝？　なんで、おれの足、引っぱってんの。",v:"06_0030"},{w:"alek",t:"ヴィクターのドローンだ。あの赤い光は、人とテリオンの体の熱を見てる。このシートは熱を外に出さないし、火にも強いから、下にいれば見つからない。なのに、お前だけ外で手足を広げて寝てたんだぞ。",v:"06_0031"},{w:"hero",t:"だったら、ふつうに起こせばいいじゃん。",v:"06_0032"},{w:"alek",t:"起こしたって！　ドローンに聞こえないように、小さい声で三回呼んだ！",v:"06_0033"},{w:"elly",t:"（シートの中から、目をつむったまま）四回だよ。わたし、数えてたもん。",v:"06_0034"},{w:"hero",t:"起きてたんなら、エリーが起こしてくれればよかったじゃん。",v:"06_0035"},{w:"elly",t:"わたしは、自分で転がって場所をあけたもん。ヤマトの分まではむり。",v:"06_0036"},{w:null,t:"アレク、かまれた手をふりながら、丘の下の道を見る。"},{w:"alek",t:"道を行くのは、もうやめる。道ぞいにはカメラがあるし、ドローンも、ああやって道の上を見て回ってる。ここから先は、丘の畑の中を通っていく。",v:"06_0038"},{w:null,t:"フォルン、シートから顔を出して、あくび。"},{w:"hero",t:"おい、それ、まだ返してくれないのかよ。",v:"06_0040"},{w:null,t:"第6話　丘の畑",v:"06_0042"}];
GR_SC.g06_02=[{w:null,t:"オリーヴァ村の東。オリーブの丘が、いくつも続いている。",v:"06_0048"},{w:null,t:"となりの大きな丘。"},{w:null,t:"こちらの斜面の畑。"},{w:"hero",t:"あっちの丘はロボットなのに、こっちは手か。手で摘むと高く売れるんだっけ？",v:"06_0051"},{w:"elly",t:"そう。かごのタグが手首の画面とつながって、だれが摘んだか記録に残るんだって。",v:"06_0052"},{w:"hero",t:"じゃあ、おれが拾ったのも、高くなんの？",v:"06_0053"},{w:"elly",t:"ヤマトの手首の画面は、この畑とつながってないもん。",v:"06_0054"},{w:null,t:"ヤマト、くやしそうに、網の上の実を一つ拾って、近くの女の人のかごに入れる。"},{w:"x",n:"村の女の人",t:"ありがとう。ついでに、そっちのはしを持っててくれる？　網がずれると、実が坂をころがっていっちゃうから。",v:"06_0056"},{w:"hero",t:"え、あ、うん。",v:"06_0057"},{w:null,t:"ヤマト、網を持ったまま動けなくなる。"},{w:"hero",t:"ちょっと待って！　おれ、手伝いの子だと思われてる！",v:"06_0059"},{w:"alek",t:"拾ってかごに入れたのは、お前だろ。たのまれたんなら、最後まで持ってろよ。",v:"06_0060"},{w:null,t:"女の人が、べつの人に網をわたして、ヤマトに手をふる。"},{w:null,t:"クロッコは、アレクの足のうしろを、自分の足で歩いている。"},{w:null,t:"ピリポンは、エリーの肩の上。前を行くフォルンのしっぽの火がゆれるたびに、エリーの髪の中に頭をつっこむ。"}];
GR_SC.g06_03=[{w:null,t:"この丘のいちばん上に、ひときわ手入れのいい畑があった。",v:"06_0066"},{w:null,t:"畑の見えるところで、アレクの足が止まる。"},{w:null,t:"アレク、少しだけ目をとじて、また歩き出す。"},{w:null,t:"手入れのいい木の並び。"},{w:null,t:"幹の小さな穴のいくつかに、黒い網の切れはしがひっかかったまま。"},{w:null,t:"畑のはしを、石を組んだ溝が流れている。"},{w:null,t:"手前のすみに、昔の脱穀場の、丸い石の床。"},{w:null,t:"畑のはしに、屋根に太陽光の板をのせた、小さな石の家。"},{w:null,t:"男が一人、くずれた溝の石を、だまって積み直している。"},{w:null,t:"ヤマト、石の床の上に、手足を広げて寝ころがる。"},{w:"hero",t:"エリー、この石、ぽかぽかしてる！　ほとんど寝てないから、ちょっとだけ寝てっていい？",v:"06_0076"},{w:"alek",t:"お前、ドローンが来ても起きないくらい、ぐっすり寝てただろ！　それに、ここは人の畑だぞ。",v:"06_0077"},{w:null,t:"エリーの肩から、ピリポンが石の床に、ぴょんと下りる。"},{w:null,t:"火花が、寝ているヤマトのおしりに届く。"},{w:"hero",t:"いでっ！",v:"06_0080"},{w:null,t:"ヤマト、とび起きる。"},{w:"elly",t:"ほら、人の畑で寝ようとするからだよ。",v:"06_0082"},{w:null,t:"太いオリーブの幹に、大きなカブトムシのテリオンがとまっている。"},{w:"hero",t:"うわ、でっか！　これ、ヘラクレスオオカブトだろ。動画で見たことある。",v:"06_0084"},{w:"elly",t:"ヘラクレスって、もとは人の名前なんだよ。",v:"06_0085"},{w:"hero",t:"人？",v:"06_0086"},{w:"elly",t:"ギリシャの昔のお話に出てくる、すっごく力持ちの人。カブトムシの方が、あとからその人の名前をもらったの。",v:"06_0087"},{w:"hero",t:"じゃあ、そのヘラクレスって人にも、つのが生えてたのか？",v:"06_0088"},{w:"elly",t:"生えてないよ。人だもん。",v:"06_0089"},{w:null,t:"カブトムシのテリオンが、幹の上で前足を、ぐっとふんばる。それから、つのを右下からすくい上げる。"},{w:null,t:"エリーだけが、それを見ている。"},{w:null,t:"ヤマトは、男のかごの黒い実を一つつまんで、光にかざしている。"},{w:"hero",t:"（男に）おじさん、これ、一個食べていい？",v:"06_0093"},{w:null,t:"ヤマト、返事を待たずに、もう口を大きくあけている。"},{w:"stavros",t:"……やめとけ。とったばかりのオリーブは、しぶくて食えたもんじゃない。",v:"06_0095"},{w:null,t:"ヤマトの口が、あいたまま止まる。"},{w:null,t:"男の目が、ヤマトのうしろへ行く。"},{w:"stavros",t:"……先月、ヴィクターの連中を、この畑まで連れてきたのは、お前だな。",v:"06_0098"},{w:null,t:"アレク、目をそらさない。"},{w:"alek",t:"……はい。ぼくです。この丘には、チップの入っていない野生の子がたくさんいると、ぼくがヴィクターに知らせて、ここまで連れてきました。",v:"06_0100"},{w:"hero",t:"え……。",v:"06_0101"},{w:"elly",t:"アレク、それ、ほんと？",v:"06_0102"},{w:"alek",t:"……本当だ。あの時は、言われた仕事を、何も考えずにやってた。",v:"06_0103"},{w:null,t:"ヤニス、幹の穴に指を入れて、網の切れはしをつまみ出す。"},{w:"stavros",t:"あの晩、ドローンがこの木に網を落としていった。ここに住んでた小さいのが、十二ひき、みんな連れていかれた。あの晩、家の中にいたこのヘラツノだけが残った。……きのうの夜も、ヴィクターの車がこの畑の下を通って、みぞをふみくずしていった。",v:"06_0105"},{w:null,t:"ヘラツノが、羽を一度だけふるわせる。"},{w:"hero",t:"でも、アレクはもうヴィクターをやめたんだ！　おれたちだって、ヴィクターに追われてるんだ！",v:"06_0107"},{w:"stavros",t:"追われてるなら、なおさら畑には入れられない。あの晩の連中も、最初は「あやしい者じゃない」と言ってた。口では、何とでも言える。",v:"06_0108"},{w:null,t:"ヤニス、手首の画面にふれる。畑の入口の低い柵が、すうっとせり上がって閉まる。"},{w:"stavros",t:"通りたいなら、ヘラツノと勝負しろ。ヴィクターの手下なら、負けそうになったらドローンを呼ぶ。呼ばずに、自分のテリオンだけで最後まで戦えるか、見せてみろ。負けたら、来た道を帰れ。",v:"06_0110"},{w:null,t:"ヤマトの顔が、少しだけ固まる。"},{w:"alek",t:"三体で戦わせてもらっても、いいですか。ヘラツノは、あの晩の網から、一体だけ残った子ですよね。一体ずつでは、とても勝負にならないと思います。",v:"06_0113"},{w:"stavros",t:"いい。三体でも、ヘラツノは負けない。",v:"06_0114"}];
GR_SC.g06_04=[{w:null,t:"畑のまん中で、勝負が始まる。",v:"06_0121"},{w:null,t:"ヤニスが、畑のまん中まで歩いていく。"},{w:null,t:"向こうのはしはオリーブの木。"},{w:null,t:"ヤニス、ヘラツノを木の手前の草に置く。"},{w:null,t:"ヤマト、フォルンを手前のまん中に。"},{w:null,t:"ヘラツノと向かい合ったとたん、フォルンの体から火の粉がぱっとあふれる。"},{w:null,t:"ヤマトの左の手首の画面で、時計の形のアイコンが光る。"},{w:null,t:"アレクが、ちらっとヤマトの顔を見る。"},{w:null,t:"アレク、クロッコを溝のそばの草に下ろす。"},{w:null,t:"エリー、石の床の左がわのはしに立つ。"},{w:"stavros",t:"始め。",v:"06_0131"}];
GR_SC.g06_08=[{w:null,t:"昼。千年のオリーブの下。",v:"06_0208"},{w:null,t:"フォルンとピリムサの体から、光がすうっと引いていく。"},{w:null,t:"ヤニス、ヘラツノのそばにしゃがむ。"},{w:null,t:"エリー、石の床の上のピリポンをだき上げる。"},{w:"elly",t:"ピリポン、さっき、すっごく大きくなってたよ！",v:"06_0212"},{w:null,t:"ピリポン、エリーの顔に、ぱちっ。"},{w:null,t:"アレク、クロッコをだき起こす。クロッコ、目をあけて、アレクの手に頭をこすりつける。"},{w:null,t:"ヤニス、立ち上がって、アレクの前に来る。だまってしゃがみ、クロッコの耳のうしろのうろこのすき間を、指でそっと広げる。"},{w:null,t:"ヤニス、手の中の網の留め金と、見くらべる。"},{w:"stavros",t:"……お前のワニにも、こいつが入れられてたのか。",v:"06_0217"},{w:"alek",t:"はい。入っていると、どこにいても居場所が知られて、向こうの好きな時に動けなくされるチップでした。おとといの夜、この二人と勝負した時に割れたんです。",v:"06_0218"},{w:null,t:"ヤニス、だまって、クロッコの頭に手のひらをのせる。それから、ふり返って、フォルンの耳のうしろを見る。"},{w:null,t:"ヤニス、石の家からガラスのびんを持ってくる。"},{w:"stavros",t:"こっちは、しおみずに二か月つけてある。これなら、食える。",v:"06_0221"},{w:null,t:"ヤマト、一つ口に入れる。顔が、きゅっとすっぱくなる。"},{w:"hero",t:"すっぱ！　……でも、うまい。もう一個、いい？",v:"06_0223"},{w:null,t:"ヤニス、うなずく。"},{w:null,t:"ヤニス、手首の画面にふれる。入口の柵が、すうっと下がって開く。"},{w:null,t:"アレク、だまって溝のそばにしゃがむ。"},{w:"stavros",t:"そこじゃない。平たいほうを、水の流れてくる方に向けろ。そうしないと、すぐまた水があふれる。",v:"06_0227"},{w:"alek",t:"……はい。",v:"06_0228"},{w:null,t:"アレク、石の向きを変えて、はめ直す。"},{w:null,t:"ヤマト、千年のオリーブの幹に、手のひらをつけている。"},{w:"hero",t:"おじさん、この木って、何年くらい生きてんの？",v:"06_0231"},{w:"stavros",t:"千年は、こえてる。この村ができるより前から、ずっとここにある。",v:"06_0232"},{w:"hero",t:"千年……。",v:"06_0233"},{w:null,t:"ヤマト、幹を見上げる。"},{w:null,t:"エリー、少しまよってから、ヤニスの前に立つ。"},{w:"elly",t:"あの、手首の画面を一回だけ、貸してもらえませんか。お姉ちゃんに毎晩かけるって約束したのに、わたしのスマホは電源を切ってて、きのうの夜はかけられなかったんです。",v:"06_0236"},{w:"hero",t:"おれの画面で、かければいいじゃん。",v:"06_0237"},{w:"alek",t:"お前の画面はだめだって。じいちゃんのアプリが入ってるんだぞ。ヴィクターにたどられたらどうすんだよ。",v:"06_0238"},{w:null,t:"アレク、ヤニスの方を向く。"},{w:"alek",t:"おじさんの画面から、かけたことが残ると、ご迷惑がかかるかもしれません。",v:"06_0240"},{w:"stavros",t:"かまわん。また来たら、今度は追い返す。",v:"06_0241"},{w:null,t:"ヤニス、手首の画面を外して、エリーにわたす。"},{w:"alek",t:"（エリーに）かけるなら、短くしろよ。長く話してると、どこからかけたか調べられるかもしれないから。",v:"06_0243"},{w:null,t:"空中の画面に、アナの顔。"},{w:"ana",t:"エリー！　きのうの夜、どうしてかけてこなかったの！　ずっと待ってたんだよ。",v:"06_0245"},{w:"elly",f:"sad",t:"ごめんね。きのうはオリーブの丘の上で寝てて——",v:"06_0246"},{w:null,t:"アレク、エリーの口の前で、両手をばたばたふる。"},{w:"alek",t:"（小声で）場所を言うなって！",v:"06_0248"},{w:"elly",t:"……外で寝てて、かけられなかったの。今夜からは、ちゃんとかけるから。",v:"06_0249"},{w:"ana",t:"……ごはんは、ちゃんと食べてる？",v:"06_0250"},{w:null,t:"エリー、ふり返る。"},{w:"elly",t:"うん。オリーブ、食べてる。",v:"06_0252"},{w:null,t:"エリー、画面を切って、ヤニスに頭を下げて返す。"},{w:null,t:"ピリポン、エリーの髪の中に頭から飛びこむ。"},{w:"elly",f:"serious",t:"……もう、出てきてるじゃん。",v:"06_0256"}];
GR_SC.g06_09=[{w:null,t:"夕方。三人は、畑の向こうの、いちばん高い丘のてっぺんに着いた。",v:"06_0259"},{w:null,t:"いちばん高い丘のてっぺんに、三人と三体。"},{w:null,t:"東の空。遠くの森の上に、灰色の煙が一本。"},{w:null,t:"アレク、古い望遠鏡をのぞく。"},{w:"hero",t:"あれ、煙だよな。何か燃えてんの？",v:"06_0263"},{w:"alek",t:"森のまん中から出てる。……ヤマト、手首の地図を出してくれ。場所を知らせる機能は、切ったままでな。",v:"06_0264"},{w:"hero",t:"ちゃんと切ってるって。おととい切ってから、一回も入れてないよ。",v:"06_0265"},{w:null,t:"ヤマトの手首から、光の地図が宙に広がる。"},{w:"alek",t:"……アルカディアの森だ。ここから歩いたら、一日はかかる。それだけ遠いのに煙が見えるなら、小さな火じゃない。",v:"06_0267"},{w:"elly",t:"あの森には、テリオンがたくさん住んでるんだよね。",v:"06_0268"},{w:null,t:"アレク、答えない。"},{w:null,t:"フォルンの鼻が、ひくっと動く。煙の方を向いて、耳を立てる。"}];
GR_BT[6]={mid:[[{w:"hero",f:"surprised",t:"フォルン、追え！　でっかくなったんだから、あんなカブトムシ、すぐ追いつける！",v:"06_0134"},{w:"hero",f:"surprised",t:"逃げんなよ！　フォルン、もっと速く追え！",v:"06_0142"},{w:"alek",t:"クロッコ、みぞから離れるな！　水のそばじゃないと、お前の水は届かない！",v:"06_0144"},{w:"alek",t:"クロッコ、みぞへもどれ！",v:"06_0147"},{w:null,t:"アレク、口をとじる。"},{w:null,t:"エリーの目は、ヘラツノの前足に止まっている。"}],[{w:"elly",t:"ピリポン、石の上から、ぱちって！",v:"06_0154"},{w:null,t:"ヤマトの目が、ヘラツノの止まった所に行く。"},{w:null,t:"ヤマト、口をあけかける。"},{w:"hero",t:"フォルン、追うな。そこで待て。",v:"06_0167"}],[{w:null,t:"ヤニスの組んだ腕の指が、一本だけ動く。"},{w:"elly",t:"右！",v:"06_0185"},{w:"hero",t:"フォルン、今だ！",v:"06_0191"},{w:"elly",t:"右！",v:"06_0197"}]],post:[{w:null,t:"ヘラツノが、草の上に、ころりと横になる。目を回している。"},{w:null,t:"千年のオリーブの葉が、風で、さあっと鳴る。"}]};
GR_EP[6]={"t": "丘の畑", "sc": [["g06_01", "丘のオリーブの木の下（夜明け）", 0], ["g06_02", "丘の斜面（朝）", 0], ["g06_03", "ヤニスの畑", 0], ["g06_04", "向かい合う", 0], ["g06_05", "勝負・追う", 1], ["g06_06", "勝負・下がる先", 1], ["g06_07", "勝負・決着", 1], ["g06_08", "勝負のあと", 0], ["g06_09", "丘のてっぺん（夕方）", 0]]};
GR_SC.g07_01=[{w:null,t:"前の日の昼。アルカディアの森の、川べり。",v:"07_0018"},{w:null,t:"昼の森。乾いた落ち葉が、地面をうめている。"},{w:null,t:"川べりの大きな岩の上に、ニーナが黒い箱を置く。"},{w:"nina",t:"これで、歌が流れる。",v:"07_0021"},{w:"nina",t:"歌を聞いた子は、自分で川まで歩いてくるよ。",v:"07_0022"},{w:"marco",t:"歩いてくるなら、網なんか、もういらなくないすか。",v:"07_0023"},{w:"nina",t:"歌で来ない子もいるの。そういうのは、網。",v:"07_0024"},{w:null,t:"ニーナ、手首の画面にふれる。"},{w:"marco",t:"あばれると、網が破れるんすよね。",v:"07_0026"},{w:"marco",t:"……スミヤモ、ちょっとだけ、おどかして。",v:"07_0027"},{w:null,t:"マルコの足もとのスミヤモが、口をあける。"},{w:null,t:"スミヤモの耳のうしろで、ヴィクターのチップが、ちかっと光る。"},{w:null,t:"スミヤモ、口を閉じない。"},{w:null,t:"網から抜けた角の子が、森の奥へ逃げていく。"},{w:"marco",t:"スミヤモ、止まれ。……止まれって言ってるじゃないすか。",v:"07_0032"},{w:null,t:"ニーナの手首の画面。"},{w:"nina",t:"……ボスが、またチップに直接入れてる。",v:"07_0034"},{w:"nina",t:"こっちからは止められない。",v:"07_0035"},{w:"marco",t:"森ごと焼く気っすか、これ。",v:"07_0036"},{w:null,t:"マルコ、腰の水の筒をあけて、燃える落ち葉にかける。"},{w:null,t:"第7話　ラドン川の歌",v:"07_0039"}];
GR_SC.g07_02=[{w:null,t:"次の日。三人は夜明け前に丘を下りて、一日歩いた。",v:"07_0045"},{w:null,t:"森へ続く道。三人とも、目の下にくま。"},{w:null,t:"アルカディア。楽園という名の森だ。入口には、受付がある。",v:"07_0047"},{w:null,t:"森の入口。木の枠の自動ゲート。"},{w:null,t:"アレク、パーカーのフードを深くかぶる。ゲートの上の小さなカメラから、顔をそらす。"},{w:"x",n:"受付のロボット",t:"十五さい以上がお一人、十五さい未満がお二人。",v:"07_0050"},{w:"x",n:"受付のロボット",t:"それに、テリオンが三体ですね。",v:"07_0051"},{w:"x",n:"受付のロボット",t:"森の保全料を、いただきます。",v:"07_0052"},{w:null,t:"ロボットの胸の画面に、金額。"},{w:"x",n:"受付のロボット",t:"判定できないテリオンは、追加料金でお通りいただけます。",v:"07_0054"},{w:null,t:"エリー、しゃがんで、フォルンをカメラの前へ押し出そうとする。"},{w:"elly",t:"この子はフォルンっていうの。ちゃんとテリオンだよ。",v:"07_0056"},{w:"x",n:"受付のロボット",t:"フォルン様。判定できません。",v:"07_0057"},{w:null,t:"エリー、白い肩かけカバンから、手のひら大のうすいカードを出す（5話でアナにもらった、名前のつかないジェムコインのカード）。"},{w:null,t:"カードの上に、残高の数字が光る。"},{w:null,t:"アレク、横からその数字をのぞきこむ。"},{w:"alek",t:"エリー、そのカード、おれに持たせてくれ。",v:"07_0061"},{w:"alek",t:"この先、何にいくら使ったか、ちゃんと数えておきたい。",v:"07_0062"},{w:"elly",t:"いいよ。アレク、お金の計算、好きだもんね。",v:"07_0063"},{w:"alek",t:"好きなんじゃない。",v:"07_0064"},{w:"alek",t:"だれも数えないから、おれが数えてるんだって！",v:"07_0065"},{w:null,t:"アレク、カードを受け取って、パーカーの内ポケットにしまう。"},{w:"x",n:"受付のロボット",t:"なお、本日、森の東がわで煙が確認されています。",v:"07_0067"},{w:"x",n:"受付のロボット",t:"消防のドローンが向かっております。",v:"07_0068"},{w:null,t:"ゲートが、すうっと開く。"}];
GR_SC.g07_03=[{w:null,t:"焦げたにおいが、だんだん強くなる。"},{w:null,t:"木のあいだがひらけた所。"},{w:null,t:"小川のふちに、手さげかばんほどの小さなポンプ。"},{w:null,t:"バケツが、人の手から手へわたされていく。"},{w:null,t:"となりで、森の手入れの作業員のおじさんが、火を消す泡の筒をふっている。"},{w:"x",n:"作業員のおじさん",t:"泡は、これで終わりだ！　あとは水しかないぞ！",v:"07_0077"},{w:null,t:"バケツを回す人たちの中に、すすで顔のまっ黒な男。"},{w:null,t:"アレク、もうクロッコを小川に下ろしている。"},{w:null,t:"エリーの肩で、ピリポンの毛がぱちぱち光っている。"},{w:"hero",t:"あっ！　お前、ヴィクターの——",v:"07_0085"},{w:"marco",t:"今、それ、いいっす。バケツ、次に回してもらえます？",v:"07_0086"},{w:"nina",t:"ドローンが来た。写真に写る前に、行くよ。",v:"07_0092"},{w:"x",n:"森番のおばあさん",t:"あのドローンが来るのは、いつも火が消えたあとなんだよ。",v:"07_0098"},{w:"x",n:"作業員のおじさん",t:"写真を撮って、道を閉めて、それでおしまいだからな。",v:"07_0099"},{w:"elly",t:"アレク、これ。ヤニスさんの木に引っかかってたのと、同じだよ。",v:"07_0102"},{w:"alek",t:"ああ。あいつら、この森で、また何か集めてるんだ。",v:"07_0103"}];
GR_SC.g07_04=[{w:null,t:"ラドン川。この秋は、夜になると、川から歌が聞こえる。",v:"07_0107"},{w:null,t:"森の外がわを流れる川。"},{w:null,t:"アレク、ヤマトの左の手首を、ぐいと引っぱる。"},{w:"alek",t:"ヤマト、地図を出してくれ。",v:"07_0110"},{w:"alek",t:"場所を知らせるのは、切ったままでな。",v:"07_0111"},{w:"hero",t:"わかってるって。毎回それ言うじゃん。",v:"07_0112"},{w:null,t:"ヤマトの手首から、光の地図が宙に広がる。"},{w:"alek",t:"森の中の道は、閉められた。",v:"07_0114"},{w:"alek",t:"でも川を下れば、森の向こうの外れまで行ける。",v:"07_0115"},{w:"elly",t:"じゃあ、あの船に乗るんだね！",v:"07_0116"},{w:null,t:"船着き場に、白い小さな観光船。"},{w:null,t:"切符の機械。"},{w:null,t:"アレク、数字を見たまま、口をへの字にする。"},{w:null,t:"ヤマト、横から左の手首をさし出す。"},{w:"hero",t:"足りないんなら、おれの画面で払おうか。",v:"07_0121"},{w:"alek",t:"だめだって！",v:"07_0122"},{w:"alek",t:"お前の画面で払ったら、ここにいるってばれるだろ！",v:"07_0123"},{w:"alek",t:"ヴィクターに、自分から知らせてどうするんだよ！",v:"07_0124"},{w:"hero",f:"serious",t:"……あ、そっか。",v:"07_0125"},{w:"alek",t:"このカードには名前がついてない。",v:"07_0126"},{w:"alek",t:"だから、だれが乗ったかは残らないんだ。",v:"07_0127"},{w:null,t:"アレク、カードを内ポケットにもどす。"}];
GR_SC.g07_05=[{w:null,t:"白い小さな観光船。だれも舵をにぎっていない。"},{w:null,t:"エリー、カメラの夫婦の奥さんに、頭を下げる。"},{w:"elly",t:"すみません。",v:"07_0133"},{w:"elly",t:"お姉ちゃんに、一言だけ電話したいんです。",v:"07_0134"},{w:"elly",t:"手首の画面を、少し貸してもらえませんか。",v:"07_0135"},{w:"x",n:"夫婦の奥さん",t:"いいわよ。短くね。",v:"07_0136"},{w:null,t:"エリー、借りた画面に小さな声で話す。二回うなずいて、すぐに返す。"},{w:null,t:"案内のロボットが、かごを持って回っている。"},{w:"x",n:"案内のロボット",t:"このあと「歌の瀬」を通ります。",v:"07_0139"},{w:"x",n:"案内のロボット",t:"歌を聞いたテリオンは、岸へ歩いていくことがございます。",v:"07_0140"},{w:"x",n:"案内のロボット",t:"お客さまも、お連れのテリオンも、こちらをどうぞ。",v:"07_0141"},{w:null,t:"エリー、髪の中のピリポンに、小さな耳あてをかぶせる。"},{w:null,t:"エリーがフォルンにも耳あてを持っていく。"},{w:null,t:"ヤマトだけ、耳せんを取らない。"},{w:"elly",t:"ヤマト、耳せんしないの？",v:"07_0145"},{w:"elly",t:"歌を聞いたら、川に入っちゃうんだよ。",v:"07_0146"},{w:"hero",t:"だって、どんな歌か聞いてみたいじゃん。",v:"07_0147"},{w:"alek",t:"聞いたら、お前が川に飛びこむって言ってるんだよ！",v:"07_0148"},{w:null,t:"ヤマト、船のまん中の太い柱を見上げる。"},{w:"hero",t:"じゃあさ、あの柱におれをしばっといてよ。",v:"07_0150"},{w:"hero",t:"それなら、飛びこめないだろ。",v:"07_0151"},{w:"alek",t:"……お前、本気で言ってるのか。",v:"07_0152"},{w:"hero",t:"本気だって。いちおう、かたく結んどいて。",v:"07_0153"},{w:null,t:"アレク、長いあいだヤマトを見る。それから、荷物どめのロープで、柱にぐるぐる、ぎゅっ。"},{w:"alek",t:"言っとくけど、歌が終わるまで、ほどかないからな。",v:"07_0155"},{w:"hero",t:"いいよ。おれ、そんなのに負けないもん。",v:"07_0156"},{w:null,t:"アレク、結び目を、もう一つ足す。"},{w:null,t:"案内のロボットが、船のまん中で話しはじめる。"},{w:"x",n:"案内のロボット",t:"この川には、昔から歌の話がございます。",v:"07_0159"},{w:"x",n:"案内のロボット",t:"海の岩の上で歌う、鳥の体をした女の人たちのお話です。",v:"07_0160"},{w:"x",n:"案内のロボット",t:"その歌を聞いた船乗りは、船ごと岩へ寄っていってしまう。",v:"07_0161"},{w:"x",n:"案内のロボット",t:"そこで船長は、自分を帆柱にしばらせて、歌を聞いたそうです。",v:"07_0162"},{w:null,t:"客の何人かが、柱のヤマトを見る。ヤマトは、背中の手でロープの結び目をさぐっている。"},{w:"x",n:"案内のロボット",t:"また、この森のそばの山にも、お話がございます。",v:"07_0164"},{w:"x",n:"案内のロボット",t:"生まれたその日に、牛をうしろ向きに歩かせた神さまです。",v:"07_0165"},{w:"x",n:"案内のロボット",t:"まだ赤ちゃんの、子どもの神さまでした。",v:"07_0166"},{w:"x",n:"案内のロボット",t:"足あとで、大人をだましたそうです。",v:"07_0167"},{w:"elly",t:"赤ちゃんなのに、大人をだましたんだって！",v:"07_0168"},{w:"elly",t:"すっごく、かしこいね。",v:"07_0169"},{w:"hero",t:"うしろ向きに歩くくらい、おれだってできるけど。",v:"07_0170"},{w:"elly",t:"ヤマトは、今、柱から一歩も動けないでしょ。",v:"07_0171"},{w:null,t:"ヤマト、また結び目をさぐる。"}];
GR_SC.g07_06=[{w:null,t:"川幅が広くなる。"},{w:null,t:"歌が聞こえてくる。"},{w:null,t:"岸の葦のあいだから、野生の子たちが出てくる。"},{w:null,t:"ヤマトの目が、その子たちを追う。"},{w:"hero",t:"ちょっと、ほどいて！　ちょっとだけでいいから！",v:"07_0182"},{w:null,t:"だれも、ふり向かない。"},{w:"hero",t:"エリー！　ほどいてって！　エリーってば！",v:"07_0184"},{w:null,t:"エリー、ヤマトに気づく。にこにこして、手をふり返す。"},{w:"hero",t:"ちがーう！！",v:"07_0186"},{w:null,t:"ヤマト、柱ごと岸の方へ体を投げ出そうとする。"},{w:null,t:"船べりで、フォルンが頭を上げる。耳が、ぺたんと寝ている。"},{w:null,t:"船は、岸の大きな岩のすぐ横を通っている。"},{w:null,t:"フォルン、立ち上がる。"},{w:null,t:"岩の上に着地。"},{w:null,t:"フォルン、線に、がぶっとかみつく。首をひとふり。"},{w:null,t:"ばちっ。火花。"},{w:null,t:"ぷつっ。歌が、途中で止まる。"},{w:null,t:"川の中の子たちが、歩きかけた足のまま止まる。はっと目をさまして、ばらばらに、ばしゃばしゃと岸へもどっていく。"},{w:null,t:"フォルン、口から線をぺっと吐く。前足で、口のまわりをこする。"},{w:null,t:"ヤマト、ロープにぶら下がるように、ぐったりする。"},{w:null,t:"アレク、望遠鏡をおろして、耳せんを片方だけ外す。"},{w:"alek",t:"なんだよ、ずっと口が動いてたけど。何か言ってたのか？",v:"07_0199"},{w:"hero",f:"serious",t:"……べつに。ぜんぜん、平気だったし。",v:"07_0200"}];
GR_SC.g07_07=[{w:"x",n:"案内のロボット",t:"機械の確認のため、こちらで少し停まります。",v:"07_0203"},{w:null,t:"観光船が岩に寄る。"},{w:null,t:"箱は横だおし。"},{w:null,t:"アレクがしゃがんで、手のひらほどの光る板で、箱の底を照らす。"},{w:null,t:"エリー、カバンから、昼に拾った網の切れはしを出す。"},{w:null,t:"エリー、箱の丸い穴を見る。それから、葦の方を見る。"},{w:"elly",t:"あの子たち、歌に呼ばれて、どこへ歩いていくところだったの？",v:"07_0209"},{w:null,t:"アレク、札の字を、指でなぞる。"},{w:"alek",t:"……森の奥だ。",v:"07_0211"},{w:null,t:"アレク、自分の左手の親指と人差し指のあいだを、右の親指でぎゅっとおさえる。"},{w:null,t:"ヤマト、ロープのあとの残る腕で、フォルンの首をなでようとする。"},{w:null,t:"ヤマト、なでかけた手のまま、ついていく。"}];
GR_SC.g07_08=[{w:null,t:"最後の船着き場。"},{w:null,t:"岸から上がる道に、また、細い柱が二本。"},{w:"hero",f:"surprised",t:"うそだろ、ここも通行止めなの？",v:"07_0219"},{w:"alek",t:"森の中の道は、全部閉めたんだろ。",v:"07_0220"},{w:"alek",t:"今夜は、どこか寝る所をさがすしかない。",v:"07_0221"},{w:null,t:"アレク、道のわきの少しはなれた所を見る。"},{w:null,t:"明かりの方へ歩く。"},{w:null,t:"そのはしに、小さな組み立て式の小屋。"},{w:null,t:"小屋のうしろの夜空に、背の高い鉄の骨組みが、まっすぐ立っている。"},{w:null,t:"骨組みの足もとに、空中の文字。"},{w:null,t:"エリー、小屋の戸を、こんこんとたたく。"},{w:"x",n:"女の人",t:"……こんな夜ふけに、何の用？",v:"07_0229"},{w:"elly",t:"こんばんは！　今夜、泊まれる所はありませんか！",v:"07_0230"},{w:"alek",t:"森の道が閉められて、行く所がないんです。",v:"07_0232"},{w:"alek",t:"床で寝かせてもらえるだけで、助かります。",v:"07_0233"},{w:"x",n:"女の人",t:"……床でいいなら、入って。",v:"07_0236"}];
GR_EP[7]={"t": "ラドン川の歌", "sc": [["g07_01", "アルカディアの森・川べりの岩（5日目の昼）", 0], ["g07_02", "アルカディアの森の入口（6日目の昼すぎ）", 0], ["g07_03", "森の中（昼すぎ）", 0], ["g07_04", "川の船着き場（夕方）", 0], ["g07_05", "観光船の上（夜）", 0], ["g07_06", "歌の瀬（夜）", 0], ["g07_07", "岸の大岩（夜）", 0], ["g07_08", "森の外れの船着き場（夜ふけ）", 0]]};
GR_SC.g08_01=[{w:null,t:"まだ暗い。ひもで四角く区切った地面の中で、明かりが一つ動いている。"},{w:null,t:"頭に小さな明かりをつけた研究者が、土の中にしゃがんでいる。"},{w:null,t:"土の中から、白っぽい、丸い物が出てくる。"},{w:null,t:"研究者、ブラシを止める。"},{w:null,t:"穴の奥は、まっ暗。"},{w:null,t:"第8話　巨人の骨",v:"08_0023"}];
GR_SC.g08_02=[{w:null,t:"アルカディアの森の外れ。化石の発掘場。",v:"08_0029"},{w:null,t:"組み立て式の小屋の床。"},{w:null,t:"棚に、箱がぎっしり。"},{w:null,t:"戸があいて、研究者が入ってくる。顔も腕も、きのうの夜と同じに、土でまっ黒。"},{w:"kenkyu",t:"朝ごはん、パンしかないけど、それでいい？",v:"08_0033"},{w:null,t:"ヤマト、むくっと起きる。"},{w:"hero",t:"パン！　食べる食べる！",v:"08_0035"},{w:null,t:"テーブルに、かたいパンと、水。"},{w:"elly",t:"研究者さんは、ずっと、ひとりで掘ってるの？",v:"08_0037"},{w:"kenkyu",t:"ずっと、ひとり。もう三年になるかな。",v:"08_0038"},{w:"elly",t:"掘るのって、ロボットにやってもらわないの？",v:"08_0039"},{w:"kenkyu",t:"前に、やらせてみた。",v:"08_0040"},{w:"kenkyu",t:"骨も石も、ぜんぶ同じ「石」の箱に入れちゃったの。",v:"08_0041"},{w:null,t:"研究者、窓の外をあごでさす。"},{w:"kenkyu",t:"骨と石の見分けは、まだ人の目の方が確かなの。",v:"08_0043"},{w:"kenkyu",t:"だから、それからは手で掘ってる。",v:"08_0044"},{w:null,t:"アレク、窓の外を見ている。"},{w:null,t:"小屋の軒下の壁ぎわに、ひとり用の寝床のカプセルが一つ、ふたを閉めて置いてある。"},{w:"alek",t:"あの鉄の骨組みは、何を建てているんですか。",v:"08_0047"},{w:"kenkyu",t:"電波の塔だって。",v:"08_0048"},{w:"kenkyu",t:"半年前から、こんな森の外れに、勝手に建ちはじめたの。",v:"08_0049"},{w:"elly",t:"（軒下のカプセルを見て）あそこの寝床は、だれが使ってるの？",v:"08_0050"},{w:"kenkyu",t:"塔の工事の人の子。",v:"08_0051"},{w:"kenkyu",t:"宿まで歩くと一時間かかるから、夜だけあそこで寝てる。",v:"08_0052"},{w:"kenkyu",t:"（三人に）それと、掘ってる所には、さわらないでね。ひもの中は、だめ。",v:"08_0053"}];
GR_SC.g08_03=[{w:null,t:"ひもで四角く区切った穴が、いくつも並んでいる。"},{w:null,t:"ヤマト、ひものまわりを、うろうろしている。"},{w:"elly",t:"ヤマト、ひもの中はだめって言われたでしょ。",v:"08_0058"},{w:"hero",t:"だから、ひもの外で掘るんだよ。外なら、いいんだろ。",v:"08_0059"},{w:null,t:"ヤマト、ひもの外の、草の生えた所にしゃがむ。"},{w:"hero",t:"化石なんてさ、どこにでも埋まってんだって。",v:"08_0061"},{w:"hero",t:"こういう、だれも見てない所に——",v:"08_0062"},{w:null,t:"スコップの先に、かちん。"},{w:"hero",t:"ほら、言ったとおりだろ！",v:"08_0064"},{w:null,t:"ヤマト、両手で掘る。"},{w:null,t:"エリーが、パンをかじりながら、穴の上からのぞいている。"},{w:null,t:"穴の中から、ヤマトが、白い石を両手で持ち上げる。"},{w:"hero",t:"見て！　骨！　でっかい骨！",v:"08_0068"},{w:null,t:"エリー、少しのあいだ見る。"},{w:"elly",t:"それ、さっき研究者さんが、いらないって投げてた石だよ。",v:"08_0070"},{w:null,t:"ヤマト、石を見る。"},{w:null,t:"ヤマト、石を置く。"},{w:null,t:"穴は、ヤマトの背より深くなっている。"},{w:"hero",f:"serious",t:"……エリー、手。手、かして。",v:"08_0074"},{w:null,t:"エリー、手をのばす。"},{w:null,t:"ヤマト、髪を立てたまま、だまってエリーを見上げる。"},{w:null,t:"アレク、遠くの小屋の前で、古い望遠鏡で塔のてっぺんをのぞいたまま、こちらを見もしない。"},{w:"hero",t:"アレク！　おーい、アレク！",v:"08_0078"},{w:"alek",t:"自分で掘った穴だろ！　自分で出てこいよ！",v:"08_0079"},{w:null,t:"穴のふちに、影がさす。"},{w:null,t:"黄色い毛に、黒いぎざぎざのしま。"},{w:null,t:"となりに、少年が一人。"},{w:"x",n:"少年",t:"……そんな穴の中で、なにしてんの。",v:"08_0083"},{w:"hero",f:"serious",t:"……化石、掘ってた。",v:"08_0084"},{w:null,t:"少年、トラの子の背中を、指で一回たたく。トラの子が、穴のふちに腹ばいになって、しっぽを穴の中へ垂らす。"},{w:null,t:"ヤマト、しっぽをつかむ。"},{w:"hero",t:"いっ——",v:"08_0087"},{w:null,t:"トラの子、立ち上がる。ヤマト、しっぽにぶら下がったまま、穴から引き上げられる。"},{w:null,t:"少年、ヤマトの顔を見る。"},{w:"x",n:"少年",t:"お前、となりのクラスのやつだろ。",v:"08_0090"},{w:"hero",t:"え？　……だれだっけ。",v:"08_0091"},{w:"x",n:"少年",t:"レン。四組の。",v:"08_0092"},{w:"hero",t:"おれ、三組なんだけど。",v:"08_0093"},{w:"dimi",t:"だから、となりのクラスだって言ってんだろ。",v:"08_0094"},{w:"hero",t:"なんで四組のやつが、ギリシャなんかにいんの？",v:"08_0095"},{w:"dimi",t:"父さんが、あそこの塔を建ててるんだ。",v:"08_0096"},{w:null,t:"レン、鉄の骨組みをあごでさす。"},{w:"dimi",t:"昼は、塔の下の見回りを手伝ってる。おれとライガで。",v:"08_0098"},{w:"hero",f:"serious",t:"……え、お前、ひとりで来てんの？",v:"08_0099"},{w:"dimi",t:"ひとりじゃない。ライガがいる。",v:"08_0100"},{w:null,t:"ライガ、ヤマトのにおいをかぐ。それから、ヤマトのうしろのフォルンを見る。"}];
GR_SC.g08_04=[{w:null,t:"発掘場のはしの、骨をしまう小屋。"},{w:null,t:"アバンの、大きな丸い骨。"},{w:"elly",t:"これ……もしかして、顔？",v:"08_0107"},{w:"kenkyu",t:"頭の骨。大昔の生き物のね。",v:"08_0108"},{w:null,t:"ヤマト、穴をのぞく。"},{w:"hero",t:"目、一個しかないじゃん。",v:"08_0110"},{w:"kenkyu",t:"大昔の人も、そう思ったの。",v:"08_0111"},{w:"kenkyu",t:"こういう骨を見て、一つ目の巨人の話を作った。",v:"08_0112"},{w:"hero",t:"じゃあ、巨人って、ほんとにいたの？",v:"08_0113"},{w:"kenkyu",t:"ううん。これは、象の頭。",v:"08_0114"},{w:"hero",t:"象？",v:"08_0115"},{w:"kenkyu",t:"まん中の穴は、目じゃなくて、鼻の穴。",v:"08_0116"},{w:null,t:"ヤマト、穴を見る。"},{w:"hero",f:"serious",t:"……象の鼻って、ここから出てんの？",v:"08_0118"},{w:"kenkyu",t:"出てる。ここから、長くね。",v:"08_0119"},{w:null,t:"エリー、台のすみの小さな箱の中を、のぞいている。"},{w:null,t:"エリー、指で土をはらう。口が、自然に動く。"},{w:"elly",t:"「この子は、わたしたちの言葉しか聞かない。」",v:"08_0122"},{w:null,t:"研究者の、シートをたたんでいた手が、止まる。"},{w:null,t:"研究者、エリーを見る。"},{w:"kenkyu",t:"……わたし、それを読むのに三日かかったんだけど。",v:"08_0125"},{w:"kenkyu",t:"古い字の辞書と、ずっと見くらべて。",v:"08_0126"},{w:"elly",t:"なんかね、見たら読めた。",v:"08_0127"},{w:null,t:"エリー、石を箱にもどす。"},{w:null,t:"研究者は、エリーの横顔を見たまま。"},{w:null,t:"ヤマトは、象の骨の鼻の穴に、腕を入れて、長さをはかっている。"},{w:null,t:"レンは、エリーを少しだけ見て、それから、手首の画面の時刻を見る。"}];
GR_SC.g08_05=[{w:null,t:"小屋の中。研究者が、電気の鍋で豆を煮ている。"},{w:null,t:"森の外では、火を使えない。熱を見るドローンが、夜も飛んでいる。",v:"08_0138"},{w:null,t:"レンも、テーブルのはしに座っている。"},{w:"kenkyu",t:"レン、お父さんは、今夜も上なの？",v:"08_0140"},{w:"dimi",t:"うん。塔の上で、朝まで。",v:"08_0141"},{w:null,t:"フォルンが、窓ぎわの平たい石の上で、しっぽの火でオリーブを焼いている。"},{w:null,t:"アレクは、クロッコに煮た魚を指で食べさせている。"},{w:null,t:"ライガが、のそっと立ち上がる。"},{w:null,t:"フォルンの首のまわりの毛が、ぼっと燃え上がる。しっぽが、ぴんと立つ。"},{w:null,t:"ライガの毛の先が、ばちばちっと光る。"},{w:"hero",t:"フォルン、やめろって。",v:"08_0147"},{w:null,t:"フォルン、止まらない。"},{w:null,t:"レン、座ったまま、人さし指を一本だけ、すっと立てる。"},{w:null,t:"ライガ、ぴたりと止まる。"},{w:null,t:"フォルンは、まだ、ライガをにらんでいる。"},{w:"hero",t:"やめろってば。もう向こうに行ったじゃん。",v:"08_0152"},{w:"elly",t:"ねえ、レンも、白い都の大会に出るの？",v:"08_0157"},{w:"dimi",t:"出るよ。そのために、父さんについてきたんだ。",v:"08_0158"},{w:"hero",f:"serious",t:"……おれも、出るし。",v:"08_0159"},{w:"dimi",t:"その狐、だれのテリオンなんだよ。",v:"08_0161"},{w:"hero",f:"serious",t:"……優勝したら、おれのになるの。",v:"08_0162"},{w:"dimi",t:"（立ち上がって）おれ、もう寝る。あしたも、朝から見回りだから。",v:"08_0166"}];
GR_SC.g08_06=[{w:null,t:"鍋の火は、もう切ってある。"},{w:null,t:"研究者が、三人の顔を、順に見る。それから、窓の外のカプセルの方を一度見る。"},{w:null,t:"研究者、声を落とす。"},{w:"kenkyu",t:"昼の、あの石の字のことなんだけど。",v:"08_0175"},{w:"elly",t:"うん。",v:"08_0176"},{w:"kenkyu",t:"ああいう字の時代の子がね、一度よみがえったの。",v:"08_0177"},{w:"hero",t:"テリオンが？",v:"08_0178"},{w:"kenkyu",t:"五十年くらい前の話。",v:"08_0179"},{w:"kenkyu",t:"骨の中にね、その生き物の設計図が残ってることがあるの。",v:"08_0180"},{w:"hero",t:"設計図って、家とかの？",v:"08_0181"},{w:"kenkyu",t:"生き物の設計図。それを読んで、体を印刷した人たちがいた。",v:"08_0182"},{w:"alek",t:"……化石の骨から、ですか。",v:"08_0183"},{w:"hero",t:"それ、強かった？",v:"08_0184"},{w:"kenkyu",t:"大きくて、強かった。でも、昔の言葉しか分からない。",v:"08_0185"},{w:"kenkyu",t:"何を言っても、聞かなかったの。",v:"08_0186"},{w:null,t:"ヤマト、窓ぎわのフォルンを見る。"},{w:"hero",t:"言うこと聞かないのなんて、ふつうじゃん。",v:"08_0188"},{w:"kenkyu",t:"ふつうの子は、おなかがすいたら寄ってくる。",v:"08_0189"},{w:"kenkyu",t:"あの子たちは、ごはんを出しても、こっちを見なかったって。",v:"08_0190"},{w:null,t:"アレク、望遠鏡をみがいていた手を止める。"},{w:"alek",t:"……それで、いなかったことにしたんですか。",v:"08_0192"},{w:"kenkyu",t:"まず、禁止。それから、いなかったことにした。",v:"08_0193"},{w:"kenkyu",t:"図鑑にも、ニュースにも、出てこない。",v:"08_0194"},{w:"elly",t:"じゃあ、その子たちは、どこに行っちゃったの？",v:"08_0195"},{w:"kenkyu",t:"どこかに、閉じこめられてる……っていう話。",v:"08_0196"},{w:"hero",t:"出してあげられないの？",v:"08_0197"},{w:"kenkyu",t:"どこにあるのかも、開け方も、だれにも分からないの。",v:"08_0198"},{w:"hero",f:"hurt",t:"……でも、いたってことは、分かってんじゃん。",v:"08_0199"},{w:"kenkyu",t:"分かってるのは、いたこと、だけ。",v:"08_0200"},{w:"kenkyu",t:"覚えてるのは、国の上の方の人と、骨を掘ってる人だけ。",v:"08_0201"},{w:"kenkyu",t:"わたしみたいなね。",v:"08_0202"},{w:null,t:"研究者、鍋のふたを、意味もなく一回あけて、閉める。"},{w:"kenkyu",t:"外でしゃべったら、わたしが捕まるから。",v:"08_0204"},{w:"hero",t:"じゃあ、なんで、おれたちに話したの？",v:"08_0205"},{w:null,t:"研究者、答えない。"},{w:null,t:"エリー、ぽかんとして、それから、にこっとする。"},{w:"elly",t:"わかった。ないしょね！",v:"08_0208"},{w:null,t:"研究者、少しだけ笑う。"},{w:null,t:"アレク、何も言わない。"},{w:null,t:"ヤマト、自分の左の手首の画面を、右の手のひらで、そっとおおう。"}];
GR_SC.g08_07=[{w:null,t:"小屋の明かりは消えている。"},{w:null,t:"遠くから、低いモーターの音。"},{w:null,t:"フォルンの耳が、ぴくっと立つ。"},{w:null,t:"ヤマトも、目をあける。"},{w:null,t:"発掘場の前の土の道を、黒いトラックが一台、明かりを消して走ってくる。"},{w:null,t:"トラックが、窓の前を通る。"},{w:null,t:"荷台の中から、鳴き声。"},{w:null,t:"トラックは、森の奥の方へ曲がっていく。"},{w:null,t:"ヤマト、体を起こす。"},{w:null,t:"エリー、シートの中で、目をあけている。"},{w:null,t:"小屋の軒下。"}];
GR_EP[8]={"t": "巨人の骨", "sc": [["g08_01", "発掘場（7日目・夜明け前）", 0], ["g08_02", "発掘場の小屋（朝）", 0], ["g08_03", "発掘場（昼前）", 0], ["g08_04", "骨の小屋（昼）", 0], ["g08_05", "小屋の中（夜）", 0], ["g08_06", "小屋の中（夜ふけ）", 0], ["g08_07", "小屋の窓（夜中）", 0]]};
GR_SC.g09_01=[{w:null,t:"森の外れの、化石の発掘場。",v:"09_0017"},{w:null,t:"きのうの夜中、窓のない黒いトラックが、この前の道を森の奥へ走っていった。",v:"09_0018"},{w:null,t:"朝もやの中、掘りかけの四角い穴がいくつも並ぶ。"},{w:null,t:"小屋の軒下の壁ぎわ。"},{w:null,t:"小屋の前の道。"},{w:null,t:"エリー、しゃがんで羽を拾う。"},{w:null,t:"ヤマト、わだちの前に仁王立ち。"},{w:"hero",f:"smile",t:"よし。こういうのは、おれにまかせとけって。",v:"09_0024"},{w:"hero",t:"タイヤのあとを追えばいいだけだろ。",v:"09_0025"},{w:null,t:"ヤマト、地面に顔を近づけて、細いわだちを一本見つける。"},{w:null,t:"細いわだちは、穴と穴のあいだをくねくね回って、小屋の裏へ。"},{w:null,t:"小屋の裏。小さな手押し車。"},{w:"kenkyu",t:"それ、わたしの一輪車のあとだよ。",v:"09_0029"},{w:null,t:"ヤマト、手押し車を見る。"},{w:null,t:"小屋の表から、アレクの声。"},{w:"alek",t:"ヤマト、そっちじゃない！　こっちだって！",v:"09_0032"},{w:null,t:"アレク、深い二本のわだちの先、森の奥へ続く道のまん中に立っている。"},{w:"alek",t:"このわだち、深いだろ。荷台が重かったんだ。",v:"09_0034"},{w:"alek",t:"檻を積んでたんだよ。",v:"09_0035"},{w:null,t:"ヤマト、もどってくる。"},{w:"kenkyu",t:"その道は、地図に出てこないよ。",v:"09_0037"},{w:"kenkyu",t:"行くなら、帰りにわたしの一輪車を押してってね。",v:"09_0038"},{w:"alek",t:"すみません。帰りは、たぶん、ここは通りません。",v:"09_0039"},{w:null,t:"研究者の手が、一度だけ止まる。それから、また骨の土を払う。"},{w:"alek",t:"（ヤマトとエリーに）この道は、前に一度、通ったことがあるんだ。",v:"09_0042"},{w:null,t:"第9話　森の奥の施設",v:"09_0044"}];
GR_SC.g09_02=[{w:null,t:"森の奥へ続く、地図に出てこない道。空の上を、配達のドローンが行きかっている。",v:"09_0050"},{w:null,t:"先頭はアレク。"},{w:"hero",t:"なあ、アレク。ヴィクターにいたころって、どんな仕事してたの？",v:"09_0052"},{w:"alek",t:"荷物の案内だよ。",v:"09_0053"},{w:"alek",t:"どの道を通れば見つからないか、車に教える仕事だ。",v:"09_0054"},{w:"hero",t:"荷物って、何の荷物？",v:"09_0055"},{w:"alek",t:"……檻だよ。中に、子が入ってる檻。",v:"09_0056"},{w:null,t:"ヤマト、それ以上聞かない。"},{w:null,t:"エリーは、さっきの羽を、指先でくるくる回している。"},{w:"elly",t:"ねえ、アレク。歌で連れてこられた子たちは、また森に帰れるの？",v:"09_0059"},{w:"alek",t:"それを、今から見に行くんだ。",v:"09_0060"},{w:null,t:"道のわきに、新しい看板。"},{w:null,t:"フォルンが、看板の前で足を止める。"},{w:null,t:"ヤマト、フォルンの横にしゃがむ。"},{w:"hero",t:"フォルン、どうしたんだよ。ここ、来たことあんのか？",v:"09_0064"},{w:null,t:"フォルン、看板から目をはなさない。"},{w:"alek",t:"においで分かるんだろ。檻のにおいが、この先からしてくるんだ。",v:"09_0066"},{w:null,t:"道の先の木の上に、黒いカメラが一つ。"},{w:null,t:"ヤマト、自分の上着をぬいで、フォルンの頭の上に、ばさっとかぶせる。フォルン、首をふって、すぐ落とす。"},{w:null,t:"三回目。フォルン、上着をくわえて、ヤマトの顔にかぶせ返す。"}];
GR_SC.g09_03=[{w:null,t:"森を切りひらいた広場。看板も、マークもない建物があった。",v:"09_0073"},{w:null,t:"窓のない、灰色の四角い建物。"},{w:null,t:"前の広場に、黒いトラックが三台、横に並んでいる。"},{w:null,t:"門の横の小さな見張り小屋に、人が一人。"},{w:null,t:"三人と三体は、広場のはしの茂みにしゃがんでいる。"},{w:"hero",t:"なんだ、人なんて一人しかいねえじゃん。",v:"09_0078"},{w:"alek",t:"ほかは、全部機械がやってるんだ。だから、人は一人でいい。",v:"09_0079"},{w:"hero",t:"じゃあ、正面から行っても、平気なんじゃね？",v:"09_0080"},{w:"alek",t:"門の上を見ろよ。カメラがこっちを向いてるだろ。",v:"09_0081"},{w:null,t:"門の柱の上に、黒いカメラ。"},{w:null,t:"アレク、茂みの中を、建物の裏へ回っていく。"}];
GR_SC.g09_04=[{w:null,t:"建物の裏。ゴミの箱が並ぶ、灰色の戸。"},{w:null,t:"アレク、左手をひらいて、親指と人差し指のあいだの水かきを、板にかざす。"},{w:null,t:"板の字。「アレク　登録が取り消されています」。"},{w:null,t:"アレク、手をにぎって、ひっこめる。"},{w:"hero",t:"なんだよ、追い出されてんじゃん。",v:"09_0090"},{w:"alek",t:"追い出されたんじゃない！　自分でやめたんだって！",v:"09_0091"},{w:"alek",t:"それに、取り消されてても、かざしたことは記録に残る。急ぐぞ。",v:"09_0092"},{w:null,t:"ぶうん、と音がして、灰色の戸が内側から開く。"},{w:null,t:"三人、ゴミの箱のかげに固まる。"},{w:null,t:"エリーだけ、かげから出る。"},{w:"hero",t:"（小声で）おい、エリー！　見つかるって！",v:"09_0096"},{w:"elly",t:"おはよう。毎日ひとりでお掃除して、たいへんだね。",v:"09_0098"},{w:"x",n:"掃除のロボット",t:"ドウゾ。",v:"09_0101"},{w:"hero",t:"ごくろうであった！",v:"09_0105"}];
GR_SC.g09_05=[{w:null,t:"建物の二階に、ガラス張りの通路が一本。",v:"09_0110"},{w:null,t:"下の部屋を、上から見られるように作ってある。",v:"09_0111"},{w:null,t:"白い通路。床に、外国の言葉の案内が三つ。"},{w:null,t:"三人、ガラスにくっつくようにして、下を見る。"},{w:null,t:"下は、長い長い流れ作業の部屋。"},{w:null,t:"檻が止まる。"},{w:null,t:"じたばたしていた羽の子の足が、止まる。目が、静かになる。"},{w:null,t:"次の檻。しっぽの子。"},{w:null,t:"次。角の子。"},{w:null,t:"エリーの両手が、ガラスに当たっている。"},{w:null,t:"フォルンの背中の毛が、しっぽの付け根から、ぞわっと逆立つ。"},{w:null,t:"ヤマト、フォルンの背中に、手のひらを置く。"},{w:null,t:"アレクは、下の部屋のすみの画面を見ている。"},{w:"hero",t:"なあ、あれって……チップ？",v:"09_0123"},{w:"alek",t:"ヴィクターのチップだ。",v:"09_0124"},{w:"alek",t:"クロッコの耳のうしろに入ってたのと、同じやつだよ。",v:"09_0125"},{w:"alek",t:"あれを入れられると、向こうの命令が、そのまま届くようになる。",v:"09_0126"},{w:"x",n:"係の男の声",t:"主任、歌で集めた子が四十二体です。",v:"09_0130"},{w:"x",n:"係の男の声",t:"きょう中に全部、入れちまいますか。",v:"09_0131"},{w:"x",n:"ノモスの声",t:"……確認します。",v:"09_0132"},{w:"x",n:"ノモスの声",t:"上に聞かないと、決められません。決まりですから。",v:"09_0134"},{w:"x",n:"係の男の声",t:"……はい。",v:"09_0135"}];
GR_SC.g09_06=[{w:null,t:"通路のつきあたり。"},{w:null,t:"アレク、板の前で止まる。自分の左手を見て、にぎる。"},{w:null,t:"うしろから、ころころ、と音。"},{w:"elly",t:"あっ、さっきの子だ。また会えたね。",v:"09_0147"},{w:null,t:"ロボットが戸の前に来ると、ぴっ、と小さな音。"},{w:null,t:"アレク、エリーを見る。"},{w:null,t:"三人、戸をくぐる。"},{w:null,t:"白い部屋。まん中に、ガラスのケース。"},{w:null,t:"奥の壁。ぶあつい金属の壁が、内側から外へ、大きくめくれている。"},{w:null,t:"掃除のロボットは、裂け目の前の床を、くり返しくり返しふいている。"},{w:null,t:"壁の画面に、記録の字が流れている。"},{w:"alek",t:"「古代の試験。化石の骨から、小さく印刷した子」。",v:"09_0155"},{w:"alek",t:"「チップで命令を入れたとたん、暴れだした」。",v:"09_0156"},{w:"alek",t:"「試験は中止」。",v:"09_0157"},{w:null,t:"ヤマト、めくれた壁の前に立つ。"},{w:"hero",t:"化石の子って、研究者さんが話してた、あれだよな。",v:"09_0159"},{w:"hero",t:"チップを入れても、言うこと聞かなかったんだ。",v:"09_0160"},{w:"elly",t:"（画面を指でなぞって）見て。オリーヴァ村が、二つもあるよ。",v:"09_0164"},{w:"alek",t:"ヤマト、手首の地図を出して、この画面の前にかざしてみろ。",v:"09_0165"},{w:"elly",t:"「角のある子の家。」",v:"09_0173"},{w:"elly",t:"……ねえ、これ、競技場の扉と、ちょっと似てるね。",v:"09_0174"},{w:"alek",t:"まずい、今の声を録られた。すぐに出るぞ！",v:"09_0178"}];
GR_SC.g09_07=[{w:null,t:"細い廊下を、三人が早足で行く。"},{w:null,t:"エリーが、一つの窓の前で、止まる。"},{w:null,t:"窓の外。建物のうしろの広場に、黒い車がずらりと並んでいる。"},{w:null,t:"エリーは、笑っている。"},{w:null,t:"うしろから来たヤマトが、エリーの背中にぶつかる。"},{w:"hero",t:"おい、急に止まるなよ、エリー——",v:"09_0186"},{w:null,t:"ヤマト、エリーの横顔を見る。"},{w:null,t:"エリーの髪の中から、ピリポンが体を半分出して、エリーの首に、ぎゅっとしがみつく。"},{w:null,t:"エリーの足が、動く。"},{w:null,t:"ヤマト、窓の外の黒い車を、もう一度だけ見る。それから、エリーのあとを追う。"}];
GR_SC.g09_08=[{w:null,t:"天井の高い倉庫。"},{w:null,t:"倉庫の向こうに、大きな搬出の戸。"},{w:null,t:"エリーが、いちばん手前の檻の前にしゃがむ。"},{w:null,t:"エリー、カバンから羽を出して、柵のすきまから中へ入れる。"},{w:"elly",t:"アレク、この子たち、出してあげようよ。",v:"09_0197"},{w:"alek",t:"だめだ。一つでも開けたら、全部の警報が鳴るんだよ。",v:"09_0198"},{w:"elly",t:"じゃあ、全部いっぺんに開けよう。",v:"09_0199"},{w:"elly",t:"そしたら、みんな逃げられるでしょ。",v:"09_0200"},{w:null,t:"アレク、エリーを見る。エリー、本気の顔で、にこにこしている。"},{w:"hero",t:"（もう檻の留め金をさわりながら）これって、どうやって開けんの？",v:"09_0202"},{w:"alek",t:"さわるなって！　お前がさわると、ろくなことにならないんだよ！",v:"09_0203"},{w:null,t:"アレク、倉庫の柱を見回す。"},{w:null,t:"アレク、赤い箱の前に立つ。ガラスのふたに手をかけて、一度だけ、止まる。"},{w:"x",n:"係の男",t:"主任！　檻が……檻が全部、開いちまいました！",v:"09_0214"}];
GR_SC.g09_09=[{w:null,t:"施設の屋根から、ヴィクターの黒いドローンが四機、飛び立った。",v:"09_0219"},{w:null,t:"森が深くなる。"},{w:null,t:"森の中を、三人と三体が走る。"},{w:null,t:"黒いドローン（オレンジの輪）は、葉の屋根の上を飛んでいる。"},{w:"alek",t:"あいつら、足あとを読んで追ってきてる。",v:"09_0223"},{w:"alek",t:"この泥じゃ、足あとは消せない。",v:"09_0224"},{w:null,t:"道が、平らな岩場を横切る。"},{w:null,t:"岩場の向こうは、また泥。"},{w:null,t:"ふり返る。岩場の手前の泥に、自分たちのくつのあと。"},{w:null,t:"ヤマト、くるっと回る。"},{w:"alek",t:"おい、こんな時に、何やってるんだよ！",v:"09_0229"},{w:"hero",t:"うしろ向きに歩いてんの。",v:"09_0230"},{w:"hero",t:"こうすれば、足あとが施設の方に向くだろ。",v:"09_0231"},{w:null,t:"アレク、ヤマトの足もとを見る。"},{w:null,t:"エリーの顔が、ぱっと明るくなる。"},{w:"elly",t:"牛をうしろ向きに歩かせた、あの赤ちゃんと同じだ！",v:"09_0234"},{w:"hero",t:"ほらな。",v:"09_0242"},{w:"hero",t:"だから言っただろ、こういうのは、おれにまかせとけって。",v:"09_0243"}];
GR_SC.g09_10=[{w:null,t:"森がとぎれて、乾いた丘。"},{w:null,t:"ずぶぬれのヤマトが、上着をしぼっている。"},{w:"alek",t:"ヤマト、しぼるのはあとにして、地図を出してくれ。",v:"09_0254"},{w:null,t:"ヤマトの手首から、光の地図。"},{w:null,t:"アレク、白い都の印から、港の方へ、指をすべらせる。"},{w:"alek",t:"白い都は、湾の向こう側だ。",v:"09_0257"},{w:"alek",t:"陸をぐるっと回ってたら、大会の受付に間に合わない。",v:"09_0258"},{w:"hero",t:"じゃあ、ロボタクシーで行けばいいじゃん。",v:"09_0259"},{w:"alek",t:"だから、乗ったとたんに、だれがどこで乗ったか残るんだって！",v:"09_0260"},{w:"alek",t:"何回言わせるんだよ！",v:"09_0261"},{w:"elly",t:"じゃあ、船は？　湾をまっすぐ渡れるよ！",v:"09_0262"},{w:"alek",t:"人が自分で動かしてる船なら、名前を取らないこともある。",v:"09_0263"},{w:"alek",t:"港で、さがしてみよう。",v:"09_0264"},{w:"elly",t:"海の船って、わたし、初めて！",v:"09_0265"},{w:"hero",t:"船なら、おれにまかせとけって。",v:"09_0266"},{w:"alek",t:"お前、さっき小川に落ちたばっかりだろ！",v:"09_0267"},{w:null,t:"アレク、内ポケットからカードを出して、残高の数字を見る。"},{w:null,t:"エリーの肩で、ピリポンが、くるっと丸くなる。しっぽの先を、ぱちっと鳴らす。"},{w:null,t:"エリー、そのしっぽを、指でちょんとさわる。それから、光の地図の四つの印を見る。"},{w:null,t:"エリー、すぐ顔を上げる。"},{w:"elly",t:"行こ。港まで、もうすぐだよ。",v:"09_0272"},{w:null,t:"フォルン、もう丘を下りはじめている。しっぽの火が、夕方の坂でゆれる。"}];
GR_SC.g09_11=[{w:null,t:"明るい部屋。"},{w:null,t:"大きな画面に、森の施設の試験室の映像。"},{w:null,t:"画面のはしに、小さな窓。"},{w:null,t:"机の上の通信機から、男の声。"},{w:"x",n:"通信機の声",t:"森の施設からです。扉の文字が、読まれました。",v:"09_0280"},{w:"x",n:"通信機の声",t:"読んだのは、子どもです。",v:"09_0281"},{w:null,t:"白いスーツの袖。"},{w:"x",n:"エリーの声（記録）",t:"「角のある子の家。」",v:"09_0283"},{w:null,t:"指輪の指が、画面のエリーの顔に、とん、と止まる。"},{w:"x",n:"男の声（ヴィクター）",t:"……この子か。古い字が読めるっていうのは。",v:"09_0285"},{w:"x",n:"男の声（ヴィクター）",t:"へえ。きみ、才能あるね。",v:"09_0286"},{w:null,t:"指輪の手が、ケーキにフォークを入れる。"}];
GR_EP[9]={"t": "森の奥の施設", "sc": [["g09_01", "アルカディアの森の外れ・発掘場（8日目・夜明け）", 0], ["g09_02", "森の道（朝）", 0], ["g09_03", "森の奥・施設の前（朝）", 0], ["g09_04", "施設の裏口", 0], ["g09_05", "施設の中・見学の通路", 0], ["g09_06", "試験室", 0], ["g09_07", "施設の中・窓のある廊下", 0], ["g09_08", "施設の中・檻の部屋", 0], ["g09_09", "森の中（昼）", 0], ["g09_10", "森の出口（夕方）", 0], ["g09_11", "どこかの部屋（夜）", 0]]};
GR_SC.g10_01=[{w:null,t:"港町ナフリア。白い都へ渡る船は、ここから出る。",v:"10_0020"},{w:null,t:"青い湾。白い家並み。"},{w:null,t:"湾の向こうの長い防波堤の上を、大きな影がゆっくり歩いている。"},{w:null,t:"岸の、網をほす台の上に、ヤマト。"},{w:"x",n:"港の子1",t:"あ、タロスだ。今日も回ってる。",v:"10_0024"},{w:"x",n:"港の子2",t:"あのロボット、百年ずっと、港を回ってるんだって。",v:"10_0025"},{w:"x",n:"港の子3",t:"タロスって、昔の島の、青銅の巨人の名前なの。",v:"10_0026"},{w:"x",n:"港の子3",t:"うちのひいじいちゃんがつけたんだよ。",v:"10_0027"},{w:"hero",t:"でけえ。あれって、テリオンとも戦えんの？",v:"10_0028"},{w:"x",n:"港の子1",t:"戦わないよ。港のまわりを、歩いて見張ってるだけ。",v:"10_0029"},{w:null,t:"子どもたちの目が、台の下へ下りる。"},{w:"x",n:"港の子2",t:"その狐、お兄ちゃんのテリオン？",v:"10_0031"},{w:"hero",t:"そうだよ。おれの……っていうか、おれと旅してんの。",v:"10_0032"},{w:"x",n:"港の子2",t:"うそだあ。日本の子って、テリオンを持っちゃだめなんでしょ。",v:"10_0033"},{w:"x",n:"港の子2",t:"日本だけ、地図が白いって、学校で習ったもん。",v:"10_0034"},{w:null,t:"ヤマト、台の上で、一瞬だけ止まる。"},{w:"x",n:"港の子3",t:"じゃあ、その狐って、ほんとはだれのなの？",v:"10_0036"},{w:null,t:"子どもたちの目が、フォルンの耳のうしろへ行く。"},{w:"hero",t:"だから、おれのだって。",v:"10_0038"},{w:null,t:"子どもたちは、まだ耳のうしろを見ている。"},{w:null,t:"台の下で、フォルンがあくびをする。"},{w:null,t:"防波堤の上で、大きな影が、また一歩。"},{w:null,t:"第10話　港町ナフリア",v:"10_0043"}];
GR_SC.g10_02=[{w:null,t:"連絡船の乗り場の、空中の画面。"},{w:null,t:"画面の前で、アレクがパーカーの内ポケットから、手のひら大のうすいカードを出して見ている。"},{w:null,t:"アレク、カードを裏返して、もう一度表を見る。"},{w:"hero",t:"なあ、船っていくらなの？　足りる？",v:"10_0052"},{w:"alek",t:"三人で二百四十。カードに残ってるのは、五十二だ。",v:"10_0053"},{w:"hero",t:"じゃあ、湾のまわりを歩いていけばいいじゃん。",v:"10_0054"},{w:"alek",t:"湾を回ったら、山が二つだ。大会の受付に間に合わない。",v:"10_0055"},{w:"hero",t:"じゃあ、泳いで渡る。クロッコなら泳げるだろ。",v:"10_0056"},{w:"alek",t:"クロッコに三人引っぱらせる気かよ！　まだ本調子じゃないんだぞ。",v:"10_0057"},{w:null,t:"アレクの足もとで、クロッコが顔を上げる。"},{w:null,t:"エリーは、となりのくじの屋台の前にしゃがんでいる。"},{w:"elly",t:"ねえ、この子、かわいくない？　回るの見てるだけで楽しいよ。",v:"10_0060"},{w:"alek",t:"ボタンは押すなよ。一回三ジェムコインだ。",v:"10_0061"},{w:null,t:"広場の奥の桟橋に、白と青の少し古い連絡船。"},{w:"marina",t:"次はだれだい！　あたしに勝てば、向こう岸まで、ただだよ！",v:"10_0063"},{w:null,t:"甲板の手すりに、日焼けした女の人が足をかけている。"},{w:null,t:"船の横の海で、青いクジラが頭から潮をふいて、甲板を洗っている。"},{w:null,t:"潮のしぶきが風に乗って、広場まで飛んでくる。"},{w:null,t:"エリーの髪の中から、ピリポンが顔を出す。"},{w:null,t:"クジラが、きゅうっと鳴いて、桟橋の下へもぐる。"},{w:"elly",f:"sad",t:"ごめんね。この子、水がかかると、びっくりして光っちゃうの。",v:"10_0069"},{w:"marina",t:"あたしの子も同じだよ。電気がかかると、びっくりしてもぐるんだ。",v:"10_0070"},{w:"alek",t:"その船は、人が動かしているんですか。",v:"10_0071"},{w:"marina",t:"あたしが動かしてる。",v:"10_0072"},{w:"marina",t:"自動の操縦は切っちまったし、名簿もとらない。文句あるかい。",v:"10_0073"},{w:"alek",t:"ありません。そのほうが、ぼくたちは助かります。",v:"10_0074"},{w:null,t:"ヤマト、もう桟橋の根もとまで走っている。"},{w:"hero",t:"はい！　おれがやる！",v:"10_0076"},{w:"marina",t:"船長のマリナだよ。負けたら、船代はちゃんともらうからね。",v:"10_0077"},{w:null,t:"エリー、走ってくる。"},{w:"elly",t:"ピリポンも、いっしょに出ようか？",v:"10_0079"},{w:null,t:"ヤマト、広場のはしを見る。"},{w:"x",n:"港の子3",t:"その狐、お兄ちゃんの言うこと、ちゃんと聞くの？",v:"10_0081"},{w:null,t:"杭の下で、フォルンがそっぽを向いて、耳をかいている。"},{w:"hero",t:"いいよ、エリー。おれとフォルンだけでやる。",v:"10_0083"},{w:"alek",t:"おい、向こうは海の上から来るんだぞ！",v:"10_0084"},{w:"hero",t:"だったら、桟橋の上でやればいいだろ。",v:"10_0085"},{w:"alek",t:"クジラが桟橋に上がってくるわけないだろ！",v:"10_0086"},{w:"hero",t:"じゃあ、上がってくるまで待つ。",v:"10_0087"},{w:"alek",t:"待ってるあいだに、潮でびしょぬれだって！",v:"10_0088"},{w:null,t:"ヤマト、もう聞いていない。"},{w:null,t:"三回目。右のくつが、すぽんとぬける。"},{w:null,t:"アレクの足もとから、クロッコが、どぼんと海へ飛びこむ。"},{w:"alek",t:"おい、クロッコ！　くつなんか、追わなくていい！",v:"10_0092"},{w:null,t:"陸ではのそのそ歩くクロッコが、水の中では、すうっと速い。"},{w:null,t:"桟橋の横の海に、古い杭が一並び、頭を出している。"},{w:null,t:"港の口から、大きな波が一つ、入ってくる。"},{w:null,t:"クロッコ、とっさに杭にかみつく。"},{w:null,t:"アレク、桟橋のふちで、それをじっと見ている。"},{w:null,t:"くつは、流れていく。その下から、クジラが、ぷかっと顔を出す。"},{w:null,t:"クジラが潮をふく。"},{w:null,t:"網の子が、網で受ける。"}];
GR_SC.g10_03=[{w:null,t:"マリナ、甲板から船の横の海を指さす。クジラが、すうっと港の口の方へ出ていく。"},{w:null,t:"港の口の深い海。"},{w:null,t:"クジラ、沖の海で止まって、こちらを向く。"},{w:"marina",t:"この子が、うちのかしらだよ。この子が沈んだら、あんたの勝ち。",v:"10_0108"},{w:null,t:"ヤマト、片足だけはだしで、フォルンを桟橋の根もとに出す。"},{w:null,t:"クジラと向かい合ったとたん、フォルンの体から火の粉がふわっとあふれる。"},{w:null,t:"ヤマトの左の手首の画面で、時計の形のアイコンが光る。"},{w:"x",n:"港の子1",t:"うわ……でっかくなった。",v:"10_0112"},{w:null,t:"ヤマト、子どもたちをふり返って、胸をはる。"},{w:null,t:"桟橋の根もとに、エリーとアレク。"},{w:"marina",t:"じゃあ、始めるよ。",v:"10_0115"}];
GR_SC.g10_05=[{w:null,t:"マリナ、手すりから海へ飛びこむ。"},{w:null,t:"アレク、桟橋のふちにしゃがんで、手をのばす。"},{w:null,t:"アレク、パーカーのそでで、クロッコの鼻先の海水をふく。"},{w:null,t:"マリナ、船に上がってくる。"},{w:"marina",t:"勝ったのは、ワニだ。",v:"10_0199"},{w:"marina",t:"ワニの持ち主と、その連れはただ。あしたの昼の便だよ。",v:"10_0200"},{w:null,t:"マリナ、札を三枚、アレクに差し出す。それから、桟橋の先の狐を見る。"},{w:"marina",t:"狐は、負けた方だね。乗せるなら、狐の分は払ってもらう。",v:"10_0202"},{w:"alek",t:"はい。……狐の分は、いくらですか。",v:"10_0203"},{w:"marina",t:"テリオン一体、三十ジェムコイン。あしたまでに用意しな。",v:"10_0204"},{w:null,t:"マリナ、船の中へ入っていく。"},{w:null,t:"広場のはしには、だれもいない。"},{w:null,t:"ヤマト、桟橋の先まで、ゆっくり歩く。"},{w:null,t:"ヤマト、しゃがまない。"},{w:"hero",t:"なんで、跳ばなかったんだよ。杭なんて、すぐそこだっただろ。",v:"10_0209"},{w:null,t:"フォルン、ヤマトを見上げる。"},{w:"hero",t:"お前がちゃんと跳んでたら、おれたちが勝ってたんだぞ。",v:"10_0211"},{w:null,t:"エリーの肩で、ピリポンが、エリーの髪の中に頭から飛びこむ。"},{w:"elly",t:"ヤマト、今のは、ちがうよ。",v:"10_0213"},{w:null,t:"フォルン、しばらくヤマトを見ている。"},{w:"hero",f:"serious",t:"……フォルン、待て。",v:"10_0217"},{w:"elly",t:"フォルン！　待って！",v:"10_0220"},{w:"hero",t:"ほっとけよ。腹がへったら、自分で戻ってくるって。",v:"10_0223"},{w:"elly",t:"フォルンの分のオリーブ、ヤマトが全部食べちゃったんだよ。",v:"10_0225"}];
GR_SC.g10_06=[{w:null,t:"せまい路地の宿。"},{w:null,t:"受付のおじいさんが、だまって板を指でさす。"},{w:null,t:"せまい部屋に、ベッドが三つ。"},{w:null,t:"アレクは、机の上にカードを置いて、光る数字を見ている。"},{w:null,t:"エリーが、受付のおじいさんの手首の画面を返して、部屋にもどってくる。"},{w:null,t:"エリーは、窓ぎわで、空になったヤニスのびんのふたを、しめたりあけたりしている。"},{w:null,t:"ヤマトは、ベッドで壁の方を向いて、寝ころんでいる。"},{w:null,t:"窓の外で、雨が降りだす。"},{w:null,t:"通りを、黒い車がゆっくり走っていく。"},{w:null,t:"エリーの手が止まる。"},{w:null,t:"エリー、びんを窓わくに置いて、かさを一本つかんで、部屋を出ていく。"},{w:null,t:"アレク、カードをパーカーの内ポケットにしまう。だまってあとを出ていく。"},{w:null,t:"ヤマトの背中は、動かない。"}];
GR_SC.g10_07=[{w:null,t:"雨の路地。エリーが、かさをさして、軒下を一つずつのぞいていく。"},{w:"elly",t:"フォルン、どこ？　……フォルーン、出ておいで。",v:"10_0246"},{w:null,t:"うしろを、アレクが、かさもささずに歩いている。"},{w:null,t:"人のいない桟橋。"},{w:null,t:"エリー、かさをアレクの方へ半分かたむける。"}];
GR_SC.g10_08=[{w:null,t:"ぬれた二人がもどってくる。"},{w:"alek",t:"ヴィクターの回収の車が、通りを回ってたぞ。",v:"10_0253"},{w:null,t:"ヤマトの背中が、少しだけ固くなる。"},{w:null,t:"明かりが消える。二人の寝息。"},{w:null,t:"ヤマトが、目を開けている。"},{w:null,t:"起き上がって、窓の前に座る。"},{w:null,t:"くもったガラスに、指で線を引く。"},{w:null,t:"指が、桟橋の丸から左のはしの丸へ、何度も行ったり来たりする。"},{w:null,t:"指が止まる。"},{w:null,t:"指が、桟橋の右へ、ゆっくり動く。"},{w:null,t:"昼間、フォルンが一度だけ首を向けた所。"},{w:null,t:"指が、そこから動かない。"},{w:null,t:"ヤマト、手を引っこめる。"},{w:null,t:"そのすき間から、雨の向こうが見える。"},{w:null,t:"ヤマト、ベッドにもどって、掛け物を頭までかぶる。"}];
GR_SC.g10_09=[{w:null,t:"雨の港。港の案内の柱が、だれもいない方に向かってしゃべっている。"},{w:"x",n:"案内の声",t:"お知らせです。港の見張りロボットは、あしたの正午に止めます。",v:"10_0270"},{w:"x",n:"案内の声",t:"歩いたままでは近づけないため、足を切ります。",v:"10_0271"},{w:"x",n:"案内の声",t:"百年間、ありがとうございました。",v:"10_0272"},{w:null,t:"防波堤の上を、大きな影がゆっくり歩いてくる。"},{w:null,t:"左のくるぶしに、太い古い鉄の栓。"},{w:null,t:"大きな足が、上がって、下りる。"},{w:null,t:"雨が、その火をかくす。"},{w:null,t:"ロボットは、止まらずに、雨の中を回っていく。"}];
GR_BT[10]={mid:[[{w:"hero",t:"フォルン、桟橋をまっすぐ行け！",v:"10_0121"},{w:"marina",t:"最初の一発は、打たせてやるよ。",v:"10_0124"},{w:"hero",t:"フォルン、今だ！　ぶちかませ！",v:"10_0125"},{w:null,t:"ヤマトの口のはしが、上がる。"},{w:"marina",t:"ホエルン、さがりな。",v:"10_0129"},{w:"hero",t:"フォルン、前だ！　もっと前へ出ろ！",v:"10_0134"}],[{w:"hero",t:"もどれ！　手前から撃て！",v:"10_0137"},{w:null,t:"ヤマトは、そっちを見ていない。"},{w:"hero",t:"海に出ろ！　杭に跳んで近づけ！",v:"10_0144"},{w:"hero",t:"なんで止まるんだよ！　跳べって言ってるだろ！",v:"10_0147"},{w:"elly",t:"ヤマト、ピリポンも出すよ。電気なら、海の上でも——",v:"10_0151"},{w:null,t:"ヤマト、ふり向かない。"},{w:"hero",t:"いい！　おれとフォルンだけで勝つ！",v:"10_0153"},{w:null,t:"エリーの足が止まる。"},{w:null,t:"アレクの目が、桟橋の左の海へ行く。"},{w:null,t:"アレクが、桟橋の根もとから一歩前へ出る。"}],[{w:"alek",t:"船長。二人目を出しても、いいですか。",v:"10_0160"},{w:null,t:"マリナ、アレクの足もとの、あごの曲がったワニの子を見る。"},{w:"marina",t:"ありだよ。この船の勝負は、二人目まで出していい。",v:"10_0162"},{w:"hero",t:"いらないって！　まだ負けてない！",v:"10_0163"},{w:null,t:"アレク、ヤマトを見ない。"},{w:"alek",t:"クロッコ、一つ前の杭へ行け。",v:"10_0171"},{w:null,t:"マリナの眉が、両方上がる。"},{w:"marina",t:"ホエルン、さがりな！",v:"10_0180"}]],post:[{w:null,t:"クジラ、海の上に、ぷかりと仰向けに浮く。目を回している。"},{w:"marina",t:"……そこまで。",v:"10_0188"},{w:null,t:"桟橋の先で、フォルコンの体が光ってしぼむ。"},{w:null,t:"杭のそばで、クロベクの体も光ってしぼむ。"}]};
GR_EP[10]={"t": "港町ナフリア", "sc": [["g10_01", "ナフリアの港（朝）", 0], ["g10_02", "港の広場", 0], ["g10_03", "向かい合う", 0], ["g10_04", "勝負", 1], ["g10_05", "勝負のあと", 0], ["g10_06", "港の裏の安い宿（夜）", 0], ["g10_07", "港の路地（夜・雨）", 0], ["g10_08", "宿（夜ふけ）", 0], ["g10_09", "港のはし（夜・雨）", 0]]};
GR_SC.g11_01=[{w:null,t:"雨は、夜どおしやまなかった。",v:"11_0019"},{w:null,t:"まだ暗い部屋。"},{w:null,t:"ヤマトが、そっとベッドから起きる。"},{w:null,t:"アレクは、壁を向いて寝ている。"},{w:null,t:"ヤマトがドアに手をかけた時、うしろから、うすい板が一枚飛んでくる。"},{w:null,t:"ヤマト、ふり向く。"},{w:null,t:"ヤマト、カードを拾う。"},{w:null,t:"となりのベッドで、エリーが目を開ける。"},{w:null,t:"第11話　雨上がり",v:"11_0028"}];
GR_SC.g11_02=[{w:null,t:"港の朝市は、雨でも開く。",v:"11_0034"},{w:null,t:"透明な雨よけの屋根の下。"},{w:null,t:"ヤマト、たるを指さす。"},{w:null,t:"魚屋のおばさんが、ヤマトの泥だらけのくつを見る。"},{w:null,t:"ヤマト、袋をポケットに押しこむ。"},{w:null,t:"うしろから、エリーがかさを開いて、ヤマトの頭の上にさしかける。"}];
GR_SC.g11_03=[{w:null,t:"雨の防波堤。"},{w:null,t:"防波堤の根もとに、黒塗りの回収車。"},{w:null,t:"ずしん。ずしん。"},{w:null,t:"エリー、ヤマトに追いついて、見上げる。口が、ぽかんと開く。"},{w:null,t:"大きな足が下りるたび、少しだけ横をずれて下りる。"},{w:null,t:"回収のレンズの光が、防波堤の上をなめていく。"},{w:null,t:"ヤマト、道のまん中で立ち止まる。"},{w:null,t:"フォルンも、止まる。"},{w:null,t:"ロボットは、二人のあいだを、ずしん、と通りすぎていく。"},{w:null,t:"ヤマト、右手を上げかける。"},{w:null,t:"指が、止まる。"},{w:null,t:"ヤマト、手を下ろす。"},{w:null,t:"水たまりに、大きな足あとと、小さな四つ足のあとが、港のはしまで、ずっと並んでいる。"},{w:null,t:"ヤマト、袋からオリーブを一つ出す。"},{w:null,t:"フォルン、オリーブを見る。ヤマトの顔を見る。"},{w:null,t:"ヤマトの手も、動かない。"},{w:null,t:"うしろで、ロボットが一回りして、また近づいてくる。"},{w:null,t:"フォルン、首をのばす。"},{w:null,t:"フォルン、オリーブをしっぽの火の上に落とす。"},{w:null,t:"うしろで、エリーが、かさを二本持ったまま立っている。"},{w:null,t:"ヤマトの顔が、ゆっくりゆるむ。それから、にやっとする。"},{w:"hero",t:"（エリーに）ほらな。腹がへったら、ちゃんと戻ってくるって言っただろ。",v:"11_0063"},{w:"elly",t:"でもヤマト、きのうの夜のごはん、残してたよね。",v:"11_0064"},{w:"hero",t:"残してないって。ちゃんと食べたよ。",v:"11_0065"},{w:"elly",t:"三口、残してた。わたし、見てたもん。",v:"11_0066"},{w:"hero",f:"serious",t:"……三口じゃなくて、二口だよ。",v:"11_0067"},{w:null,t:"エリー、かさを開いて、くるくる回しながら、そっぽを向く。口のはしが、上がっている。"},{w:null,t:"ヤマト、フォルンの頭を、わしわしとなでる。"},{w:null,t:"ヤマトの手が止まった時には、フォルン、二つ目のオリーブを、勝手にヤマトのポケットから出して焼いている。"}];
GR_SC.g11_04=[{w:null,t:"ロボットが、港を一回りして、またこっちへ来る。"},{w:null,t:"防波堤の、古い石の段の前。"},{w:null,t:"ロボット、また歩きだす。"},{w:null,t:"次の一回り。"},{w:null,t:"エリー、段の横の壁に近づく。"},{w:null,t:"絵。海の方を向いて、ひざを折って座りこんだ大きなロボット。"},{w:null,t:"段の上に、さびた油さしが三つ、並んだまま。"},{w:"elly",t:"ヤマト、見て。この絵のロボット、あの子だよ。",v:"11_0080"},{w:"hero",t:"ほんとだ。足の栓まで、同じ形だ。",v:"11_0081"},{w:null,t:"ヤマト、タイルの絵を見る。"},{w:null,t:"空が、低く光る。"},{w:null,t:"エリーの髪の中から、ピリポンが飛び出して、エリーの首にしがみつく。"},{w:"elly",t:"だいじょうぶ、だいじょうぶ。雷さんは、まだ遠いよ。",v:"11_0085"},{w:null,t:"エリー、首のピリポンをなでる。"}];
GR_SC.g11_05=[{w:null,t:"防波堤の根もとに、黄色い解体の機械が集まってくる。"},{w:null,t:"作業員たちが、手首の画面にふれる。"},{w:"x",n:"案内の声",t:"正午から、足の切断を始めます。近づかないでください。",v:"11_0091"},{w:null,t:"かさをさして、マリナが歩いてくる。"},{w:null,t:"アレクも来ている。"},{w:null,t:"アレク、ヤマトの前に、だまって手のひらを出す。"},{w:"marina",t:"子どものころは、毎朝おじいさんたちが、あの段で油をさしてたよ。",v:"11_0095"},{w:"marina",t:"栓を抜くと、あいつ、海の方を向いて座って、待ってたっけね。",v:"11_0096"},{w:"alek",t:"今は、もうだれも油をさしていないんですか。",v:"11_0097"},{w:"marina",t:"おじいさんたちが、いなくなってね。今は、機械の点検は機械がやる。",v:"11_0098"},{w:"marina",t:"あいつは、点検の表に入ってないのさ。",v:"11_0099"},{w:null,t:"黄色い機械の切断の腕が、ためしに一回うなる。"},{w:null,t:"ロボットが、また段の前で止まる。"},{w:null,t:"ヤマトの目が、火花から、タイルの座りこんだロボットへ。それから、くるぶしの栓へ。"},{w:"x",n:"作業員",t:"おい、そこの子ども！　入っちゃだめだ！",v:"11_0104"},{w:"marina",t:"ちょっと、あんた！　どこ行くんだい！",v:"11_0105"}];
GR_SC.g11_06=[{w:null,t:"ロボットは、倒れない。"},{w:null,t:"ゆっくり、歩きだす。"},{w:null,t:"朝市の前を通る。魚屋のおばさんが、手を止めて見上げる。"},{w:null,t:"連絡船の前を通る。"},{w:null,t:"解体の機械の前を通る。"},{w:null,t:"防波堤のいちばん先。"},{w:null,t:"ゆっくり、ひざを折る。"},{w:null,t:"片目の光が、ゆっくり暗くなって、消える。"},{w:null,t:"作業員の手首の画面に、字。"},{w:null,t:"黄色い機械のエンジンが、一台ずつ止まる。"}];
GR_SC.g11_07=[{w:null,t:"ぬれた桟橋が、日の光で光っている。"},{w:null,t:"船を待つ人たち。"},{w:null,t:"いちばんうしろの方に、三人。"},{w:null,t:"桟橋の屋台。"},{w:null,t:"アレク、カードの数字を見る。"},{w:"alek",t:"狐の分が、六ジェムコイン足りない。",v:"11_0138"},{w:"hero",t:"だったら、リュックに入れて乗ればいいじゃん。",v:"11_0139"},{w:null,t:"ヤマト、リュックの口を開ける。"},{w:null,t:"ヤマト、リュックを背負う。"},{w:null,t:"リュックの口から、しっぽの火の先だけ、ぴょこんと出ている。"},{w:"alek",t:"焦げてるって！　背中から、けむりが出てるぞ！",v:"11_0143"},{w:null,t:"ヤマト、あわててリュックを下ろして口を広げる。"},{w:null,t:"そこへ、朝市の魚屋のおばさんが、白い保冷の箱をかかえて歩いてくる。"},{w:null,t:"おばさん、何も言わずに、保冷の箱のふたを少しだけ開ける。"},{w:null,t:"フォルン、リュックから、箱の中へ、するっと入る。"},{w:null,t:"レンズが、三人の足もとをなめる。"},{w:null,t:"レンズが、おばさんの足もとをなめる。"},{w:null,t:"箱のすきまから、うすいけむり。"},{w:null,t:"船の手すりの上から、白い札が一枚、ひらひら落ちてくる。"},{w:null,t:"マリナの白い乗船の札。"},{w:null,t:"ヤマト、上を見る。"},{w:null,t:"船に上がったところで、おばさんが箱のふたを開ける。"},{w:null,t:"おばさん、少し焦げた魚を一切れ見て、肩をすくめる。"}];
GR_SC.g11_08=[{w:null,t:"向こう岸まで、船で半日かかる。",v:"11_0158"},{w:null,t:"連絡船が、港を出ていく。"},{w:null,t:"防波堤のいちばん先に、座ったままのロボット。"},{w:null,t:"足もとの段で、魚屋のおばさんが、さびた油さしを一つ、くるぶしの横に置く。"},{w:null,t:"エリー、手すりから、両手で大きく手をふる。"},{w:null,t:"ヤマト、手すりにひじをついて、胸をそらしている。"},{w:"hero",t:"船なんて楽勝だよ。おれ、ゆれるのに強いから。",v:"11_0164"},{w:"alek",t:"まだ港の中だぞ。ゆれるのは、外に出てからだ。",v:"11_0165"},{w:"hero",t:"港の外でも強いって。見てろよ。",v:"11_0166"},{w:null,t:"船が、防波堤の外へ出る。"},{w:null,t:"ヤマト、ひじをついたまま、だまる。"},{w:null,t:"船が、上がる。"},{w:null,t:"となりの手すりの上で、フォルンが、ヤマトのポケットから持ってきた最後のオリーブを、しっぽの火で焼きはじめる。"},{w:null,t:"ヤマト、においから顔をそむける。"},{w:"elly",t:"ヤマト、ゆれるのに強いんだよね？",v:"11_0174"},{w:"hero",f:"serious",t:"……強いよ。今、ちょっと休んでるだけ。",v:"11_0175"},{w:"elly",t:"あれ、お月さま？　昼なのに、出てるんだね。",v:"11_0180"},{w:"alek",t:"月は、昼も出てる。明るくて、気づかないだけだ。",v:"11_0181"},{w:"elly",t:"ふうん。アレクは、月の何を見てるの？",v:"11_0182"},{w:"alek",t:"山のかげだ。月にも、山があるんだよ。",v:"11_0183"}];
GR_SC.g11_09=[{w:null,t:"向こう岸の船着き場。"},{w:null,t:"ヤマトが、桟橋の上に、大の字になっている。"},{w:"marina",t:"（船の上から、三人の方を見ずに）次は、船代をちゃんと払える日に来な。",v:"11_0192"},{w:"elly",t:"ありがとう、マリナさん！　またね！",v:"11_0193"},{w:null,t:"マリナ、背中を向けたまま、片手だけ上げる。"},{w:null,t:"エリー、船の手すりに走りよって、マリナの手首を指さす。"},{w:null,t:"道の入口に、白い門。"},{w:null,t:"アレクの足が、止まる。小さな字から、目がはなれない。"},{w:"elly",t:"持ち主、Vだって。名前が一文字だけの人なの？",v:"11_0198"},{w:"hero",t:"（大の字のまま）アレク、その字、知ってんの？",v:"11_0199"},{w:"alek",t:"……さあな。Vなんて、どこにでもある字だろ。",v:"11_0200"},{w:null,t:"アレク、それ以上言わない。"},{w:null,t:"うしろで、船が汽笛を鳴らして、岸をはなれていく。"},{w:null,t:"桟橋の上で、ヤマトがまだ大の字のまま、汽笛の方へ首だけ向ける。"}];
GR_EP[11]={"t": "雨上がり", "sc": [["g11_01", "港の裏の宿（夜明け前・雨）", 0], ["g11_02", "朝市（夜明け・雨）", 0], ["g11_03", "防波堤の道（朝・雨）", 0], ["g11_04", "防波堤・古い石の段（朝・雨）", 0], ["g11_05", "防波堤（昼前・雨）", 0], ["g11_06", "港（正午・雨がやんでいく）", 0], ["g11_07", "連絡船の桟橋（昼）", 0], ["g11_08", "連絡船の上（午後）", 0], ["g11_09", "向こう岸（夕方）", 0]]};
GR_SC.g12_01=[{w:null,t:"獅子門の丘の見学の門。"},{w:null,t:"明るい部屋。"},{w:null,t:"壁の画面に、止めた映像。森の施設の中で、古い扉の写真を指でなぞるエリーの横顔。"},{w:null,t:"となりの小さな窓に、文字が流れている。「検索中：宿・船・見学の名簿　顔の照合」。"},{w:null,t:"指にオレンジの輪の指輪。その指が、「該当なし」を、とん、とたたく。"},{w:null,t:"画面のすみで、ぽん。"},{w:null,t:"指輪の手が、ケーキにフォークを入れる。"},{w:null,t:"白いスーツの腕が、いすの背の上着を取って、はおる。"},{w:null,t:"第12話　獅子門の丘",v:"12_0028"}];
GR_SC.g12_02=[{w:null,t:"獅子門の丘。三千年前の王の城あとだ。",v:"12_0034"},{w:null,t:"今は、ある大金持ちの持ち物になっている。",v:"12_0035"},{w:null,t:"船着き場の、屋根だけの待合。"},{w:null,t:"フォルンは、シートのはしで、ヤマトの足の上に丸くなっている。しっぽの火は、シートの下。"},{w:"hero",t:"足がしびれて動かないんだけど。フォルン、ずっと乗ってたのかよ。",v:"12_0038"},{w:"elly",t:"フォルン、ヤマトの足があったかいから、そこがいいんだって。",v:"12_0039"},{w:null,t:"アレク、シートをたたむ。"},{w:null,t:"船着き場からの道は、丘を上がって、新しい白い門で行き止まり。"},{w:null,t:"アレク、その一文字を、もう一度見上げる。"},{w:"alek",t:"ヤマト、手首の地図を出してくれ。場所を知らせるのは、切ったままでな。",v:"12_0043"},{w:"hero",t:"分かってるって。アレク、毎回それ言うじゃん。",v:"12_0044"},{w:null,t:"ヤマトの左の手首から、光の地図が宙に広がる。"},{w:null,t:"アレク、丘のところを指でなぞる。"},{w:"alek",t:"北へ抜ける道は、あの門の中を通る一本だけだ。",v:"12_0047"},{w:"hero",t:"いいじゃん。見学ご自由に、だってさ。ただだし、名簿もとらないって。",v:"12_0048"},{w:"alek",t:"その「ただ」っていうのが、気にいらないんだよ。",v:"12_0049"},{w:"hero",t:"なんで？　ただなら、いいことじゃん。",v:"12_0050"},{w:"alek",t:"ただで入れるのは、向こうに何かほしい物があるからだ。",v:"12_0051"},{w:"hero",t:"ほしいのは、お客さんに見学してもらうことだろ。",v:"12_0052"},{w:null,t:"ヤマト、もう門をくぐっている。"},{w:null,t:"エリー、看板に、ぺこりと頭を下げてから、くぐる。"},{w:null,t:"アレク、門の柱を見上げる。"},{w:null,t:"アレク、クロッコの背中を軽くたたく。"}];
GR_SC.g12_03=[{w:null,t:"見学の客が、二十人ほど。"},{w:"x",n:"案内のロボット",t:"ようこそ、獅子門の丘へ！",v:"12_0060"},{w:"x",n:"案内のロボット",t:"本日のお客さまは、二十一名さまと、テリオン三体さまです！",v:"12_0061"},{w:null,t:"客の中に、小さな丸い耳の子を抱いた女の子。"},{w:null,t:"ロボットの顔の光が、客の足もとを一つずつなめていく。"},{w:null,t:"フォルンで、ぴっ。"},{w:"x",n:"案内のロボット",t:"お知らせでーす！",v:"12_0065"},{w:"x",n:"案内のロボット",t:"登録の確認できない狐さまを、お連れのお客さまがいらっしゃいまーす！",v:"12_0066"},{w:"x",n:"案内のロボット",t:"あとで受付まで、おこしくださーい！",v:"12_0067"},{w:null,t:"客が、いっせいにふり向く。"},{w:null,t:"ヤマト、とっさにフォルンをだき上げて、パーカーのおなかに押しこむ。"},{w:null,t:"パーカーのおなかが、もこもこ動く。首の所から、しっぽの火が、ぽっと出る。"},{w:null,t:"客たちが、手首の画面をかざして写真をとる。"},{w:null,t:"ヤマト、客に小さく会釈する。"},{w:"alek",t:"（小声で）けむりが出てるって！　かくせてないぞ！",v:"12_0073"},{w:null,t:"エリーは、ロボットの旗に、両手で手をふっている。"},{w:null,t:"坂の途中。ロボットが立ち止まって、旗で丘のてっぺんをさす。"},{w:"x",n:"案内のロボット",t:"昔、この町を作った英雄は、見た者を石にする、おそろしい怪物をたおしました！",v:"12_0076"},{w:"x",n:"案内のロボット",t:"怪物の目を見ないように、ぴかぴかにみがいた盾に映して、近づいたのです！",v:"12_0077"},{w:null,t:"女の子が、腕の丸い耳の子の目を、手でかくす。"},{w:"x",n:"案内のロボット",t:"たおした怪物の顔は、知恵の女神の盾に、かざられました！",v:"12_0079"},{w:"x",n:"案内のロボット",t:"その盾の名前は——アイギス！",v:"12_0080"},{w:null,t:"ロボットが、旗をくるっと回す。客たちが、ぱらぱらと手をたたく。"},{w:"hero",t:"盾に映して近づくって、それ、ちょっとずるくない？",v:"12_0082"},{w:"alek",t:"ずるくないだろ。目を見たら、石になるんだぞ。",v:"12_0083"},{w:"hero",t:"じゃあ、おれもそういう盾がほしい。いちいち逃げなくてすむし。",v:"12_0084"},{w:"alek",t:"お前は、まず、けむりをかくせよ。",v:"12_0085"},{w:null,t:"ヤマトのパーカーの首から、まだ、けむりが一本のぼっている。"}];
GR_SC.g12_04=[{w:null,t:"大きな石の門。"},{w:"x",n:"帽子のおじいさん",t:"（となりのアレクに）この獅子、頭はどうしたんだろうね。",v:"12_0091"},{w:"alek",t:"頭だけ、別の石で作って、はめてあったそうです。",v:"12_0092"},{w:"alek",t:"だれかが持っていったと聞きました。",v:"12_0093"},{w:"x",n:"帽子のおじいさん",t:"へえ、よく知ってるね。ありがとう、物知りなお兄さん。",v:"12_0094"},{w:null,t:"アレク、小さく頭を下げる。"},{w:null,t:"ヤマト、門の下で、獅子の渦巻く毛を見上げている。口が、ぽかんと開いている。"},{w:null,t:"エリー、門のわきの石の古い文字に、顔を近づける。"},{w:"elly",t:"ここ、「門をくぐる者は、獅子の前で手を洗え」って書いてあるよ。",v:"12_0098"},{w:null,t:"エリー、自分の手のひらを見る。"},{w:null,t:"客のうしろから、ぱちぱちぱち、と小さな拍手。"},{w:"victor",t:"すごいね。今の、古いギリシャ語だよね？",v:"12_0101"},{w:"victor",t:"声に出して読める子は、ぼくも初めて見たよ。",v:"12_0102"},{w:null,t:"白いスーツの、若い男。"},{w:null,t:"見回りの二人の胸に、小さなオレンジの、角の丸い四角の輪。"},{w:null,t:"アレクの肩が、ぴくりと固くなる。目が、指輪と胸の輪から動かない。"},{w:"victor",t:"はじめまして。ぼくは、ヴィクター。",v:"12_0106"},{w:null,t:"アレクの顔から、色が消える。"},{w:"elly",t:"え、ヴィクター？　あの悪い一味と同じ名前だね！",v:"12_0108"},{w:"elly",t:"すごい偶然！　でも、こっちはいい人そう。",v:"12_0109"},{w:"victor",t:"（笑ったまま）よく言われるよ。迷惑な話でね。",v:"12_0110"},{w:"victor",t:"この丘は、ぼくの庭みたいなものなんだ。",v:"12_0111"},{w:"elly",t:"ここ、全部お庭なの？　すごい！",v:"12_0112"},{w:"victor",t:"すごいのは、きみの方だよ。",v:"12_0113"},{w:"victor",t:"うちの学者でも、あんなにすらすらは読めない。",v:"12_0114"},{w:"elly",t:"ほんと？　今まで、おばあちゃんにしか、ほめられたことないよ。",v:"12_0115"},{w:"victor",t:"じゃあ、ぼくが二人目だ。きみ、才能あるね。名前は？",v:"12_0116"},{w:"elly",t:"エリー！　オリーヴァ村から来たの。",v:"12_0117"},{w:"elly",t:"おばあちゃん、昔、研究所にいたんだよ。",v:"12_0118"},{w:null,t:"アレクの指が、エリーのそでをつまむ。"},{w:"victor",t:"お茶でもどう？　ケーキがある。その子たちの分もね。",v:"12_0120"},{w:"elly",t:"ケーキ！　行く行く！",v:"12_0121"},{w:"alek",t:"せっかくですが、ぼくたちは先を急いでいるので。",v:"12_0122"},{w:"victor",t:"心配いらないよ。今日は、見に来ただけだから。",v:"12_0123"},{w:null,t:"ヴィクター、アレクの足もとのクロッコに目を落とす。"},{w:"victor",t:"元気そうだね、きみ。そのワニも。",v:"12_0125"},{w:null,t:"アレクの頭の中に、4話の森の夜。顔の出ない手首の画面から、低い声。"},{w:null,t:"同じ声。アレク、息が止まる。"},{w:"alek",t:"……おかげさまで。",v:"12_0128"},{w:null,t:"ヴィクター、うしろの見回りの二人を、ふり返りもせずに、手のひらで止める。"},{w:null,t:"エリー、アレクの指から、そでをするりと抜く。"},{w:null,t:"フォルンが、さっさとエリーのあとをついていく。"},{w:"hero",t:"（小声で）アレク、行っちゃっていいの？　さっき、急いでるって言ってたじゃん。",v:"12_0132"},{w:"alek",t:"（小声で）見回りの二人の胸を、見てみろ。",v:"12_0133"},{w:null,t:"ヤマトの目が、見回りの胸の、オレンジの輪に行く。"},{w:"hero",t:"（小声で）名前もマークも、ヴィクターじゃん。走って逃げようよ。",v:"12_0135"},{w:"alek",t:"（小声で）ここは、あの人の庭の中だ。走っても、門の外までは行けない。",v:"12_0136"},{w:"alek",t:"（小声で）向こうが「見に来ただけ」って言ってるうちは、ついていく方が安全だ。",v:"12_0137"},{w:null,t:"二人、だまって歩きだす。"}];
GR_SC.g12_05=[{w:null,t:"丘のてっぺんの、白い館。三千年前の城あとを、見下ろす部屋だ。",v:"12_0144"},{w:null,t:"背の低い、白い石とガラスの館。"},{w:null,t:"配膳のロボットが、白い机に、ケーキを並べていく。"},{w:null,t:"エリーは、ヴィクターのとなりで足をぶらぶらさせている。"},{w:null,t:"ヤマトは、いすのはしに浅く座っている。"},{w:null,t:"アレクは、座らない。"},{w:null,t:"ヴィクターが、指輪の指を一つ鳴らす。"},{w:"x",n:"画面のヴィクター",t:"——古代の力を、チップで。",v:"12_0151"},{w:null,t:"ヤマトの手のフォークが、皿に当たって、かちんと鳴る。"},{w:null,t:"アレクは、窓ガラスに映った画面の字を見ている。"},{w:null,t:"ヴィクターは、画面ではなく、三人の顔を見ている。"},{w:null,t:"ヴィクター、もう一度、指を鳴らす。"},{w:"victor",t:"さあ、遠慮しないで。どんどん食べて。",v:"12_0156"},{w:null,t:"ヤマト、ケーキを見る。"},{w:null,t:"フォークで、いちごのケーキをひと口。"},{w:null,t:"ヤマトの皿が、空になる。"},{w:null,t:"アレクが、ふり返る。ヤマト、皿から手をはなす。"},{w:null,t:"テリオン用の皿。"},{w:null,t:"ヤマト、黒いケーキを見る。"},{w:"hero",f:"serious",t:"……これ、焦げてても、けっこううまい。",v:"12_0163"},{w:null,t:"ピリポンは、エリーのひざに下りて、チョコのケーキに顔をつっこんでいる。"},{w:null,t:"ヴィクター、ヤマトの足もとのフォルンを見る。"},{w:"victor",t:"その狐、登録がないんだってね。",v:"12_0166"},{w:"victor",t:"ぼくの施設なら、今日にでも登録できるよ。",v:"12_0167"},{w:"victor",t:"耳のうしろに、チップを一つ入れるだけ。痛くはない。",v:"12_0168"},{w:"hero",t:"いいです。登録は、自分でなんとかするから。",v:"12_0172"},{w:"victor",t:"そう。じゃあ、十五歳になるまで、待つのかな？",v:"12_0173"},{w:"victor",t:"エリーちゃん。おばあさまは、研究者だったんだよね。",v:"12_0176"},{w:"victor",t:"何か、おばあさまから預かってないかな。大事な物。",v:"12_0177"},{w:"elly",t:"大事な物？　うーん、なんだろう……",v:"12_0179"},{w:"elly",t:"ねえ、あの獅子の頭、どこ行ったんだろうね。",v:"12_0182"},{w:"elly",t:"しっぽは、ちゃんと残ってるのに。",v:"12_0183"},{w:"elly",t:"ほら、しっぽの先、くるんってなってるよ。かわいくない？",v:"12_0184"},{w:"victor",t:"……その話は、また今度、ゆっくりしよう。",v:"12_0187"},{w:"victor",t:"困ったことがあったら、いつでも呼んでいいよ。",v:"12_0189"},{w:"elly",t:"これ、名刺だ！　わたし、初めてもらった！",v:"12_0190"}];
GR_SC.g12_06=[{w:null,t:"館の裏の、北へ下りる石の道。"},{w:"x",n:"見回りの男",t:"どうぞ。お通ししろと言われています。",v:"12_0196"},{w:null,t:"三人、門を出る。"},{w:null,t:"坂を少し下りた所で、アレクがふり返る。"},{w:"elly",t:"ヴィクターさん、いい人だったね。名前はこわいけど。",v:"12_0199"},{w:"elly",t:"ケーキも、すっごくおいしかったし。",v:"12_0200"},{w:null,t:"坂の下に、小さな店が一軒。"},{w:"elly",t:"あ、お店だ。おばあちゃんに、名刺もらったって言わなきゃ。",v:"12_0202"},{w:"alek",t:"電話するなら、短くしろよ。今どこにいるかは、言うなよ。",v:"12_0203"},{w:"elly",t:"分かってるって！　すぐ、もどってくるから。",v:"12_0204"},{w:null,t:"エリー、店へ走っていく。"},{w:null,t:"坂の途中に、ヤマトとアレク。"},{w:"hero",t:"アレク。あの人、名前もヴィクターだったよな。",v:"12_0207"},{w:"alek",t:"ああ。もらったカードの裏にも、あの輪がついてた。",v:"12_0208"},{w:null,t:"アレク、ポケットの上から、カードを指で一回はじく。"},{w:"alek",t:"それに、あの声。おれに電話で命令してたボスだ。",v:"12_0210"},{w:"hero",t:"ボスって、森でアレクにおれたちを捕まえさせた人？",v:"12_0211"},{w:"alek",t:"そうだよ。ヴィクターっていうのは、あの人の名前なんだ。",v:"12_0212"},{w:"hero",t:"看板のVも……。ボス本人が、ケーキ出してたのかよ。",v:"12_0213"},{w:"alek",t:"声は、ずっと聞いてた。顔を見たのは、今日が初めてだ。",v:"12_0214"},{w:"hero",t:"画面で「古代の力を、チップで」って言ってたよな。",v:"12_0215"},{w:"alek",t:"化石の子にチップを入れて、言うことを聞かせる気なんだろうな。",v:"12_0216"},{w:"hero",f:"serious",t:"……エリーには、言わなくていいの？",v:"12_0217"},{w:"alek",t:"言ったら、顔に出る。あの人は、それを見てるんだ。",v:"12_0218"},{w:null,t:"ヤマト、自分の手を見る。"},{w:null,t:"エリーが、走ってもどってくる。口のまわりに、まだチョコ。"},{w:"elly",t:"おばあちゃん、出なかった。だから、伝言にしといたよ。",v:"12_0221"},{w:"hero",t:"エリー、口のまわり、チョコついてるぞ。",v:"12_0222"},{w:null,t:"エリー、口のまわりのチョコを、手のひらでぬぐって、なめる。"}];
GR_SC.g12_07=[{w:null,t:"丘の西の道。"},{w:null,t:"ヴィクターがうしろの席に乗る。"},{w:null,t:"となりの席。"},{w:"x",n:"影の男",t:"ヴィクター。鍵は。",v:"12_0229"},{w:"victor",t:"かわいい子でした。字は、うちのどの学者より読めます。",v:"12_0230"},{w:"victor",t:"おばあさまの物は、まだです。",v:"12_0231"},{w:"victor",t:"でも、勝ち方は、もう分かってます。",v:"12_0232"},{w:"victor",t:"ほめておけば、あの子の方から来ますよ。",v:"12_0233"},{w:null,t:"ヴィクター、見回りへの指示を打つ。"},{w:null,t:"黒い手袋の手が、横からのびて、画面の上に、ふたをするようにのる。"},{w:null,t:"指輪の指が、止まる。"},{w:null,t:"手袋の指が、写真の女の子の顔を、一回だけ、とんとたたく。"},{w:"x",n:"影の男",t:"その子も、いっしょに連れてきなさい。",v:"12_0238"},{w:"victor",t:"……はい。そうします。",v:"12_0241"}];
GR_SC.g12_08=[{w:null,t:"乾いた道が、北へ長くのびている。"},{w:null,t:"三人と三体が歩いている。"},{w:"hero",t:"なあ、あの山をこえたら、白い都なの？",v:"12_0248"},{w:"alek",t:"あの山をこえて、それから、もう少し先だ。",v:"12_0249"},{w:"hero",t:"でもあれ、上の方、雪じゃん。",v:"12_0250"},{w:"alek",t:"雪だよ。だから、早く行かないと道が消える。",v:"12_0251"},{w:"hero",t:"平気だって。おれ、雪には強いから。",v:"12_0252"},{w:"alek",t:"お前、船にも強いって言ってたよな。",v:"12_0253"},{w:null,t:"ヤマト、だまる。"},{w:null,t:"エリー、二人のうしろを、くるくる回りながら歩いている。"},{w:null,t:"フォルンが、ふり返って、丘の上をしばらく見る。"},{w:null,t:"フォルン、前を向く。"}];
GR_SC.g12_09=[{w:null,t:"村はずれの小さな石の家。"},{w:null,t:"壁の画面に、光る字。"},{w:null,t:"伝言が流れはじめる。画面に、少しゆれたエリーの顔。"},{w:"x",n:"エリーの声（伝言）",t:"おばあちゃん！　エリーだよ。これ、お店の人の画面を借りてかけてるの。",v:"12_0263"},{w:"x",n:"エリーの声（伝言）",t:"きょうね、すっごく親切なお金持ちの人に、ケーキをもらったの。",v:"12_0264"},{w:"x",n:"エリーの声（伝言）",t:"ヴィクターさんっていうの。あの一味と同じ名前！",v:"12_0265"},{w:"x",n:"エリーの声（伝言）",t:"でも、ぜんぜん別の、いい人だったよ。",v:"12_0266"},{w:"x",n:"エリーの声（伝言）",t:"おばあちゃんのこと、聞かれた。",v:"12_0267"},{w:"x",n:"エリーの声（伝言）",t:"また電話するね！　お姉ちゃんにも、よろしくね！",v:"12_0268"},{w:null,t:"しわの少ない手が、画面にふれて、伝言を止める。"},{w:null,t:"手が、棚の写真の板にのびる。"},{w:null,t:"手が、写真の上で止まる。"}];
GR_EP[12]={"t": "獅子門の丘", "sc": [["g12_01", "獅子門の丘・見学の門〜どこかの部屋（朝）", 0], ["g12_02", "船着き場〜見学の門（朝）", 0], ["g12_03", "城あとの坂道（朝）", 0], ["g12_04", "獅子の門（昼前）", 0], ["g12_05", "丘の上・ヴィクターの館の応接間（昼）", 0], ["g12_06", "丘の北の出口〜坂の下（昼すぎ）", 0], ["g12_07", "丘の反対側の道（昼すぎ）", 0], ["g12_08", "北への道（夕方）", 0], ["g12_09", "オリーヴァ村・おばあさんの家（夜）", 0]]};
GR_SC.g13_01=[{w:null,t:"白い都へ行くには、この山を越えるのが一番の近道だ。冬でなければ。",v:"13_0023"},{w:null,t:"横なぐりの雪。"},{w:null,t:"雷が光るたびに、石塚の上に影が浮かぶ。"},{w:null,t:"下の谷から、赤い光を点滅させて、救助のドローンがのぼってくる。"},{w:"x",n:"救助のAIの声",t:"救助に向かいます。到着まで、あと四分です。",v:"13_0027"},{w:null,t:"影が、石塚の上で槌をふり上げる。"},{w:null,t:"太い雷が、空を横切って、遠いドローンのすぐ横の岩に落ちる。"},{w:"x",n:"救助のAIの声",t:"落雷のため、引き返します。再開は、天気が回復してからです。",v:"13_0030"},{w:null,t:"峠の下。雪の斜面に、小さな石の小屋。"},{w:null,t:"第13話　雲の山道",v:"13_0033"}];
GR_SC.g13_02=[{w:null,t:"その日の昼。まだ、晴れていた。",v:"13_0039"},{w:null,t:"晴れた山道。"},{w:null,t:"先頭はアレク。"},{w:null,t:"フォルンは、ヤマトの横を歩いている。エリーの肩で、ピリポンが首をすくめている。"},{w:"elly",t:"ねえアレク、白い都まで、あとどのくらい？",v:"13_0043"},{w:"alek",t:"この山を越えて、運河の町を抜けて、谷を一つだ。大会には、ぎりぎり間に合う。",v:"13_0044"},{w:"hero",t:"ぎりぎりって、どのくらいだよ。",v:"13_0045"},{w:"alek",t:"一日でも足止めされたら、もう間に合わない。",v:"13_0046"},{w:null,t:"ヤマト、道ばたの雪に気づく。"},{w:"hero",t:"雪だ！　東京じゃ、画面でしか見たことないんだよ！",v:"13_0048"},{w:null,t:"アレク、ふり返らずに、いただきを指さす。"},{w:"alek",t:"あの雲が下りてきたら、止まれよ。まわりがまっ白になって、道が消えるんだ。",v:"13_0050"},{w:"hero",t:"はーい。",v:"13_0051"},{w:null,t:"ヤマト、もう聞いていない。"},{w:"alek",t:"おい、どこ行く気だ！",v:"13_0053"},{w:"hero",t:"一回だけ！　すぐもどるって！",v:"13_0054"},{w:null,t:"ヤマト、雪をける。"},{w:"hero",f:"surprised",t:"うおおおお！　はええ！",v:"13_0056"},{w:null,t:"赤い上着が、白い斜面の下へみるみる小さくなる。"},{w:"hero",f:"surprised",t:"見たー！？",v:"13_0058"},{w:null,t:"アレク、だまって、下りてくる雲を指さす。それから、自分の足もとの道を指さす。"},{w:null,t:"ヤマト、斜面を見上げる。"},{w:null,t:"のぼりはじめる。"},{w:null,t:"フォルンが、上から一直線に駆け下りてきて、ヤマトのリュックの上に、ぴょんと乗る。"},{w:"hero",f:"serious",t:"……重いって。おりろよ。",v:"13_0063"},{w:null,t:"フォルン、座ったまま、あくび。"},{w:null,t:"やっと道にもどったヤマトの目が、道のすぐ横の、さっきよりもっと長い斜面へ行く。"},{w:"alek",t:"のぼるのに、どれだけかかったと思ってるんだ！　前を見て歩けよ！",v:"13_0067"}];
GR_SC.g13_03=[{w:null,t:"まっ白。風が、横から雪を吹きつける。"},{w:null,t:"ヤマトの手首の光の地図が、雪の中でにじんでいる。"},{w:"alek",t:"ヤマト、地図は消せ。まっ白で、見ても、どっちが道か分からない。",v:"13_0073"},{w:null,t:"ヤマト、手首にふれる。"},{w:"alek",t:"ヤマトはおれの上着、エリーはヤマトの上着をつかめ。絶対にはなすなよ。",v:"13_0075"},{w:null,t:"ヤマトがアレクのパーカーのすそをつかむ。"},{w:"elly",t:"アレク、小屋の場所、分かるの？",v:"13_0077"},{w:"alek",t:"さっきの大きな岩から、百二十歩だ。案内の仕事で、何回も数えて歩いた。",v:"13_0078"},{w:null,t:"アレク、歩きだす。口の中で、数を数えている。"},{w:"alek",t:"……百十九。",v:"13_0080"},{w:null,t:"アレクの手のひらが、冷たい石の壁にさわる。"}];
GR_SC.g13_04=[{w:null,t:"石を積んだ低い小屋。"},{w:null,t:"小屋の手前の雪の上に、赤い登山服の男が、うつぶせに倒れている。"},{w:null,t:"雪の上に、戸口から男の方へ、子どもの足あとが何本も。"},{w:"elly",t:"人が倒れてる！",v:"13_0087"},{w:null,t:"戸が開く。銀色の救助シートをかかえて、少年が出てくる。"},{w:null,t:"レン、ヤマトを見る。"},{w:"hero",f:"serious",t:"……レン？",v:"13_0090"},{w:null,t:"レンの足もとで、黄色と黒のトラの子が、戸口の内側に立っている。"},{w:null,t:"レンの手首の画面に、字。"},{w:null,t:"レン、画面を指でおす。"},{w:null,t:"エリー、通報の板の赤いボタンをおす。"},{w:"elly",t:"救助、お願いします！　人が倒れてて、動かないんです！",v:"13_0095"},{w:"x",n:"救助のAIの声",t:"ただいま、たいへん混み合っております。順番に、おうかがいします。",v:"13_0096"},{w:null,t:"フォルンが、ヤマトの胸から飛び下りる。"},{w:null,t:"ヤマト、男の腕を肩にかけようとする。"},{w:null,t:"反対側に、レンがしゃがむ。"},{w:null,t:"二人、目を合わせない。"},{w:null,t:"戸口の内側で、ライガが、運ばれてくる男を見上げている。"}];
GR_SC.g13_05=[{w:null,t:"壁にうめこまれた暖房の板が、だいだい色に光っている。"},{w:"x",n:"登山服のAIの声",t:"体温が、もどりつつあります。左足の指の温度が、まだ低いままです。",v:"13_0105"},{w:null,t:"男、子ども四人と、小さなテリオン四体を見る。目が、暖房の板のそばのレンで止まる。"},{w:"x",n:"登山家",t:"坊主は、一人で来たのか。",v:"13_0107"},{w:null,t:"レン、答えない。"},{w:null,t:"窓の外が、まっ白に光る。"},{w:"x",n:"登山家",t:"……峠の主だ。冬になると下りてくる。空を飛ぶ物が大きらいでな。あいつがいる間は、ドローンは来られない。",v:"13_0110"},{w:null,t:"かち、かち、かち。暗い中で、レンが手のひらの小さな光る板を、何度もにぎっている。"},{w:null,t:"エリー、男の手首の画面を見る。"},{w:"elly",t:"あの、手首の画面を、少しだけ貸してもらえませんか。お姉ちゃんに、毎晩電話するって約束してるんです。",v:"13_0113"},{w:"x",n:"登山家",t:"貸してやりたいが、さっきの雷から、ずっと「圏外」だ。",v:"13_0114"},{w:null,t:"男、手首を見せる。"},{w:"elly",f:"serious",t:"……そっか。お姉ちゃん、また怒るだろうな。",v:"13_0116"},{w:null,t:"エリー、うとうとして、こてんとヤマトの肩に寄りかかって寝る。"},{w:null,t:"フォルンが、男のひざの前で丸くなる。しっぽの火が、ぽうっと明るい。"},{w:null,t:"男、シートから手を出して、火にかざす。"},{w:"x",n:"登山家",t:"火ってのは、昔は、神さまの物だったんだってさ。それを、こっそり人に渡した神さまがいたんだ。その神さまは怒られて、山にしばられたんだと。ちょうど、こういう山に。",v:"13_0120"},{w:"hero",t:"しばられて、そのあと、どうなったの。",v:"13_0121"},{w:"x",n:"登山家",t:"さあな。毎日、鳥につつかれてたらしい。",v:"13_0122"},{w:"hero",f:"serious",t:"……ひでえ。火をくれたのに。",v:"13_0123"}];
GR_SC.g13_06=[{w:null,t:"朝なのに、窓の外はまっ白。"},{w:null,t:"エリーが、袖をまくって、暖房の板の前に非常食のパックを並べている。"},{w:"elly",t:"ヤマト、パックのひもを引いて温めて。レンくん、お湯をお願い。アレク、非常食の袋、どこにあるの？",v:"13_0129"},{w:"alek",t:"棚の、いちばん上だ。",v:"13_0130"},{w:"elly",t:"とどかない。",v:"13_0131"},{w:null,t:"アレク、取ってわたす。"},{w:null,t:"エリー、パックをあけて、スプーンを配る。"},{w:null,t:"エリーの前には、何もない。"},{w:null,t:"ヤマト、自分のパックを見る。"},{w:null,t:"エリー、パックを見る。"},{w:null,t:"エリー、非常袋の安全ピンを出して、レンのジャージの裂けた袖を、三つとめる。"},{w:"x",n:"登山服のAIの声",t:"左足の指の温度が、さらに下がっています。",v:"13_0138"},{w:"hero",t:"峠のやつを、どかせばいいんだろ。おれとフォルンで行ってくる。",v:"13_0142"},{w:"alek",t:"この雪じゃ、相手がどこにいるかも見えないだろ！　出たとたんに、雷で打たれるぞ。",v:"13_0143"},{w:"hero",t:"じゃあ、いつならいいんだよ。",v:"13_0144"},{w:"alek",t:"雪がやんで、あいつが見えるようになってからだ。それまでは、ここで待て。",v:"13_0145"}];
GR_SC.g13_07=[{w:null,t:"風の音が、ふっと止まる。"},{w:null,t:"外。小屋の上に、雪の積もった岩の斜面。"},{w:null,t:"谷の下から、赤い光の救助のドローンがのぼってくる。"},{w:"x",n:"救助のAIの声",t:"天気が回復しました。救助に向かいます。",v:"13_0154"},{w:null,t:"石塚の上に、雲の毛の獣が立ち上がる。"},{w:null,t:"ドローンが、ふらつきながら小屋の方へ逃げてくる。"},{w:null,t:"獣が、石塚をけって追ってくる。"},{w:null,t:"ドローンは、もう谷へ消えている。"},{w:null,t:"獣は、うしろの石塚を、ちらっとふり返る。"},{w:null,t:"ヤマトが、戸口から、それを見ている。"},{w:null,t:"小屋の横の、雪にうもれかけた案内の柱が、ぴっと鳴る。"},{w:"x",n:"登山道の柱の声",t:"野生のテリオン、トールジンです。近くの方は、建物の中へ入ってください。",v:"13_0162"},{w:null,t:"獣が石塚の上にもどる。"},{w:"hero",t:"あいつがいるかぎり、ドローンは来られないんだろ。……アレク、雪、やんだぞ。",v:"13_0164"},{w:"alek",t:"……分かってる。エリー、行けるか。",v:"13_0165"},{w:"elly",t:"うん。おじさんの足、もう待てないもん。",v:"13_0166"}];
GR_SC.g13_08=[{w:null,t:"雪の斜面。手前は、小屋の前の平らな雪原。"},{w:null,t:"ヤマト、戸口の前でフォルンを下ろす。"},{w:null,t:"エリーの髪の中から、ピリポンが雪の上に下りる。"},{w:null,t:"アレクのクロッコ。"},{w:null,t:"ヤマトは、小屋の戸口の前に立つ。"},{w:null,t:"石塚の上で、トールジンの体が光る。"},{w:null,t:"冠のいなずまが、ばちばち鳴る。"}];
GR_SC.g13_10=[{w:null,t:"フォルレオンの体が、ふわっと光る。"},{w:null,t:"ヤマト、戸口から走り出る。"},{w:null,t:"フォルン、ヤマトを見上げる。それから、ヤマトの手の上に、自分であごをのせる。"},{w:null,t:"雪原の向こうで、トールガが起き上がる。"},{w:null,t:"トールジン、背を向ける。"},{w:"x",n:"登山服のAIの声",t:"天気が回復しました。夜の山の飛行は、決まりで行っていません。救助は、あしたの朝、七時に到着します。",v:"13_0235"},{w:"x",n:"登山家",t:"……七時か。坊主たち、もう一晩、たのむよ。",v:"13_0236"}];
GR_SC.g13_11=[{w:null,t:"暖房の板が、電池で弱く光っている。"},{w:null,t:"レンのとなりで、ライガが丸くなっている。"},{w:null,t:"ヤマトのひざで、フォルンが寝ている。"},{w:null,t:"レンの目が、フォルンへ行く。"},{w:"hero",t:"……なんだよ。さっきから、フォルンばっかり見て。",v:"13_0243"},{w:"dimi",t:"別に。さがれって言われて、さがらない子は、初めて見ただけだ。",v:"13_0244"},{w:null,t:"レン、暖房の板のつまみを、一つ上げる。"},{w:"hero",t:"レンも、白い都の大会に出るのか？",v:"13_0246"},{w:"dimi",t:"出る。そのために、一人でここまで来た。",v:"13_0247"},{w:"hero",f:"serious",t:"……おれも出る。",v:"13_0248"},{w:"dimi",t:"その狐、持ち主の登録がないだろ。どうやって出るんだよ。",v:"13_0249"},{w:"hero",t:"だから出るんだよ。優勝したら、登録できるんだから。",v:"13_0250"},{w:null,t:"レン、何か言いかけて、やめる。"}];
GR_SC.g13_12=[{w:null,t:"戸が、そっと開く。"},{w:null,t:"レン、雪の道を峠の方へ歩いていく。"},{w:null,t:"小屋の壁の板。"}];
GR_SC.g13_13=[{w:null,t:"七時。谷の下から、救助のドローンがのぼってきて、小屋の前に下りる。"},{w:"x",n:"救助のAIの声",t:"お待たせしました。ご利用、ありがとうございました。",v:"13_0260"},{w:null,t:"男が、担架に乗せられる。"},{w:"x",n:"登山家",t:"お姉さんに電話するんだろ。今なら、つながるぞ。",v:"13_0262"},{w:"elly",t:"ありがとうございます！　すぐ、お返しします。",v:"13_0263"},{w:null,t:"アレク、エリーのそばに来て、小声で言う。"},{w:"alek",t:"短くしろよ。それと、場所は言うなよ。",v:"13_0265"},{w:null,t:"空中の小さな画面に、アナの顔。"},{w:"ana",t:"エリー！　三晩もかけてこないで、何してたの！",v:"13_0267"},{w:"elly",f:"sad",t:"ごめんね。雪で、ずっと小屋から出られなかったの。もう、晴れたから大丈夫。",v:"13_0268"},{w:"ana",t:"小屋って、どこの……。",v:"13_0269"},{w:"elly",f:"surprised",t:"えっと、それは、言っちゃだめなの。今夜は、ちゃんとかけるね。",v:"13_0270"},{w:null,t:"エリー、画面を切って、男に両手で返す。男、笑ってうなずく。"},{w:null,t:"男、ヤマトの足もとのフォルンを見る。シートから指を一本出して、しっぽの火に、ちょんとつける。"},{w:null,t:"担架がドローンに収まって、谷へ下りていく。"},{w:null,t:"エリー、壁の板の「決勝」を、指でなぞっている。"},{w:"elly",t:"これ、レンくんの字かな？",v:"13_0275"},{w:"hero",f:"serious",t:"……さあな。知らない。",v:"13_0276"},{w:null,t:"ヤマト、リュックをしょって、先に戸口を出る。"},{w:"alek",t:"一日、足止めされた。ここからは急ぐぞ。",v:"13_0278"},{w:"elly",t:"でも、間に合うよね？",v:"13_0279"},{w:"alek",t:"……走ればな。",v:"13_0280"}];
GR_SC.g13_14=[{w:null,t:"峠の向こう側。"},{w:null,t:"店先の棚に、色ちがいの毛糸のマフラーの山。"},{w:null,t:"エリー、からし色を首に巻く。"},{w:null,t:"エリー、赤いのを、ヤマトにわたす。"},{w:"hero",t:"赤とか、目立つじゃん。おれたち、追われてるのに。",v:"13_0287"},{w:"elly",t:"でもヤマト、目立つの好きでしょ。",v:"13_0288"},{w:null,t:"ヤマト、だまって巻く。"},{w:null,t:"エリー、マフラーを巻かれて固まっているアレクのパーカーの内ポケットから、手のひら大のうすいカードを、すっと抜き取る（アナの、名前のつかないジェムコインのカード。"},{w:"x",n:"店のおばあさん",t:"三本で六つでいいよ。冬の売れ残りだからね。ほつれてても、文句なしだよ。",v:"13_0292"},{w:"alek",t:"おい、勝手に使うなよ！　大会の参加料の分は、残しとかないとだめだろ！",v:"13_0294"},{w:"elly",f:"surprised",t:"ちゃんと残ってるよ。それに、首が寒いままじゃ、勝負もできないよ。",v:"13_0295"},{w:"alek",t:"引っぱるなって！　全部ほどけたら、買った意味がないだろ！",v:"13_0298"}];
GR_SC.g13_15=[{w:null,t:"三人の横を、黒い大きなトラックが追いこしていく。"},{w:null,t:"うしろの席。"},{w:null,t:"男、指で、写真の横に小さく丸をつける。顔を上げない。"},{w:null,t:"荷台の布のすきまから、先だけ虹色の羽が一枚のぞいて、すぐ引っこむ。"},{w:null,t:"アレクの目が、トラックの横腹の輪を追う。"}];
GR_BT[13]={mid:[[{w:"hero",t:"フォルン、上だ！　あいつのとこまで行け！",v:"13_0181"},{w:"alek",t:"クロッコ、右の岩をつたって、上まで行け！",v:"13_0185"},{w:null,t:"アレク、クロッコを抱き上げる。指が、背中で止まる。"},{w:"elly",t:"ピリポン、左から回って！",v:"13_0189"}],[{w:"elly",t:"ピリポン、もどって！",v:"13_0192"},{w:"alek",t:"ヤマト、さがれ！　戸の中に入れ！",v:"13_0199"},{w:"hero",t:"フォルン、さがれ！　もう、さがっていいから！",v:"13_0201"},{w:null,t:"ヤマトの目が、雷の輪のあとを見る。"},{w:null,t:"ヤマト、口を閉じる。"},{w:null,t:"ヤマトの左の手首の画面で、時計の形のアイコンが光る。"},{w:null,t:"ヤマトの口が、「追え」の形に開きかける。"},{w:"hero",f:"serious",t:"……追うな。そこから撃て。",v:"13_0220"}]],post:[{w:null,t:"冠のいなずまが、ふっと消える。"},{w:null,t:"夕日の雪原。"}]};
GR_EP[13]={"t": "雲の山道", "sc": [["g13_01", "雲の山・峠（夕方・吹雪）", 0], ["g13_02", "雲の山道（昼）", 0], ["g13_03", "雲の中（夕方）", 0], ["g13_04", "避難小屋の前（夕方）", 0], ["g13_05", "避難小屋の中（夜）", 0], ["g13_06", "避難小屋の中（次の日・吹雪）", 0], ["g13_07", "避難小屋の前（夕方）", 0], ["g13_08", "向かい合う", 0], ["g13_09", "勝負", 1], ["g13_10", "勝負のあと", 0], ["g13_11", "避難小屋の中（夜）", 0], ["g13_12", "避難小屋（夜明け前）", 0], ["g13_13", "避難小屋の前（朝）", 0], ["g13_14", "ふもとの町・小さな店の前（夕方）", 0], ["g13_15", "ふもとの町を出る道（夜）", 0]]};
GR_SC.g14_01=[{w:null,t:"運河の町コリンタ。海と海を、まっすぐな水の道がつないでいる。",v:"14_0023"},{w:null,t:"切り立った岩のかべのあいだを、細い運河がまっすぐ走る。"},{w:null,t:"橋のたもとに、人の形をした黒いロボットが四台。"},{w:null,t:"橋の手前に、貨物船が何そうも、つらなって止まっている。"},{w:null,t:"運河の上を、黒いドローンが二機、低く飛んでいく。赤い光の帯で、岸を歩く人の顔を、一人ずつなでていく。"},{w:null,t:"船室の窓から、ひげの男が顔を出す。"},{w:null,t:"橋のたもとに、黒い大きなトラック。"},{w:null,t:"ユスフ、数えていた指を、ぎゅっとにぎる。"},{w:null,t:"第14話　運河の町コリンタ",v:"14_0032"}];
GR_SC.g14_02=[{w:null,t:"三人が山の道から下りてくる。"},{w:null,t:"運河の岸で、洗たく屋のおばさん（2100年の作業着）の水の子が、つるしたシーツに霧をふいている。"},{w:null,t:"広場のまん中に、古い丸いモザイクの床。"},{w:null,t:"画面の中。小さな子が、大きな相手に押されて、はしまで下がる。"},{w:"x",n:"実況の声",t:"ふんばったーっ！　変わったーっ！",v:"14_0042"},{w:null,t:"子どもたちがわっとさけぶ。上着を肩にかけた男の子が、いちばん大きく手をたたいている。"},{w:null,t:"エリー、画面の小さい方の子を、じっと見ている。"},{w:null,t:"ヤマト、足もとのフォルンを両手で持ち上げて、子どもたちのうしろから割りこむ。"},{w:"hero",t:"おれのフォルンもな、あれより、もっとでっかくなるんだぜ。",v:"14_0046"},{w:"x",n:"子ども",t:"ちっちゃ。ほんとに？",v:"14_0047"},{w:"hero",t:"勝負になったらな。見てろよ。",v:"14_0048"},{w:null,t:"ヤマト、モザイクのまん中にフォルンを置く。"},{w:"hero",t:"フォルン、変われ。",v:"14_0050"},{w:null,t:"フォルン、毛づくろいを始める。"},{w:"hero",f:"serious",t:"……こう、ぶわっとだよ、ぶわっと。",v:"14_0052"},{w:"alek",t:"お前、顔が町じゅうに映ったんだぞ！　追われてるの、分かってるのか！",v:"14_0057"},{w:"hero",t:"一瞬だけじゃん。だれも、ちゃんと見てないって。",v:"14_0058"},{w:"yusuf",t:"お兄ちゃん、画面に出てた！　ぼく、ユスフ。うちの船、すぐそこだよ。",v:"14_0061"}];
GR_SC.g14_03=[{w:null,t:"さびた甲板。"},{w:"yusuf",t:"二年前に、この船で来たの。父さんと二人で。",v:"14_0065"},{w:null,t:"ユスフ、絵地図の小さな丸を、一つずつ指でさす。"},{w:"yusuf",t:"ここがパン屋さん。きのう、ぼくの名前、おぼえてくれたの。ここは、サッカーする所。",v:"14_0067"},{w:null,t:"ユスフの指が、パン屋の丸を何回もなぞる。"},{w:"yusuf",t:"でもね、父さん、あさってから白い都の港で仕事なの。橋が上がったままだと、船が通れないんだって。",v:"14_0069"},{w:"elly",t:"橋、いつから止まってるの？",v:"14_0070"},{w:"yusuf",t:"きのうの夕方から。黒いロボットが来て、ミハリスさんを小屋から追い出しちゃった。",v:"14_0071"},{w:null,t:"アレク、甲板のはしから、上がったままの橋を見ている。"},{w:"alek",t:"……ヴィクターだ。橋を上げておけば、北へ行くやつは、みんなここで止まる。",v:"14_0073"},{w:"hero",t:"北って、白い都だろ。おれたちのこと、待ってるのかよ。",v:"14_0074"},{w:"alek",t:"向こう岸へ渡るには、あの橋か、船しかない。待つなら、ここだ。",v:"14_0075"},{w:"yusuf",t:"あの橋ね、沈むんだよ。水の中に沈めて、その上を船が通るの。ミハリスさんがレバーで。",v:"14_0076"},{w:"hero",t:"橋が、沈むの？　上がるんじゃなくて？",v:"14_0077"},{w:"yusuf",t:"うん。あとね、あのとりでの上に、泉があるの。羽のある馬が、ひづめでこんってやったら、水が出たんだって。",v:"14_0078"},{w:null,t:"ユスフ、町の上の岩山を指さす。"},{w:null,t:"ヤマト、足で甲板を、こんとける。"},{w:null,t:"ヤマトの指が、左の手首の画面の、時計のアイコンに当たる。"}];
GR_SC.g14_04=[{w:null,t:"黒いロボットのあいだの、折りたたみの机。"},{w:null,t:"橋の横の小屋の窓から、油だらけの手の男が、こっちを見ている。"},{w:null,t:"男、顔を上げる。"},{w:"nomos",t:"さきほど、広場の画面で拝見しました。ヴィクターで現場主任をしております、ノモスです。……アレク。名簿では、消されたことになっていますが。",v:"14_0087"},{w:"alek",t:"ノモスさん。ぼくは、もう抜けました。ヴィクターの人間じゃありません。",v:"14_0088"},{w:"nomos",t:"抜けた、とは聞いていません。抜ける時は届けを出す決まりですので。",v:"14_0089"},{w:null,t:"ノモス、画面を流す。"},{w:"nomos",t:"そちらの娘さんを、お連れします。上からの決まりですので。",v:"14_0091"},{w:"elly",t:"えー、やだ。わたし、白い都に行くんだもん。",v:"14_0092"},{w:"hero",t:"連れてくって、どこにだよ。",v:"14_0093"},{w:"nomos",t:"上が決めます。わたしは、お連れするだけです。",v:"14_0094"},{w:null,t:"エリーの目が、画面のいちばん下の字で止まる。"},{w:"elly",t:"ヴィクターさんって、丘でケーキをくれた人だよ？",v:"14_0096"},{w:"elly",t:"一味と同じ名前の、別の人じゃないの？",v:"14_0097"},{w:"alek",t:"同じ人だよ。あの人が、ヴィクター本人なんだ。",v:"14_0098"},{w:"alek",t:"見回りの胸にも、この輪がついてたろ。",v:"14_0099"},{w:"elly",f:"surprised",t:"え、二人とも知ってたの！？　なんで言ってくれなかったの！",v:"14_0100"},{w:"hero",t:"だってエリー、すぐ顔に出るじゃん。",v:"14_0101"},{w:null,t:"エリー、ほっぺたをふくらませて、ノモスをにらむ。顔に、全部出ている。"},{w:null,t:"ノモスのうしろで、黒いロボットが一歩前に出る。ノモス、手を上げて止める。"},{w:"nomos",t:"ただし、力ずくは禁止されております。娘さんに、かすり傷ひとつ、つけるなと。",v:"14_0104"},{w:"hero",t:"じゃあ、勝負しろよ。テリオンどうしなら、だれもけがしないだろ。",v:"14_0105"},{w:"nomos",t:"申しこまれたら、受ける決まりです。わたしが負けたら、ロボットは橋から引き上げます。",v:"14_0106"},{w:null,t:"甲板の上で、ユスフが顔を上げる。"},{w:"alek",t:"そちらが勝ったら、どうなるんですか。",v:"14_0108"},{w:"nomos",t:"娘さんは、お連れします。それと、その狐も。名簿にありますので。",v:"14_0109"},{w:null,t:"ノモス、かごの布に手をかける。"},{w:"nomos",t:"上から、この子を使うように、と言われております。",v:"14_0111"},{w:null,t:"布が取られる。"},{w:null,t:"右の羽の付け根に、白っぽい古い傷あと。"},{w:null,t:"エリーの笑顔が、そのまま止まる。"},{w:"elly",f:"serious",t:"……ニジッコ？",v:"14_0115"},{w:null,t:"鳥の頭が、ぴくっと動く。"},{w:null,t:"ノモスの指が画面をたたく。"}];
GR_SC.g14_05=[{w:null,t:"運河の広場。"},{w:null,t:"鳥は、奥の柱の上に下りて、羽をたたむ。"},{w:null,t:"ノモスの指が、画面を二回たたく。"},{w:null,t:"岸に町の人が集まる。"},{w:null,t:"ヤマト、フォルンを石だたみに下ろす。"},{w:null,t:"エリー、髪の中のピリポンに、指先でふれる。指が止まっている。"},{w:"nomos",t:"（手首の画面を見て）では、始めます。",v:"14_0129"}];
GR_SC.g14_07=[{w:null,t:"干し草の上の木の箱。"},{w:null,t:"8歳のエリーが、ぶどうを一粒、黄色いひよこに近づける。"},{w:null,t:"ひよこの右の羽の付け根に、小さな白い傷。"},{w:null,t:"夕方。物置が暗くなる。"},{w:null,t:"次のしゅんかん、ひよこの体がぽうっと光る。"},{w:null,t:"物置の前に、黒い車。"},{w:null,t:"エリーが、ロボットの腕にしがみつく。"},{w:null,t:"札の画面の「えりい」の字が、箱といっしょに車の中へ消える。"},{w:null,t:"坂の上に、羽が一枚。"}];
GR_SC.g14_09=[{w:null,t:"ナルカミが光ってしぼみ、小さなピリポンにもどる。"},{w:null,t:"石だたみに、割れたチップ。"},{w:null,t:"鳥が起き上がる。"},{w:null,t:"エリー、ピリポンを髪にのせたまま、人さし指を、そっと前に出す。"},{w:null,t:"鳥が、ひと羽ばたきで、エリーの指にとまる。"},{w:null,t:"鳥の羽が、ぷうっとふくらむ。"},{w:null,t:"エリーは、指を曲げない。手を、ひらく。"},{w:null,t:"鳥が飛び立つ。"},{w:null,t:"エリーの手は、しばらく、そのままの形で上がっている。"},{w:null,t:"ノモス、画面の「受け取り　失敗」を見て、消す。"},{w:"nomos",t:"負けましたので、ロボットは橋から引き上げます。決まりですから。",v:"14_0212"},{w:null,t:"黒いロボットたちが、列になってトラックに乗りこむ。"},{w:null,t:"ノモスが机をたたむひょうしに、画面の板が一枚すべり落ちる。"},{w:null,t:"クロッコがのそのそ歩いていって、曲がったあごで板をくわえ、アレクの足もとに置く。"}];
GR_SC.g14_10=[{w:null,t:"画面の板。「集める子の名簿」。"},{w:"hero",t:"……おれの名前まで載ってる。手首の画面の記録って、なんだよ。",v:"14_0219"},{w:"alek",t:"お前の画面を使えば、名前も居場所も向こうに分かるってことだ。白い都でも、どこかにかざすなよ。",v:"14_0220"},{w:null,t:"ヤマト、足もとのフォルンを、だまって抱き上げる。"},{w:"hero",t:"保護局って、国の役所だろ。なんで、ヴィクターの名簿に、役所の印があるんだよ。",v:"14_0222"},{w:"alek",t:"役所で持ち主のいない子を調べて、ヴィクターに回してるんだ。役所の中に、仲間がいるんだよ。",v:"14_0223"},{w:null,t:"アレクの指が、板をめくる。"},{w:null,t:"ヤマト、肩のフォルンの耳のうしろを、指でさわる。"},{w:"elly",t:"大理石の谷って、どこにあるの？",v:"14_0226"},{w:"alek",t:"白い都の、すぐ手前だ。昔、案内で行ったことがある。",v:"14_0227"},{w:null,t:"アレク、板の字を、上から下まで、ゆっくり目で追う。それから、運河のふちに立つ。"},{w:"hero",t:"それ、どうすんの。……え、ちょっと待って！　それ、証拠だろ！",v:"14_0229"},{w:null,t:"アレク、板を運河に落とす。"},{w:"alek",t:"ヴィクターの板だぞ！　持ってたら、居場所を向こうに教えてるのと同じだろ！　中身は、全部覚えた。",v:"14_0231"},{w:"hero",f:"serious",t:"……ほんとに全部？",v:"14_0232"},{w:"alek",t:"保管場所は、大理石の谷。印は、保護局の課長。それだけ分かれば、行ける。",v:"14_0233"},{w:null,t:"エリー、北の山の方を見る。"}];
GR_SC.g14_11=[{w:null,t:"橋の横の小さな小屋。"},{w:"yusuf",t:"ミハリスさん、橋、沈めてよ。黒いロボット、もういないよ。",v:"14_0238"},{w:"mihalis",t:"あいつら、鍵をかけていった。この鍵は、わたしには開けられない。",v:"14_0239"},{w:"yusuf",t:"でも、もういないんだよ。",v:"14_0240"},{w:"mihalis",t:"いなくても、鍵は残ってるんだ。",v:"14_0241"},{w:null,t:"窓の外を、黒いドローンが一機、赤い光の帯で岸をなめながら飛んでいく。"},{w:null,t:"ユスフ、戸口の段に座って、袋のパンをちぎる。"},{w:"yusuf",t:"パン屋さんがくれたの。ぼくの名前、ちゃんと言って。",v:"14_0244"},{w:null,t:"ミハリスの手が止まる。"},{w:null,t:"フォルンが、パンのかけらをしっぽの火であぶっている。"},{w:null,t:"ミハリス、立ち上がる。"},{w:"alek",t:"ミハリスさん。手で沈めたら、ヴィクターに目をつけられるんじゃないですか。",v:"14_0248"},{w:null,t:"ミハリス、答えない。"},{w:"mihalis",t:"この橋は、あいつらの物になる前から、わたしが沈めてきたんだ。",v:"14_0250"}];
GR_SC.g14_12=[{w:null,t:"ユスフの船が、沈んだ橋の上をゆっくり通る。"},{w:null,t:"甲板のすみで、エリーがユスフの父さんの手首の画面を借りて、小さな声でアナにかけている。"},{w:null,t:"北の岸の小さな船着き場で、三人が下りる。"},{w:"yusuf",t:"ぼくら、このまま白い都の港まで行くの。父さんの仕事、間に合うって。",v:"14_0259"},{w:"elly",t:"よかったね、ユスフ。パン屋さんには、また来られる？",v:"14_0260"},{w:"yusuf",t:"うん。仕事が休みの日に、船で来るんだ。",v:"14_0261"},{w:null,t:"ひげの男が、操舵室の窓から一回うなずく。"},{w:null,t:"甲板のはしで、ユスフが右の手のひらを上げる。"},{w:null,t:"船着き場の上の道に、案内の柱。"},{w:null,t:"その道を、ヴィクターの黒いトラックが一台、また一台と走っていく。"},{w:null,t:"エリーの目が、トラックを追う。"}];
GR_BT[14]={mid:[[{w:"hero",t:"フォルン、行け！　柱まで突っこめ！",v:"14_0132"},{w:"elly",t:"ピリポン、橋まで行って！",v:"14_0136"},{w:"elly",t:"ニジッコ！",v:"14_0140"},{w:null,t:"ノモスが画面をたたく。"},{w:null,t:"ヤマトの目が、柱の前のフォルレオンから、うしろへ行く。"},{w:"hero",f:"serious",t:"……フォルン、もどれ。橋の前でいい。",v:"14_0145"},{w:null,t:"アレク、運河の水を見ている。"},{w:"alek",t:"クロッコ、水に入れ！　向こう岸まで泳げ！",v:"14_0148"},{w:"elly",t:"ニジッコ、やめて！",v:"14_0153"},{w:null,t:"エリー、口を開けたまま止まる。"}],[{w:null,t:"エリー、もう呼ばない。"},{w:"elly",t:"ピリポン、左へ走って！　石の柱まで！",v:"14_0173"},{w:null,t:"エリーの目が、そこで止まる。"},{w:"elly",t:"ピリポン、柱のうしろ！",v:"14_0178"},{w:null,t:"エリーの目が、ピリムサの毛へ行く。それから、広場の空中の画面へ。"},{w:null,t:"エリーは、何も言わない。"},{w:"elly",t:"ピリポン！",v:"14_0194"},{w:"hero",t:"フォルン、今だ！",v:"14_0196"}]],post:[{w:null,t:"鳥の耳のうしろで、ぱきん、と小さな音。"},{w:null,t:"鳥が、柱の上からゆっくり落ちる。"}]};
GR_EP[14]={"t": "運河の町コリンタ", "sc": [["g14_01", "運河（夜明け）", 0], ["g14_02", "コリンタの広場（朝）", 0], ["g14_03", "止められた貨物船（朝）", 0], ["g14_04", "大橋のたもと", 0], ["g14_05", "向かい合う", 0], ["g14_06", "勝負", 1], ["g14_07", "オリーヴァ村・ぶどう畑の奥の物置（6年前）", 0], ["g14_08", "勝負・つづき", 1], ["g14_09", "勝負のあと", 0], ["g14_10", "橋のたもと（昼すぎ）", 0], ["g14_11", "技師の小屋（夕方）", 0], ["g14_12", "運河（夜）", 0]]};
GR_SC.g15_01=[{w:null,t:"大理石の谷。白い都の神殿の石は、ぜんぶ、ここから運ばれた。",v:"15_0023"},{w:null,t:"天井の高い、白い大理石の広間。"},{w:null,t:"ケースの中で、小さなテリオンたちが眠っている。"},{w:null,t:"人の形をした黒いロボットが、札の画面を一つずつ指でなぞって、字を書きかえていく。"},{w:null,t:"広間の奥。大理石の台の上に、鷲の頭と翼、獅子の胴の獣。"},{w:"x",n:"警備のAIの声",t:"警備は、本日もテリオン一体です。経費は、前の年の八割減です。",v:"15_0028"},{w:null,t:"見張りの目が、うすく開く。"},{w:null,t:"第15話　大理石の谷",v:"15_0031"}];
GR_SC.g15_02=[{w:null,t:"山を巨大な包丁で切ったような、まっ白ながけ。"},{w:null,t:"谷のふちで、三人が腹ばいになって見下ろしている。"},{w:null,t:"望遠鏡の中。"},{w:"alek",t:"……ヴィクターの印だ。昔、ここも案内してたんだ。あの辺の石で、白い都の丘の神殿を建てた。牛で引いて、何年もかけてな。",v:"15_0040"},{w:null,t:"エリー、がけを指でなぞる。それから、建物を見る。"},{w:"elly",t:"……あの日ね、あの車に、ほかの子も乗ってたの。ここに、いるかな。",v:"15_0042"},{w:null,t:"ヤマトとアレクがエリーを見る。"},{w:"alek",t:"おれは、あの名簿の続きが知りたい。板は運河に沈めた。だから、課長の印のことを、ほかの人に見せる物がないんだ。",v:"15_0044"},{w:null,t:"ヤマトは谷の切れ目の先を見ている。"},{w:"hero",t:"大会、あしただぞ。分かってるよな。",v:"15_0046"},{w:"alek",t:"だから、きょうのうちに入るんだ。",v:"15_0047"},{w:"hero",t:"分かってるって。言ってみただけ。",v:"15_0048"},{w:null,t:"ヤマト、立ち上がって、両手を口に当てる。"},{w:"alek",t:"おい、待て——",v:"15_0050"},{w:"hero",t:"やっほーーー！",v:"15_0051"},{w:"x",n:"こだま",t:"……やっほー……やっほー……やっほー……",v:"15_0052"},{w:null,t:"ヤマト、ふり返って、にやっと笑う。"},{w:"hero",f:"smile",t:"三回！　すげえ、三回も返ってきた！",v:"15_0054"},{w:null,t:"四回目のかわりに、谷のスピーカーが鳴る。"},{w:"x",n:"谷のスピーカーの声",t:"ただいま、作業中です。お静かにお願いいたします。",v:"15_0056"},{w:null,t:"建物の屋根から、黒いドローンが二機、ふわりと浮いて、こっちを向く。"},{w:null,t:"アレク、ヤマトのマフラーをつかんで、うしろへ引き倒す。"},{w:null,t:"アレク、マフラーをはなさない。"},{w:"alek",t:"お前な！　これで、正面からは近づけなくなったんだぞ！",v:"15_0060"},{w:"elly",t:"じゃあ、どこから入るの？",v:"15_0061"},{w:null,t:"アレク、がけの下を指さす。"},{w:"alek",t:"昔の石切り場の、排水路だ。あそこなら、門もカメラもない。",v:"15_0063"}];
GR_SC.g15_03=[{w:null,t:"石の管の中。"},{w:"hero",f:"serious",t:"……くっせえ。なんだよ、ここ。",v:"15_0067"},{w:"alek",t:"だれのせいで、ここを歩いてると思ってるんだ！",v:"15_0068"},{w:null,t:"ヤマト、鼻をつまんで前を向く。"},{w:null,t:"ヤマトの足が、ぬるっとした物をふむ。両手をばたばた。"},{w:null,t:"エリー、カバンを頭の上に持ったまま、ヤマトの上をまたいで通る。"},{w:null,t:"フォルン、アレクの頭の上から、ずぶぬれのヤマトを見下ろしている。"},{w:null,t:"上に、金属の格子が三つ。"},{w:null,t:"アレク、冷たい水に手を入れる。"}];
GR_SC.g15_04=[{w:null,t:"床の格子が、がたんと持ち上がる。"},{w:null,t:"エリーがケースの並びのあいだを走る。"},{w:null,t:"エリーの足が止まる。"},{w:null,t:"丸い耳の子。ふさふさのしっぽの子。"},{w:null,t:"エリー、ガラスに両手をつける。"},{w:null,t:"アレクは札のいちばん下を見ている。"},{w:"alek",t:"……名前まで出てる。課長は、ニコスってやつだ。",v:"15_0083"},{w:null,t:"アレク、天井を見上げる。"},{w:null,t:"広間の奥で、台の上の影が目を開ける。"},{w:null,t:"グリフォが立ち上がる。"},{w:"x",n:"警備のAIの声",t:"侵入者のテリオンを確認しました。",v:"15_0087"}];
GR_SC.g15_05=[{w:null,t:"大理石の床。"},{w:null,t:"台の上で、グリフォの体が金色に光る。"},{w:null,t:"ヤマトの肩から、フォルンが床に飛び下りる。"},{w:"x",n:"警備のAIの声",t:"ケースに近づく物を、とりのぞきます。",v:"15_0096"}];
GR_SC.g15_07=[{w:null,t:"三体が光って、小さなフォルン、ピリポン、クロッコにもどる。"},{w:"x",n:"警備のAIの声",t:"警備のテリオンが倒れました。担当には、あしたの朝、お知らせします。",v:"15_0149"},{w:"hero",f:"serious",t:"……あしたの朝？　今じゃないのかよ。",v:"15_0150"},{w:"x",n:"警備のAIの声",t:"夜のお知らせは、経費をへらすため、行っておりません。",v:"15_0151"},{w:null,t:"見張りが目を開ける。"},{w:null,t:"グリフォ、ゆっくり歩いていって、ケースの並びの前で羽をたたんで伏せる。"},{w:"elly",f:"serious",t:"……この子、守ってるのかな？",v:"15_0154"},{w:"alek",t:"（案内の時の言い方で）グリフォンは、金の番をする。昔から、そう言われてるんだ。",v:"15_0155"},{w:null,t:"エリーが、いちばん近いケースに走る。"},{w:null,t:"ヤマトが来て、いっしょに引く。"},{w:"hero",t:"手のひらの鍵って、なんだよ。",v:"15_0158"},{w:null,t:"アレク、自分の右の手のひらを見る。"},{w:"alek",t:"……ヴィクターの手下が、ここに入れてるチップだ。それで、アジトの戸も箱も開く。",v:"15_0160"},{w:"elly",t:"アレクにも、入ってるの？",v:"15_0161"},{w:null,t:"アレク、少しだけまよってから、手のひらを錠にかざす。"},{w:"alek",t:"……だろうな。おれは、抜けたんだから。",v:"15_0163"},{w:null,t:"伏せたグリフォが、三人を見ている。"},{w:null,t:"エリー、ガラスに額をつける。中の子は、目を開けない。"},{w:"elly",f:"sad",t:"……ごめんね。開けられないや。",v:"15_0166"},{w:null,t:"アレク、天井のカメラを見上げる。それから、広間の奥のガラス戸の小部屋を見る。"},{w:"alek",t:"開けられないなら、見せるしかない。あそこの部屋の画面なら、このカメラの写真を外へ送れる。",v:"15_0168"},{w:"hero",t:"送るって、だれにだよ。警察か？",v:"15_0169"},{w:"alek",t:"警察は、持ち主のいない子のためには動かない。保護局の、研究所の所長に送る。課長とは別の所の人で、ちゃんとした人だ。",v:"15_0170"}];
GR_SC.g15_08=[{w:null,t:"ガラス戸の小部屋。"},{w:null,t:"アレク、机の画面の報告を、指で流していく。一つで手が止まる。"},{w:null,t:"ヤマトが横からのぞいて、左の手首の画面の、時計のアイコンにふれる。"},{w:null,t:"細い窓の向こう、ずっと遠くの海がわに、港の塔。"},{w:"alek",t:"……本番って、何をやる気なんだよ。",v:"15_0177"},{w:"hero",t:"じいちゃんの印と、同じ場所だぞ。",v:"15_0178"},{w:null,t:"だれも、その先を言わない。"},{w:null,t:"エリーは、壁の画面の前に立っている。"},{w:"elly",f:"serious",t:"……おっきいね。町より、おっきい。",v:"15_0181"},{w:null,t:"ヤマト、絵の巨人の腕と、自分の腕を見くらべる。口をとじる。"},{w:null,t:"アレク、壁の絵も写しにとる。"},{w:null,t:"送り先の欄に、「テリオン保護局　研究所　所長」。アレクの指が、所長の名前の上で、少しだけ止まる。"},{w:"alek",t:"出るぞ。あいつが知らせるのは、あしたの朝だ。それまでに、谷を出る。",v:"15_0185"},{w:null,t:"エリー、広間をふり返る。"}];
GR_SC.g15_09=[{w:null,t:"暗い部屋。画面の明かりだけ。"},{w:null,t:"画面の横に、もう一つの窓。"},{w:null,t:"女の指が、ボタンの上に来て、止まる。"},{w:null,t:"指を下ろす。"}];
GR_SC.g15_10=[{w:null,t:"大きな窓。すぐ外に、港の埋め立て地の白い電波の塔。"},{w:null,t:"机にケーキの箱と紅茶。"},{w:null,t:"画面の中に、部下の男。"},{w:"x",n:"画面の声",t:"谷のドローンが、けさ撮ったものです。昼すぎには、排水路の出口に子どもの足あとが。どういたしましょう。",v:"15_0198"},{w:"victor",t:"……へえ。元気な子たちだね。",v:"15_0199"},{w:null,t:"ヴィクター、写真をとじる。"},{w:"victor",t:"放っておいていいよ。あそこは、もう要らない。",v:"15_0201"},{w:"victor",t:"大会は予定どおり。買い手のみなさんにも、そう伝えて。",v:"15_0202"},{w:"victor",t:"勝ち方は、もう分かってる。",v:"15_0203"},{w:null,t:"港の塔のてっぺんの赤い明かり。"},{w:null,t:"白い都の港。"},{w:null,t:"甲板で、三人が、船にあった薄くて軽い掛け物にくるまって、並んで寝そべっている。となりでユスフの寝息。"},{w:null,t:"ヤマト、塔を見たまま、左の手首の画面を、右手でにぎっている。"}];
GR_BT[15]={mid:[[{w:"elly",t:"ピリポン、行こう！",v:"15_0100"},{w:null,t:"エリーの目が水路を追う。"},{w:"elly",t:"待って！　ピリポン、撃っちゃだめ！",v:"15_0105"},{w:null,t:"アレク、エリーを見る。それから、水路を見る。"},{w:"hero",t:"じゃあ、こっちでやる！　フォルン、前だ！",v:"15_0109"},{w:"hero",t:"もう一発！",v:"15_0112"},{w:null,t:"ヤマト、口をあける。"},{w:null,t:"アレクの目が、水路を追う。"},{w:"alek",t:"クロッコ、流れに乗れ！　そのまま奥まで行け！",v:"15_0119"},{w:"hero",t:"フォルン、もう一回！　こっちを向かせろ！",v:"15_0123"},{w:null,t:"ヤマトの左の手首の画面で、時計の形のアイコンが光る。"}]],post:[{w:null,t:"見張りが、台から床にすべり落ちる。羽を広げたまま、目を回して動かない。"},{w:null,t:"ケースの中の子たちは、眠ったまま。"}]};
GR_EP[15]={"t": "大理石の谷", "sc": [["g15_01", "大理石の谷・保管庫（夜）", 0], ["g15_02", "谷の上（朝）", 0], ["g15_03", "古い排水路（昼）", 0], ["g15_04", "保管庫（昼）", 0], ["g15_05", "向かい合う", 0], ["g15_06", "勝負", 1], ["g15_07", "勝負のあと", 0], ["g15_08", "保管庫のとなりの事務室", 0], ["g15_09", "研究所・所長室（夜）", 0], ["g15_10", "白い都の海がわ・新しい港のビルの最上階・ヴィクターの部屋（夜）", 0]]};
GR_SC.g16_01=[{w:null,t:"白い都。神殿の丘のふもとに、二千年分の町が積み重なっている。",v:"16_0021"},{w:null,t:"古い神殿の丘。"},{w:null,t:"神殿の屋根より低い所を、広告のドローンが飛ぶ。"},{w:null,t:"カメラが海の方へ引く。"},{w:null,t:"大競技場。古い石の客席の段の上を、うすいガラスの屋根がおおっている。"},{w:null,t:"競技場の裏に、黒塗りのロボタクシーが何台も並ぶ。"},{w:null,t:"出むかえる、白いスーツの男。いつもの笑顔。"},{w:"victor",t:"ようこそ、遠いところを。きょうは、いい物をお見せしますよ。",v:"16_0028"},{w:null,t:"ヴィクター、競技場の屋根を見上げる。"},{w:null,t:"第16話　白い都の大会",v:"16_0031"}];
GR_SC.g16_02=[{w:null,t:"広場はお祭り。"},{w:null,t:"エリーが、両手に串焼きを持って、もう一本くわえている。"},{w:"elly",t:"はい、これ。屋台の焼き台が止まって、おじさんが困ってたの。ピリポンがぱちってしたら、動いたんだよ。",v:"16_0039"},{w:null,t:"屋台の電気の焼き台の上で、ピリポンの毛がまだぱちぱち鳴っている。おじさんが手をふっている。"},{w:"elly",t:"そしたら、お礼に三本くれたの。カードの残りも、減らなくてすんだよ。",v:"16_0041"},{w:"alek",t:"それなら、先に言えよ！　おれ、屋台の前で、カードの残りで何本買えるか、ずっと計算してたんだぞ。",v:"16_0042"},{w:"elly",t:"えー、アレク、ずっと屋台の前に立ってたのって、それだったの？",v:"16_0043"},{w:null,t:"アレク、串を受け取って、だまって一口かじる。"},{w:null,t:"ヤマトは、入口の大きな空中の組み合わせ表の前に立っている。"},{w:null,t:"表のいちばん上に、金色の字。"},{w:null,t:"ヤマトの目が、金色の字から足もとのフォルンへ。"},{w:null,t:"広場の上を、黒いドローンが二機、高く回っている。"},{w:null,t:"アレク、ヤマトの赤いマフラーを、鼻の上まで引き上げる。"}];
GR_SC.g16_03=[{w:null,t:"受付の机の横に、腕が一本の白いカメラの機械。"},{w:"x",n:"受付の係",t:"はい、次の方。参加料は、ジェムコインで十五です。それから、手首の画面をこの板にかざしてください。お名前と住所が、自動で入ります。",v:"16_0053"},{w:null,t:"ヤマト、左の手首を板の上に出しかける。"},{w:"alek",t:"（小さく）かざすなって！　名前も居場所も、全部記録に残るんだぞ。名簿に「狐」って書かれてたの、忘れたのかよ。",v:"16_0055"},{w:"hero",t:"（小さく）でも、かざさないと、名前が入らないじゃん。どうやって出るんだよ。",v:"16_0056"},{w:"x",n:"受付の係",t:"手首の画面をお持ちでない方は、こちらに、登録名を指で書いてください。",v:"16_0057"},{w:null,t:"係が、光る板の横の、字を書く画面を指さす。"},{w:"hero",t:"（小さく）書くのはいいけど、なんて書けばいいんだよ。本名はだめなんだろ。",v:"16_0059"},{w:"alek",t:"（小さく）なんでもいい。本名じゃなければ。",v:"16_0060"},{w:"hero",t:"（小さく）なんでもいいって言われるのが、いちばん困るんだって。",v:"16_0061"},{w:null,t:"エリーが、二人のあいだから串焼きごと顔を出す。"},{w:"elly",t:"ダレデモナイは？　おばあちゃんのお話に出てくる人。一つ目の巨人に、そう名のって、だましたの。",v:"16_0063"},{w:"hero",t:"巨人をだました名前か。それ、ちょっとかっこいいじゃん。",v:"16_0064"},{w:"elly",t:"でしょ。巨人が「ダレデモナイにやられた」って叫んでも、仲間はだれも助けに来なかったんだよ。",v:"16_0065"},{w:null,t:"ヤマト、もう指で書いている。"},{w:"x",n:"受付の係",t:"登録名の変更は、受けつけておりません。なりすまし防止のためです。",v:"16_0067"},{w:null,t:"アレク、天井を見る。"},{w:null,t:"アレク、パーカーの内ポケットから、手のひら大のうすいカードを出して、エリーにわたす。"},{w:null,t:"ヤマト、フォルンを両手で高くカメラに向ける。自分も横から顔をよせて、歯を見せていちばんの顔。"},{w:null,t:"ぱしゃ、の直前。フォルンが首をくるっと反対へひねる。"},{w:null,t:"画面に、歯を見せたヤマトと、そのとなりに、ふさふさのしっぽだけ。"},{w:"x",n:"受付の機械の声",t:"登録にない形式です。判定、できません。",v:"16_0073"},{w:"hero",t:"もう一回！　今のなし！　次は、ちゃんと前を向かせるから！",v:"16_0074"},{w:null,t:"ぱしゃ。しっぽ。"},{w:null,t:"係、画面を見て、うしろに並ぶ大勢の人を見る。"},{w:"x",n:"受付の係",t:"……次の方。",v:"16_0077"},{w:null,t:"ヤマト、押し出されながら、しっぽだけの写真を、まだ手首の画面でのぞきこんでいる。"},{w:null,t:"机の画面の登録の一覧が、次の人の分で一行上がる。"}];
GR_SC.g16_04=[{w:null,t:"客席は満員。"},{w:"x",n:"司会",t:"昔むかし、この町の名前をめぐって、二人の神さまが、町の人に贈り物をくらべさせました！",v:"16_0083"},{w:null,t:"海の神がほこで地面をつく。"},{w:null,t:"女神がやりで地面をつく。"},{w:"x",n:"司会",t:"町の人が選んだのは、オリーブ！　それで、この町は女神の名前になったのです！",v:"16_0086"},{w:null,t:"拍手。役者たちが下がる。"},{w:"elly",t:"オリーヴァ村のオリーブも、ここの木から来たのかな。",v:"16_0088"},{w:"alek",t:"さあな。案内の仕事の時は、村のじいさんたちが、そう自慢してたって話してた。本当かどうかは知らない。",v:"16_0089"},{w:"elly",t:"えー、本当かどうか知らないのに、お客さんに話してたの？",v:"16_0090"},{w:"alek",t:"お客さんが喜ぶ話をするのが、案内の仕事なんだよ。",v:"16_0091"},{w:null,t:"ヤマト、オリーブの木の根もとを見ている。"}];
GR_SC.g16_05=[{w:null,t:"通路の壁の結果の画面に、字が上へ上へとのびていく。"},{w:null,t:"「決勝　ダレデモナイ　対　レン」。"},{w:null,t:"通路の向こうから、レンが来る。"},{w:null,t:"すれちがう。"},{w:"dimi",t:"その狐、まだ、お前の言うことを聞かないのか。",v:"16_0099"},{w:"hero",t:"聞くよ。たまにだけどな。",v:"16_0100"},{w:null,t:"レン、何も言わずに歩いていく。"},{w:null,t:"控えのベンチ。"},{w:"elly",t:"フォルン、こっちおいで。クッキーだよ。",v:"16_0103"},{w:null,t:"フォルンの耳が、くるっと左の箱を向く。"},{w:"elly",f:"serious",t:"……耳だけ、来た。",v:"16_0105"},{w:null,t:"ヤマト、フォルンの耳と足を見くらべる。"},{w:null,t:"頭の上で、ぶうん、と低い音。天井がかすかにふるえる。"},{w:null,t:"通路の向こうで、親子の連れた子が、びくっと体をすくめる。"},{w:null,t:"アレクが、天井を見上げる。"}];
GR_SC.g16_06=[{w:null,t:"ガラスの屋根ごしの夕日。"},{w:"x",n:"司会",t:"決勝は大将戦！　一体どうしの、真っ向勝負です！",v:"16_0116"},{w:null,t:"大競技場の場内。"},{w:null,t:"ガラスで囲んだ貴賓席に、ヴィクターと外国の買い手たち。"},{w:null,t:"レンが、足もとにライガを下ろす。"},{w:null,t:"その場で光がはじける（別画面にしない・約3秒）。"},{w:null,t:"場内の大きな空中の画面に「エレグリオ」。"},{w:"x",n:"司会",t:"重ねた子も、一体です！",v:"16_0122"},{w:null,t:"ヤマト、フォルンを走路に下ろす。"},{w:null,t:"ヤマトの左の手首の画面で、時計の形のアイコンが光る。"},{w:"x",n:"司会",t:"決勝、始め！",v:"16_0125"}];
GR_SC.g16_08=[{w:null,t:"フォルレオンが光って、小さなフォルンにもどる。"},{w:null,t:"ヤマトが走路に走りこんで、フォルンの前ですべって止まる。"},{w:null,t:"ヤマト、頭の葉をつまんで取ろうとする。フォルン、首をふってよける。"},{w:null,t:"走路の向こう。"},{w:null,t:"レンが、ライガの横にしゃがんで、背中に手をのせている。"},{w:null,t:"レン、ヤマトの方を見ない。"},{w:null,t:"客席の手すりを乗りこえかけたエリーの上着を、アレクがつかんでいる。"}];
GR_SC.g16_09=[{w:null,t:"いちばん上にヤマト。"},{w:null,t:"係が、フォルンに登録のチップを入れる白い機械を当てる。"},{w:null,t:"係が、ヤマトに金色のふちの登録の札をわたす。"},{w:null,t:"ヤマト、札を見る。"},{w:"hero",f:"serious",t:"……これ、おれ？",v:"16_0196"},{w:"alek",t:"（客席から）お前だよ！　自分で書いたんだろ！",v:"16_0197"},{w:null,t:"客席のいちばん前で、エリーがおなかを抱えて笑っている。"},{w:null,t:"ヤマト、札をパーカーのポケットに大事にしまう。"},{w:null,t:"レンも準優勝の札を受け取る。"},{w:"x",n:"司会",t:"それでは、この大会の協賛、ヴィクターさんより、ひとこと！",v:"16_0201"},{w:null,t:"ヴィクターが、白いスーツのボタンを留めて立つ。"},{w:null,t:"アレクの目が、部下の胸のオレンジの輪で止まる。"},{w:"victor",t:"おめでとう、ダレデモナイくん。きみ、才能あるね。",v:"16_0204"},{w:null,t:"ヴィクターがヤマトに小さく手をふる。"},{w:"victor",t:"では、皆さんお待ちかねの、本日の目玉を。",v:"16_0206"},{w:null,t:"オレンジの輪の指輪の指が、手もとの画面を、とん、とたたく。"}];
GR_SC.g16_10=[{w:null,t:"頭の上で、屋根の裏の白い皿がいっせいに鳴る。"},{w:null,t:"遠く、海がわの港の電波の塔のてっぺんで、赤い明かりが、点きっぱなしになる。"},{w:null,t:"客席のチップの子たちが、いっせいに体をすくめる。"},{w:null,t:"エリーの髪の中から、ピリポンが顔を出して、耳をぴんと立てる。"},{w:null,t:"表彰台の上。"},{w:null,t:"四つとも、いっぺんに、まっ赤に光る。"},{w:null,t:"音が、やむ。"},{w:null,t:"足の下から、低い、長い声が上がってくる。"},{w:null,t:"表彰台が、ことん、と小さくゆれる。"}];
GR_BT[16]={mid:[[{w:"hero",t:"フォルン、行け！",v:"16_0128"},{w:"hero",t:"返せ！",v:"16_0131"},{w:null,t:"レンの目は、ヤマトを見ていない。"},{w:null,t:"ヤマト、走路のはしにしゃがむ。フォルレオンの耳を見る。"},{w:null,t:"ヤマトの目が、一瞬、控えの通路の方へ行く。"},{w:"hero",t:"フォルン、待て。",v:"16_0150"},{w:null,t:"レンの目が、初めて、ヤマトの顔に行く。"},{w:"hero",t:"左だ。木の下まで下がれ。",v:"16_0156"}]],post:[{w:null,t:"エレグリオの羽の模様が、一つずつ消えていく。"},{w:null,t:"静か。オリーブの葉が一枚、フォルレオンの頭の上に落ちる。"},{w:"x",n:"司会",t:"……優勝、ダレデモナイ！",v:"16_0179"},{w:null,t:"客席が、割れるようにわく。"}]};
GR_EP[16]={"t": "白い都の大会", "sc": [["g16_01", "白い都・大通り（朝）", 0], ["g16_02", "大競技場の前（朝）", 0], ["g16_03", "受付の机（朝）", 0], ["g16_04", "大競技場・開会の出し物（昼前）", 0], ["g16_05", "控えの通路（昼〜夕方）", 0], ["g16_06", "決勝（夕方）", 0], ["g16_07", "勝負", 1], ["g16_08", "勝負のあと", 0], ["g16_09", "表彰台（夕方）", 0], ["g16_10", "大競技場（夕方）", 0]]};
GR_SC.g17_01=[{w:null,t:"白い都の大会は、終わったばかりだった。",v:"17_0023"},{w:null,t:"表彰台。ヤマトの首に、優勝のメダル。"},{w:null,t:"足の下から、牛の吠える声。"},{w:null,t:"競技場のまん中の白い線に沿って、地面が割れる。割れ目が、まっすぐ丘の方へ走る。"},{w:null,t:"割れ目の前に、警察のロボットが十体、盾をかまえて、横一つにならぶ。"},{w:"x",n:"警察のロボット",t:"危険区域です。下がってください。",v:"17_0028"},{w:null,t:"割れ目の奥で、赤い光が一つ、点いて、消える。"},{w:null,t:"黒く反ったつのが二本、地面から突き出る。"},{w:null,t:"ならんだロボットが、まとめて宙に浮く。"},{w:null,t:"つのが、割れ目の奥へ引っこむ。"},{w:null,t:"第17話　守り①ミノタス・前編",v:"17_0034"}];
GR_SC.g17_02=[{w:null,t:"割れ目は、客席のいちばん前まで来ている。"},{w:null,t:"その前に、レン。"},{w:null,t:"ライガが、レンの前に出て、毛の雷を逆立てる。"},{w:null,t:"割れ目から、つのが、もう一突き。"},{w:null,t:"レン、走って、ライガの前に立つ。両手を広げる。"},{w:null,t:"つのは、もう出てこない。"},{w:null,t:"ヤマトが走ってくる。"},{w:null,t:"レン、ヤマトを見ない。ライガの首に手を当てている。"},{w:"hero",t:"レン、ライガは？　さっきの、まともに当たってたよな。",v:"17_0048"},{w:"dimi",t:"……息は、ある。お前に心配されるほどじゃない。",v:"17_0049"},{w:null,t:"ヤマト、何か言いかける。"},{w:null,t:"保護局の制服の男が、白い顔で割れ目の前に立つ。"},{w:"x",n:"保護局の職員",t:"近づかないで！　だれも、近づかないでください！",v:"17_0052"},{w:null,t:"職員のうしろで、割れ目のふちが、ぽろぽろと崩れていく。"}];
GR_SC.g17_03=[{w:null,t:"ガラスで囲まれた席。"},{w:null,t:"白いスーツの男、ヴィクター。"},{w:"victor",t:"……受けつけない？　ぼくの言うことを、聞かないって？",v:"17_0058"},{w:null,t:"ヴィクター、画面を伏せる。買い手たちに、にっこり笑う。"},{w:null,t:"競技場の裏。"}];
GR_SC.g17_04=[{w:null,t:"通路の空中の大きな画面に、ニュース。"},{w:"x",n:"ニュースの声",t:"白い都で、地震がありました。市の中心部で、地面が割れています。",v:"17_0064"},{w:null,t:"牛のことは、一言も出ない。"},{w:"alek",t:"地震で、警察のロボットが十体もふっ飛ぶかよ。あれは、どう見たって、下に何かいるだろ。",v:"17_0066"},{w:null,t:"ヤマト、左の手首の画面の、時計の形のアイコンにふれる。"},{w:null,t:"村の丘の印だけ、ほかより大きい。"},{w:null,t:"エリー、肩かけカバンのスマホに手をのばしかけて、止める。"},{w:null,t:"通路のはしに、昼の屋台のおじさん。"},{w:"elly",t:"おじさん！　手首の画面、一回だけ貸してもらえませんか。おばあちゃんが村にいて、ゆれてないか聞きたいんです。",v:"17_0071"},{w:"x",n:"屋台のおじさん",t:"いいとも。焼き台を直してもらったお礼が、串三本じゃ足りないと思ってたんだ。",v:"17_0072"},{w:null,t:"おじさん、手首の画面を外して、エリーにわたす。"},{w:"alek",t:"（エリーに）かけるなら、短くしろよ。場所も言うなよ。",v:"17_0074"},{w:"elly",t:"わかってるって。……おばあちゃん！　ヤマト、優勝したよ！",v:"17_0075"},{w:null,t:"空中に小さな画面。顔は映らない。"},{w:"oba",n:"おばあさん（画面の声）",t:"……うん。中継で、見てたよ。",v:"17_0077"},{w:null,t:"画面の向こうで、食器が、かたかた鳴っている。"},{w:"oba",n:"おばあさん（画面の声）",t:"こっちも、ゆれてる。丘の方から。……エリー、丘の子が起ききったら、村がつぶれる。",v:"17_0079"},{w:"elly",t:"丘の子って、なに？　おばあちゃん、何か知ってるの？",v:"17_0080"},{w:"oba",n:"おばあさん（画面の声）",t:"……ごめん。もう、切るね。",v:"17_0081"},{w:null,t:"画面が消える。"},{w:null,t:"足の下で、また、ずん。"},{w:null,t:"レンが、ライガを抱えて救護のテントへ歩いていく。"},{w:null,t:"ヤマト、メダルを首からはずして、ポケットにつっこむ。"},{w:"hero",t:"アレク。あの丘の下に、入れる所ってある？",v:"17_0086"},{w:"alek",t:"裏に、今は閉めてる見学の入口がある。案内の仕事で、一回だけ客を連れていった。",v:"17_0087"},{w:"elly",t:"村のほうは、どうするの？　おばあちゃん、ゆれてるって言ってたよ。",v:"17_0088"},{w:"hero",t:"村の印は、まだ広がってる途中だろ。足の下のやつは、もう町をこわしてる。先に、こっちだ。",v:"17_0089"}];
GR_SC.g17_05=[{w:null,t:"丘の裏には、見学をやめた古い入口がある。",v:"17_0092"},{w:null,t:"草にうもれた石の門。"},{w:"x",n:"警察のロボット",t:"立ち入り禁止です。",v:"17_0094"},{w:null,t:"ヤマト、胸を張って、ポケットから優勝の札を出す。"},{w:"hero",t:"白い都の大会の、優勝者だぞ。ちょっと通して。",v:"17_0096"},{w:null,t:"ロボットの目が、札を読む。"},{w:"x",n:"警察のロボット",t:"登録者、ダレデモナイ。該当者、なし。",v:"17_0098"},{w:null,t:"ロボットの腕が、ヤマトの胸を、やさしく押しもどす。"},{w:null,t:"エリーが札を拾う。持ち主の欄の「ダレデモナイ」の字を、ヤマトの顔の前に向ける。"},{w:null,t:"ヤマト、しりもちのまま、口をとがらす。"},{w:"alek",t:"だから、そんな名前で通るわけないだろ！　自分で「だれでもない」って書いたんだぞ。",v:"17_0102"},{w:null,t:"アレク、さくの横の草をかき分ける。"},{w:null,t:"ロボットは、正面のさくを見たまま。"},{w:null,t:"くぐり戸の上に、色のあせた札。"}];
GR_SC.g17_06=[{w:null,t:"石の柱が二本。"},{w:"hero",t:"中で迷ったら困るし、地図、出しとくか。",v:"17_0109"},{w:null,t:"ヤマトの手首から、光の地図。階段の一段目をふんだとたん、地図がちらちらゆれて、消える。"},{w:"alek",t:"地下じゃ、電波が届かないんだよ。中で迷っても、地図は助けてくれないぞ。",v:"17_0111"},{w:"elly",t:"じゃあ、ひもがいるね。迷路は、入口からひもを引いていくんだよ。昔のお話でも、そうしてた。",v:"17_0112"},{w:"alek",t:"ひもなんか、だれも持ってきてないだろ。",v:"17_0113"},{w:null,t:"エリー、自分のからし色のマフラーに手をかける。"},{w:null,t:"ヤマト、自分の赤いマフラーをはずす。"},{w:"hero",t:"おれのを使えよ。どうせ、いちばん安いやつだし。",v:"17_0116"},{w:null,t:"エリー、赤いマフラーの端の糸を一本、ぷつりと引く。端を入口の柱に、かたく二回、結ぶ。"},{w:null,t:"エリー、マフラーをヤマトの首に、ふわっともどす。"},{w:"elly",t:"ヤマトが巻いたまま歩いて。そしたら、歩いた分だけ、ほどけていくから。",v:"17_0119"},{w:"hero",t:"巻いたまま？　それ、おれだけ、どんどん寒くなるじゃん。",v:"17_0120"},{w:"elly",t:"そのほうが、なくさないでしょ。",v:"17_0121"},{w:null,t:"ヤマト、階段を下りる。"},{w:null,t:"フォルンのしっぽの火が、明かりになる。"}];
GR_SC.g17_07=[{w:null,t:"天井の低い石の通路。"},{w:null,t:"角を曲がる。"},{w:null,t:"アレク、くつの先で送信機のふたを起こす。"},{w:null,t:"アレク、オレンジの輪を見る。"},{w:"elly",t:"アレク、それ、ヴィクターのマークだよね。",v:"17_0130"},{w:"alek",t:"ああ。あいつら、ここまで掘ってたんだ。……今は、先に行くぞ。",v:"17_0131"},{w:null,t:"ヤマトの首のマフラーが、ひと回り細くなっている。"},{w:null,t:"通路の先の壁に、古い文字が一行。"},{w:null,t:"エリー、指で字を一つずつなぞる。"},{w:null,t:"字の頭の一つが、欠けている。"},{w:"elly",t:"……「……数えて、壁は動く」、だって。前のとこが、欠けてて読めない。",v:"17_0136"},{w:null,t:"通路の奥。遠くで鳴っていた、ひづめの音。"},{w:null,t:"……止まる。"},{w:null,t:"三人、だまる。"},{w:null,t:"しんとした中で、どこかで、ゴトン、と石の音。"},{w:null,t:"……カツン、ドン。"},{w:null,t:"ヤマトが歩き出す。"},{w:null,t:"首から出た毛糸が、閉じた壁のすきまにはさまって、ぴんと張る。"},{w:null,t:"ゴトン。ゴトン。……少しして、壁がまた開く。"},{w:null,t:"アレク、毛糸を拾う。"},{w:null,t:"通路の先が、急に広くなる。"},{w:null,t:"奥の暗がりで、何かが立ち上がる。"},{w:null,t:"大きな茶色い牛。"},{w:null,t:"胸の毛の奥で、四角い物が、赤く点いて、消える。"},{w:null,t:"牛が、ひづめで、床を、ドン、と一回ける。"}];
GR_SC.g17_09=[{w:null,t:"三人、毛糸を手でたぐりながら、早足で通路をもどる。"},{w:null,t:"うしろで、ひづめの音が近づいたり、遠ざかったりする。"},{w:null,t:"角ごとに、毛糸が壁のすきまにはさまっている。"},{w:"alek",t:"引っぱるな！　ちぎれたら、帰り道がなくなるぞ。壁が開くまで待て。",v:"17_0228"},{w:null,t:"三人、壁の前で止まる。"},{w:null,t:"しばらくして、壁が開いて、毛糸が、ぱさりと落ちる。"}];
GR_SC.g17_10=[{w:null,t:"階段を上がる。柱に、毛糸の端が、エリーの結んだまま、かたく巻きついている。"},{w:null,t:"外は夜。丘の下の町の明かりが、ところどころ消えている。"},{w:null,t:"三人、石段に、ばらばらに座りこむ。"},{w:null,t:"フォルン、ヤマトのひざの上で目をつぶっている。"},{w:null,t:"アレク、クロッコの頭に、水の筒から水をたらす。クロッコ、口を少しだけ開ける。"},{w:null,t:"ヤマトの首には、赤いマフラーが、指二本分だけ残っている。"},{w:null,t:"エリー、柱から階段の下まで続く毛糸を、手のひらの上でたぐる。"},{w:null,t:"エリーの指が止まる。"},{w:null,t:"エリー、跡の一つを、ヤマトの前にさし出す。"},{w:null,t:"アレクが、横から毛糸の別の所を取る。"},{w:null,t:"アレクの手が、止まる。"},{w:null,t:"丘の奥から、牛の吠える声。"},{w:null,t:"ヤマト、左の手首の時計のアイコンにふれる。"}];
GR_BT[17]={mid:[[{w:null,t:"ヤマト、フォルンを下ろす。"},{w:"hero",t:"フォルン、前！　焼け！",v:"17_0158"},{w:"hero",t:"効いてる！",v:"17_0160"},{w:"elly",t:"ピリポン、上から！",v:"17_0161"},{w:"alek",t:"クロッコ、横から行け！",v:"17_0164"}],[{w:"hero",t:"平気だろ！　もっと前！",v:"17_0167"},{w:null,t:"エリー、牛の足もとの土を見る。"},{w:"elly",t:"ピリポン、そこにいて。",v:"17_0170"},{w:null,t:"ヤマト、壁のへこみを見る。"},{w:"alek",t:"クロッコ、今だ！",v:"17_0178"},{w:null,t:"アレク、クロコディロスの足もとを見る。"},{w:"hero",t:"フォルン、回れ！　右から！",v:"17_0185"},{w:"alek",t:"下がれ。……下がれ、クロッコ！",v:"17_0189"}]],post:[{w:null,t:"クロコディロスの大きな体が、ずしん、と横に倒れる。"},{w:null,t:"アレク、入口の柱のかげで、こぶしをにぎる。"},{w:null,t:"牛が、奥の柱の方へ向きを変える。"},{w:null,t:"エリー、柱の根もとの石を見る。"},{w:"hero",t:"フォルン、出ろ！　輪の外！",v:"17_0200"},{w:"alek",t:"ヤマト、引くぞ！",v:"17_0209"},{w:"hero",t:"まだ、フォルンは——",v:"17_0210"},{w:"hero",t:"フォルン、こっちだ。おれの所まで下がれ。",v:"17_0214"}]};
GR_EP[17]={"t": "守り①ミノタス・前編", "sc": [["g17_01", "白い都の競技場（表彰のすぐあと）", 0], ["g17_02", "客席の前", 0], ["g17_03", "貴賓席", 0], ["g17_04", "表彰台のうら", 0], ["g17_05", "丘の裏・閉めた入口（夕方）", 0], ["g17_06", "迷宮の入口", 0], ["g17_07", "迷宮", 0], ["g17_08", "勝負", 1], ["g17_09", "帰り道", 0], ["g17_10", "迷宮の入口（夜）", 0]]};
GR_SC.g18_01=[{w:null,t:"17話の続き。"},{w:null,t:"アレク、毛糸を石段の上にまっすぐのばしていく。"},{w:null,t:"毛糸の端は、まだ柱に結んだまま。"},{w:null,t:"階段の下から、ゴトン、と石の音。"},{w:null,t:"エリーが、指を一本折る。"},{w:null,t:"ゴトン。もう一本。"},{w:"hero",t:"そこ、どこにもつながってないじゃん。行き止まり？",v:"18_0039"},{w:"alek",t:"ああ。ここを作った職人が、自分で迷って出られなくなったって話がある。案内の時に、よく話してた。",v:"18_0040"},{w:"hero",t:"自分で作った迷路で迷うって、ばっかでー。",v:"18_0041"},{w:"alek",t:"笑ってる場合かよ！　おれたちも、これからそこに入るんだぞ。",v:"18_0042"},{w:"alek",t:"七つ目に、ここの溝から壁が出る。中にいたら、出られない。",v:"18_0046"},{w:null,t:"第18話　守り①ミノタス・後編",v:"18_0053"}];
GR_SC.g18_02=[{w:null,t:"白い都の人たちは、その夜、家の外ですごした。",v:"18_0059"},{w:null,t:"広場に、銀色のうすい保温シートを敷いた人たち。"},{w:null,t:"空中の大きな画面に、ニュース。"},{w:"x",n:"ニュースの声",t:"政府は、今日の地震を、地下の古い水路のくずれによるものと発表しました。余震に注意してください。",v:"18_0062"},{w:null,t:"羊のぬいぐるみをだいた小さな男の子が、画面を見上げている。"},{w:null,t:"三人、広場のはしを通る。"},{w:null,t:"ヤマト、首に手をやる。"},{w:null,t:"エリー、自分のからし色のマフラーをはずして、ヤマトの首に一周だけ巻く。"},{w:"hero",t:"いいよ、エリーが寒くなるじゃん。",v:"18_0067"},{w:"elly",t:"わたしは、ピリポンがいるからあったかいもん。ヤマトのは、迷宮に置いてきちゃったでしょ。",v:"18_0068"},{w:null,t:"肩のピリポンが、エリーの首にぴたっとくっつく。"}];
GR_SC.g18_03=[{w:null,t:"階段を下りる。"},{w:null,t:"どこかで、ゴトン。"},{w:null,t:"ヤマト、指を折る。口の中で数える。"},{w:"hero",f:"smile",t:"……ご、ろく、なな。よし、今のうちだ。",v:"18_0075"},{w:null,t:"ヤマト、目の前の溝をまたいで、一歩ふみ出す。"},{w:null,t:"壁は、動かない。"},{w:null,t:"ヤマト、胸を張って、もう一歩。"},{w:null,t:"壁が、ごごご、と立ち上がる。"},{w:"alek",t:"お前、数えはじめる所から、まちがえてただろ！　最初の一つを聞いてなかったんだよ。",v:"18_0080"},{w:null,t:"アレク、ヤマトの顔の前に、指を一本立てる。"},{w:null,t:"ヤマト、ひっくり返ったまま、天井を見て、指を折り直す。"},{w:"hero",f:"serious",t:"……いち、に、さん、し、ご、ろく……",v:"18_0083"},{w:null,t:"ゴトン。壁が、また開く。"}];
GR_SC.g18_04=[{w:null,t:"天井の高い四角い広間。"},{w:null,t:"奥の暗がりで、牛が柱にもたれて、すわっている。"},{w:null,t:"肩と首の葉の毛は、焦げて黒いまま。"},{w:null,t:"牛が、三人を見る。"},{w:null,t:"エリー、牛の目を見る。それから、胸の赤い光。"},{w:null,t:"牛が、ひづめで、ドン、と一回ける。"}];
GR_SC.g18_08=[{w:null,t:"静か。天井から、小石が一つ、ころん、と落ちる。"},{w:null,t:"牛の鼻から、白い息。"},{w:null,t:"ヤマト、牛の方へ、一歩、二歩。"},{w:null,t:"牛の鼻が、ぶふううっと鳴る。息が、まともにヤマトの顔に。"},{w:null,t:"牛が、ひづめで土をかく。"},{w:null,t:"エリーが、足もとのピリポンをだき上げて、ヤマトのひざの上に、そっと下ろす。"},{w:null,t:"エリー、一人で、牛の方へ歩いていく。"},{w:"alek",t:"おい、エリー！　一人で行くなって！",v:"18_0177"},{w:null,t:"エリー、ふり向かずに、片手だけうしろに上げる。"},{w:null,t:"牛の前で、エリーが止まる。牛の鼻と、エリーの顔が、同じ高さ。"},{w:null,t:"エリーの口から、短い言葉。"},{w:null,t:"牛の耳が、ぴくっと動く。"},{w:null,t:"エリーが、もう一言。"},{w:null,t:"牛が、ゆっくり頭を下げる。"},{w:null,t:"エリー、手のひらを牛の鼻の前に出す。"},{w:null,t:"エリー、割れたチップを拾う。"},{w:"hero",t:"今の、なんて言ったの？　おれにも教えてよ。",v:"18_0186"},{w:"elly",t:"ないしょ。牛さんと、二人だけのお話だもん。",v:"18_0187"},{w:null,t:"ヤマト、口を開けたまま、アレクを見る。"},{w:null,t:"フォルンが、ヤマトのひざから下りて、牛の前まで歩いていく。"},{w:null,t:"エリーが、からし色のマフラーを拾って、ヤマトの首に、ぐるぐる巻く。"}];
GR_SC.g18_09=[{w:null,t:"三人、毛糸をたぐりながら、階段を上がる。"},{w:null,t:"うしろの暗がりに、牛が立っている。"},{w:null,t:"エリーが、階段の上から、古い言葉で一言。"},{w:null,t:"牛が、ひづめで床を、こつん、と軽く鳴らす。"},{w:null,t:"アレク、くぐり戸の非常ハンドルを回して、戸を閉める。"},{w:null,t:"外は、明け方。"},{w:null,t:"広場で、保温シートをたたむ人たち。"},{w:null,t:"ヤマト、左の手首の時計のアイコンにふれる。"},{w:null,t:"ほかの三つは、赤いまま。"},{w:null,t:"広場の空中の大きな画面。"},{w:"x",n:"ニュースの声",t:"続いて、運河の町コリンタです。きのうの夕方から、町の上空に雷雲がとどまり、落雷が続いています。運河の橋は、すべて沈められ——",v:"18_0203"},{w:null,t:"画面に、コリンタの空。"},{w:"elly",t:"コリンタって、ユスフの船が帰る町だよね。",v:"18_0205"},{w:null,t:"アレク、ポケットのチップを、指でさわる。"},{w:null,t:"ヤマト、からし色のマフラーと赤い結び目を巻き直して、港の方の道を見る。"}];
GR_BT[18]={mid:[[{w:null,t:"アレク、入口の柱のかげで、ゴトン、に合わせて、指を折りはじめる。"},{w:"elly",t:"ピリポン、顔に！",v:"18_0104"},{w:null,t:"ヤマト、じっとしていられない。"},{w:"hero",f:"serious",t:"……フォルン、ちょっとだけ前に出ろ。",v:"18_0109"},{w:null,t:"アレクの指が、止まる。"},{w:"elly",t:"ピリポン、光って！",v:"18_0113"},{w:null,t:"ヤマト、自分の口を、手でおさえる。"},{w:null,t:"ヤマト、フォルレオンに、手のひらを下に向けて、すっと下げる。"},{w:"alek",t:"……六。",v:"18_0120"},{w:"alek",t:"七。",v:"18_0126"}],[{w:"hero",t:"フォルン、今だ！",v:"18_0131"},{w:"alek",t:"クロッコ、すきまから撃て！",v:"18_0133"},{w:null,t:"エリーは、何も言わない。"}],[{w:null,t:"アレクの指が、六本。"},{w:"hero",t:"フォルン、前へ一歩だけ出ろ。",v:"18_0155"},{w:"alek",t:"クロッコ、そのままでいい。",v:"18_0157"}]],post:[{w:null,t:"牛が、両方のひざを土につく。"},{w:null,t:"牛の胸の毛の奥で、ぱきん、と音。"},{w:"alek",t:"……七。",v:"18_0163"},{w:null,t:"ごごご。うしろの壁が、下がりきる。四角の口が開く。"}]};
GR_EP[18]={"t": "守り①ミノタス・後編", "sc": [["g18_01", "迷宮の入口（夜）", 0], ["g18_02", "丘の下の広場（夜）", 0], ["g18_03", "迷宮", 0], ["g18_04", "迷宮の広間", 0], ["g18_05", "勝負・柱の四角", 1], ["g18_06", "勝負・左右から", 1], ["g18_07", "勝負・決め手", 1], ["g18_08", "勝負のあと", 0], ["g18_09", "迷宮の入口（明け方）", 0]]};
GR_SC.g19_01=[{w:null,t:"運河の町の空に、雷雲が居すわった。",v:"19_0023"},{w:null,t:"運河の両岸の、高い岩のかべ。"},{w:null,t:"雲の中を、羽のある白い影が、ぐるりと回る。"},{w:null,t:"どおん。雷が、橋のたもとの鉄の柱に落ちる。"},{w:null,t:"橋のたもとの制御室。ミハリス、レバーに手をかけたまま、窓の下を見ている。"},{w:null,t:"ミハリス、レバーを引く。"},{w:null,t:"雷が、橋の沈んだあとの水面に落ちる。"},{w:null,t:"雲の中の白い影が、町の上の高い丘へ、すうっともどっていく。"},{w:null,t:"制御室の小さな画面。"},{w:"x",n:"ニュースの声",t:"コリンタでは、落雷が続いています。市は、屋内にとどまるよう呼びかけています。",v:"19_0032"},{w:null,t:"ミハリス、画面を消す。"},{w:null,t:"第19話　守り②ペガライ・前編",v:"19_0035"}];
GR_SC.g19_02=[{w:null,t:"港の待合の空中の画面に、「コリンタで落雷つづく」。"},{w:null,t:"港のはし、埋め立て地の電波の塔。"},{w:null,t:"アレク、塔を一度だけ見る。"},{w:null,t:"甲板で、ユスフが洗濯物を取りこんでいる。顔を上げる。"},{w:"yusuf",t:"エリー！　ヤマトも、アレクも！",v:"19_0045"},{w:null,t:"エリー、両手をふり返して、かけていく。"},{w:"yusuf",t:"大会、見たよ。船のみんなで。画面が一個しかないから、取り合いだった。",v:"19_0047"},{w:"elly",t:"ヤマト、優勝したんだよ。すごいでしょ。",v:"19_0048"},{w:"yusuf",t:"だから、見たって。取り合いしながら、ちゃんと最後まで見てたよ。",v:"19_0049"},{w:null,t:"ヤマト、胸を張る。"},{w:null,t:"ユスフの父さんが、操舵室の窓から顔を出す。"},{w:"x",n:"ユスフの父さん",t:"白い都で荷を積んでた。コリンタへ帰るとこだ。橋が全部沈めてあるから、今なら運河を通れる。……乗っていくか。",v:"19_0052"},{w:"alek",t:"いいんですか。コリンタは今、雷が落ちてるって、ニュースで言ってましたけど。",v:"19_0053"},{w:"x",n:"ユスフの父さん",t:"うちは、あの町の岸に住んでるんだ。雷が落ちてても、帰るしかない。",v:"19_0054"}];
GR_SC.g19_03=[{w:null,t:"船が、港を出る。遠くに、運河の入口の、細い岩の切れ目。"},{w:null,t:"操舵室。計器の画面がいくつも並んでいるが、半分は消えている。"},{w:null,t:"ヤマト、その丸いハンドルを、じっと見ている。"},{w:"hero",t:"おじさん。それ、ちょっとだけ、さわらせてくれない？",v:"19_0061"},{w:"x",n:"ユスフの父さん",t:"だめだ。自動の舵がこわれてるから、手で回してるんだ。遊びじゃない。",v:"19_0062"},{w:"hero",t:"まっすぐ持ってるだけでいいから。ほんとに、ちょっとだけ。",v:"19_0063"},{w:null,t:"父さん、前を見たまま、首をふる。"},{w:"yusuf",t:"父さん、ぼくも前に、海の広い所でやらせてもらったよ。",v:"19_0065"},{w:"x",n:"ユスフの父さん",t:"……ちょっとだけな。まっすぐ持ってろ。",v:"19_0066"},{w:null,t:"ヤマト、両手でハンドルをにぎる。"},{w:null,t:"窓の外の甲板で、ユスフが見ている。ヤマト、片手をハンドルからはなして、ひらひらふる。"},{w:"hero",t:"見ろ、片手！",v:"19_0069"},{w:null,t:"ハンドルが、からからと回る。"},{w:null,t:"がりがりがり。船の横腹が、入口の岩をこする。"},{w:null,t:"父さんの太い腕が、横からハンドルをつかんで、ぐいっともどす。"},{w:"x",n:"ユスフの父さん",t:"つけた傷は、つけたやつが自分の手で消す。それが、この船の決まりだ。",v:"19_0074"},{w:"hero",f:"smile",t:"手伝わなくていいよ。おれがやったんだし。",v:"19_0077"},{w:"alek",t:"お前ひとりにやらせたら、コリンタに着いても終わらないだろ。メダル、ぶらぶらさせてるひまがあったら、手を動かせよ。",v:"19_0078"}];
GR_SC.g19_04=[{w:null,t:"運河は、岩の山をまっすぐ切ってつくった水の道だ。",v:"19_0082"},{w:null,t:"両側に、そそり立つ岩のかべ。"},{w:null,t:"沈んだ橋の上を、船がゆっくり通る。"},{w:null,t:"運河を出ると、町。"},{w:null,t:"町の上の高い丘。"},{w:"yusuf",t:"あそこのいちばん上に、泉があるんだよ。昔、羽のある馬が——",v:"19_0087"},{w:"hero",t:"ひづめで地面をけって掘った、だろ。前に、ユスフから聞いた。",v:"19_0088"},{w:"yusuf",t:"……覚えてたんだ。ヤマト、ぜんぜん聞いてない顔してたのに。",v:"19_0089"},{w:null,t:"どおん。とりでのてっぺんに、雷。"},{w:null,t:"ユスフ、手すりをにぎったまま、だまる。"},{w:null,t:"ヤマト、左の手首の時計のアイコンにふれる。"},{w:null,t:"船が、岸に横づけする。"},{w:"yusuf",t:"船、ここで待ってるから。帰ってきたら、すぐ出られるようにしとく。",v:"19_0094"},{w:null,t:"ユスフの父さんが、操舵室から、だまって親指を立てる。"}];
GR_SC.g19_05=[{w:null,t:"乾いた岩の丘。"},{w:null,t:"三つ目の門の下に、保護局の無人の車が一台、止まっている。"},{w:"x",n:"保護局の職員",t:"……君たち、上はだめだ。雷が落ちてるから。",v:"19_0100"},{w:"alek",t:"雷、ですか。あれは、ふつうの雷じゃないと思います。雲の中で、何か回ってましたよね。",v:"19_0101"},{w:"x",n:"保護局の職員",t:"雷だよ。発表で、そう言ってるんだ。",v:"19_0102"},{w:null,t:"職員の手は、ひざの上でにぎったまま。"},{w:null,t:"三人、車の横を通りすぎる。"}];
GR_SC.g19_06=[{w:null,t:"広い中庭。草の中に、古い柱が、ところどころ立っている。"},{w:null,t:"中庭の左に、石でふちどった四角い泉。"},{w:null,t:"水面が、ぶるっとふるえる。"},{w:null,t:"白い天馬。たてがみの中で、小さな稲妻がちかちか光る。"},{w:null,t:"天馬が、泉の上で、ひづめを一つ空にける。"},{w:null,t:"天馬が、塔の上の石にとまる。"},{w:null,t:"ヤマト、首を上に向ける。"},{w:null,t:"天馬の目が、ヤマトの方へ動く。"},{w:null,t:"ヤマトが止まる。口を開けたまま。"},{w:"elly",t:"ヤマト？　ねえ、ヤマトってば！",v:"19_0116"},{w:null,t:"ヤマト、まばたきもしない。肩のフォルンが、耳をぺろりとなめる。"},{w:null,t:"アレク、塔の方を見ないように、うつむいたまま、ヤマトの足首をつかむ。"},{w:null,t:"柱のかげ。少しして、ヤマトの指がぴくっと動く。"},{w:null,t:"ヤマト、柱のかげから首を出して、上を見ようとする。"},{w:null,t:"アレクの手のひらが、横から、ヤマトの目の上に、ばふっとかぶさる。"},{w:"alek",t:"見るなって！　目が合ったら、また止まるぞ。",v:"19_0122"},{w:"hero",f:"serious",t:"……おれ、もしかして止まってた？",v:"19_0123"},{w:"elly",f:"sad",t:"うん。片足、上げたまんまで。ちょっと、かっこ悪かったよ。",v:"19_0124"},{w:null,t:"ヤマト、手のひらの下で、口をへの字にする。"},{w:null,t:"塔の上で、天馬が、ひづめで石を、かつん、とたたく。"}];
GR_SC.g19_10=[{w:null,t:"三人とも、城壁のかげにひざをつく。息が上がっている。"},{w:null,t:"アレク、すきまから泉の水をすくって、クロッコの頭にかける。クロッコ、うっすら目を開ける。"},{w:null,t:"エリー、髪の中のピリポンの背中を指でなでる。"},{w:null,t:"ヤマトのうでの中で、フォルンが片目を開けて、シャツからはみ出たメダルのひもを前足でちょいとはじく。"},{w:null,t:"ヤマト、石のすきまから、泉の水面を見下ろす。"},{w:null,t:"水面に、黒い雲。"},{w:null,t:"ヤマト、びくっと肩を上げる。"},{w:null,t:"……指が、動く。"},{w:null,t:"水面の中で、天馬の目がこっちを向いている。"},{w:null,t:"ヤマト、動ける。首をかしげる。"},{w:null,t:"アレク、ヤマトの横顔を見る。"},{w:null,t:"エリー、二人の顔を見くらべる。"},{w:null,t:"ヤマト、水面から目をそらさないまま、フォルンを胸にかかえ直す。"},{w:null,t:"アレクの手が、ヤマトのパーカーのすそを、うしろから、ぐっとつかむ。"},{w:null,t:"ヤマトの目は、水面からはなれない。"}];
GR_BT[19]={mid:[[{w:null,t:"ヤマト、フォルンを下ろす。"},{w:"hero",t:"みんな、顔は見るな。……見るなよ。",v:"19_0135"},{w:"hero",t:"フォルン、前！",v:"19_0136"},{w:"alek",t:"クロッコ、泉へ行け！",v:"19_0140"},{w:"elly",t:"ピリポン、柱の石から！",v:"19_0143"},{w:null,t:"ヤマトのこぶしが、にぎったまま止まる。"}],[{w:null,t:"エリーの手が、肩かけカバンのひもを、ぎゅっとにぎる。"},{w:"hero",t:"フォルン、下向いたまま撃て！",v:"19_0159"},{w:"alek",t:"クロッコ、下を見たまま——",v:"19_0162"},{w:null,t:"ヤマト、天馬の体を見ている。口が、少し開いたまま。"}],[{w:null,t:"アレク、柱のかげで、灰色のクロコディロスを見ている。こぶしをにぎる。"},{w:null,t:"ヤマト、フォルレオンを見る。"},{w:"hero",t:"フォルン、こっちだ。輪の外まで下がれ。",v:"19_0178"},{w:"elly",t:"ピリポン、おいで。こっちまで下がって。",v:"19_0181"}]],post:[{w:null,t:"アレク、輪のふちを回って、泉のふちのクロコディロスに手をのばす。"},{w:null,t:"アレク、手をはなさないまま、くちびるをかむ。"},{w:null,t:"どおおん。赤い輪に、空から太い雷。"}]};
GR_EP[19]={"t": "守り②ペガライ・前編", "sc": [["g19_01", "運河の町コリンタ（きのうの夕方）", 0], ["g19_02", "白い都の港（朝）", 0], ["g19_03", "貨物船・操舵室（昼）", 0], ["g19_04", "運河（午後）", 0], ["g19_05", "とりでの坂道（夕方近く）", 0], ["g19_06", "とりでの上の中庭", 0], ["g19_07", "勝負・一度目", 1], ["g19_08", "勝負・二度目", 1], ["g19_09", "勝負・引く", 1], ["g19_10", "泉の裏・くずれた城壁のかげ（夕方）", 0]]};
GR_SC.g20_01=[{w:null,t:"コリンタの運河。きのうの夜、三人は、とりでを下りて船にもどった。",v:"20_0022"},{w:null,t:"岸に横づけした古い貨物船。"},{w:null,t:"エリーのシートのはしから、ピリポンのしっぽだけが出ている。"},{w:null,t:"船のへりで、ヤマトが、ロープのついたバケツを運河に下ろしている。"},{w:null,t:"ヤマト、バケツを胸の前に持って、水面をのぞく。"},{w:null,t:"ヤマト、水面から目をはなさずに、甲板を歩きだす。"},{w:null,t:"ヤマトの口のはしが、上がる。"},{w:null,t:"マストの柱に、おでこから当たる。バケツの水が、顔と胸に、ざばっとかかる。"},{w:null,t:"アレク、シートをはねのけて起き上がる。"},{w:"alek",t:"朝から何やってんだよ！　ごんって、船じゅうに響いたぞ！",v:"20_0032"},{w:"hero",t:"今のはマストが悪いんだって。あんな所に立ってるからだよ。",v:"20_0033"},{w:"alek",t:"マストは、船ができた時からずっとそこにあるって！",v:"20_0034"},{w:null,t:"ヤマト、ぬれた前髪のまま、またバケツを運河に下ろす。"},{w:"yusuf",t:"バケツなんか持って歩いて、何してんの？　水まき？",v:"20_0037"},{w:"hero",t:"水面だけ見て歩く練習。あの天馬、顔を見たら固まるからさ。",v:"20_0038"},{w:"yusuf",t:"それで、おでこが赤いんだ。",v:"20_0039"},{w:"hero",f:"serious",t:"……一回目は、しかたないだろ。",v:"20_0040"},{w:null,t:"第20話　守り②ペガライ・後編",v:"20_0049"}];
GR_SC.g20_02=[{w:null,t:"甲板のまん中に、ユスフが持ってきたパンとオリーブのびん（ふたに日付が光る）。"},{w:null,t:"フォルン、オリーブを一つくわえて、しっぽの火の上でころがす。"},{w:null,t:"ピリポンは、エリーの肩の上で、パンのはしを両手で持ってかじっている。"},{w:null,t:"アレク、フォルンの吐いた焦げた種をつまむ。"},{w:"alek",t:"きのうの夜、おれが引っぱらなかったら、お前、泉に落ちてたぞ。",v:"20_0059"},{w:"hero",t:"落ちてないって。ちょっと身を乗り出しただけだよ。",v:"20_0060"},{w:"alek",t:"片足、もう泉の上に出てただろ！",v:"20_0061"},{w:"hero",t:"出てたけど、落ちてはないじゃん。",v:"20_0062"},{w:null,t:"ヤマト、甲板の泉の絵を、指でとん、とたたく。"},{w:"hero",t:"ここでやろう。水に映ったあいつなら、目が合っても平気だった。",v:"20_0064"},{w:null,t:"アレク、ヤマトの赤いおでこを見る。それから、泉と塔のあいだを、種でなぞる。"},{w:"alek",t:"あいつは、塔の石の上で治るだろ。泉からじゃ、塔まで届かない。",v:"20_0066"},{w:null,t:"ヤマト、パンをかじりながら、甲板の塔をにらむ。"},{w:"hero",t:"撃てば、下りてくるって。きのうも、そうだったじゃん。",v:"20_0068"},{w:"alek",t:"下りてきたのは、ピリポンの顔をのぞきこむ時だけだ。",v:"20_0069"},{w:"hero",t:"水だけ見てれば、のぞかれたって平気だろ。",v:"20_0070"},{w:null,t:"アレク、返事をしない。"},{w:"alek",t:"下りてきたら、そこは草の上だ。石じゃないから、治らない。",v:"20_0072"},{w:null,t:"甲板のむこうで、とりでの雲から雷が一つ落ちる。"},{w:null,t:"ユスフが、パンを半分にちぎって、ヤマトにわたす。"},{w:"yusuf",t:"顔を見ないで、どうやって戦うの？　目、つぶるの？",v:"20_0075"},{w:"hero",t:"下を見るんだよ。泉の水に、ちゃんと映るから。",v:"20_0076"},{w:null,t:"ユスフ、操舵室の父さんの方を見る。"},{w:"x",n:"ユスフの父さん",t:"昼には船を出す。そのころまだ雲が残ってたら、待たずに行くぞ。",v:"20_0078"},{w:"alek",t:"わかりました。昼までに、片をつけてもどります。",v:"20_0079"},{w:null,t:"ヤマト、パンを口いっぱいにつめこんで、立ち上がる。"}];
GR_SC.g20_03=[{w:null,t:"三つ目の門の下。"},{w:null,t:"中庭。草の上に、きのうの雷の焦げあとが、点々と黒い。"},{w:null,t:"奥の塔の上に、白い天馬。羽をたたんで、首を下げている。"},{w:null,t:"三人、うつむいたまま、中庭のはしを、泉の方へ歩く。"},{w:null,t:"泉のふちの石。"},{w:null,t:"エリー、浮き彫りの前にしゃがむ。"},{w:"elly",t:"見て。この人も、盾に映った顔のほうを見てるよ。",v:"20_0089"},{w:null,t:"ヤマト、浮き彫りの盾を見る。"},{w:null,t:"ヤマト、何も言わずに、塔に背を向けて、泉のふちにすわる。"},{w:null,t:"アレクも、塔に背を向けて、となりにすわる。"},{w:null,t:"三人の顔が、水面に並んで映る。"},{w:null,t:"水面の中で、天馬が首を上げる。"}];
GR_SC.g20_07=[{w:null,t:"獣の闘気が引いて、光がほどけて、小さなフォルンと、小さなクロッコ。"},{w:null,t:"フォルン、起き上がる。"},{w:null,t:"フォルン、前足で鼻をごしごしこすって、クロッコから一歩はなれてすわる。クロッコは、知らん顔で、泉に頭をつっこんで水を飲む。"},{w:null,t:"アレク、クロッコの頭を、指で一回、こつんとたたく。それから、自分の手を、しばらく見ている。"},{w:null,t:"天馬が、前足を折ったまま、首を上げる。"},{w:null,t:"水面に映った天馬の目には、もう、光がない。"},{w:null,t:"エリー、天馬のそばへ行く。"},{w:null,t:"エリーの口から、短い言葉。"},{w:null,t:"天馬が、水を飲むのをやめる。耳が、エリーの方を向く。"},{w:null,t:"エリーが、もう一言。"},{w:null,t:"天馬が、ゆっくり、前のひざを折る。"},{w:null,t:"エリー、天馬の首の毛に、手をのせる。"},{w:null,t:"アレク、草の上の割れたチップを拾う。"},{w:null,t:"ヤマト、浮き彫りの盾の男を、もう一度見る。それから、ひざを折った天馬の背中を見る。"},{w:"hero",t:"なあ、エリー。この天馬って、背中に乗れんの？",v:"20_0200"},{w:"elly",t:"聞いてみるね。",v:"20_0201"},{w:null,t:"エリー、天馬の首をなでて、古い言葉で一言。"},{w:null,t:"天馬が、羽を一回、ばさっと広げる。"},{w:"elly",t:"いいって。……おでこ、まだ赤いね。",v:"20_0204"},{w:"hero",t:"それは、言わなくていいって。",v:"20_0205"}];
GR_SC.g20_08=[{w:null,t:"天馬の背に、三人。"},{w:null,t:"天馬が、泉のふちから草をけって浮く。"},{w:null,t:"とりでが、下へ遠ざかる。"},{w:null,t:"ヤマト、片手を上げかけて、すぐに首の毛をつかみ直す。"},{w:null,t:"海と山と、オリーブの畑が、ずっと先まで見える。"},{w:null,t:"ヤマト、左の手首の画面にふれる。"},{w:null,t:"村の丘の印が、きのうより、また大きい。"},{w:null,t:"エリー、肩ごしに地図を見る。"},{w:null,t:"村の競技場の赤い印が、どくん、と一度強く光る。天馬の耳が、ぴくっとそちらを向く。"},{w:null,t:"天馬が、羽の向きを変える。"}];
GR_BT[20]={mid:[[{w:"alek",t:"クロッコ、水だけ見てろ！",v:"20_0106"},{w:null,t:"ヤマトの口のはしが、上がる。"},{w:"hero",t:"ほら、水に映して見れば、止まらないだろ！",v:"20_0111"},{w:"hero",t:"フォルン、撃て！",v:"20_0112"},{w:"hero",t:"いけるいける！　撃て撃て、どんどん撃て！",v:"20_0115"},{w:null,t:"アレク、ヤマトの横顔を見る。"}],[{w:null,t:"アレク、くちびるをかむ。"},{w:"hero",t:"フォルン、今のうちに撃て！",v:"20_0126"},{w:"hero",t:"クロッコ、撃て！　今なら撃てるって！",v:"20_0132"},{w:null,t:"アレク、一瞬ヤマトを見る。それから、つられたように前へ出る。"},{w:"alek",t:"クロッコ、撃て！",v:"20_0134"},{w:null,t:"ヤマトの口が、「撃て」の形のまま止まる。"},{w:null,t:"ヤマトの目が、湯気に止まる。"},{w:null,t:"ヤマト、口を閉じる。"},{w:null,t:"エリーが、ヤマトの横顔を見る。"},{w:"hero",t:"フォルン、クロッコのとなりへ行け。",v:"20_0150"},{w:"alek",t:"クロッコ、そこから動くなよ。",v:"20_0152"},{w:"alek",t:"……おい、ヤマト。今の、なんだ。",v:"20_0159"}],[{w:"hero",t:"そのまま、水を見てろ！",v:"20_0168"},{w:null,t:"エリーの手が、自分の肩かけカバンのひもを、ぎゅっとつかむ。"},{w:"elly",t:"ピリポン、今！",v:"20_0177"}]],post:[{w:null,t:"胸の毛の奥で、ぱきん。"},{w:null,t:"とりでの上の黒い雲が、まん中から、すうっと晴れていく。"}]};
GR_EP[20]={"t": "守り②ペガライ・後編", "sc": [["g20_01", "貨物船の甲板（明け方）", 0], ["g20_02", "貨物船・甲板（朝）", 0], ["g20_03", "とりでの上の中庭", 0], ["g20_04", "勝負・はじめ", 1], ["g20_05", "勝負・なか", 1], ["g20_06", "勝負・おわり", 1], ["g20_07", "勝負のあと", 0], ["g20_08", "とりでの上・空（朝）", 0]]};
GR_SC.g21_01=[{w:null,t:"コリンタからオリーヴァ村まで、歩けば四日。天馬は、昼までに飛ぶ。",v:"21_0022"},{w:null,t:"雲の下。白い羽が、ゆっくり上下する。"},{w:null,t:"下に、見なれた丘。"},{w:null,t:"ヤマト、エリーの肩につかまったまま、立ち上がる。"},{w:"hero",t:"見ろよ、村だ！　天馬で帰ってきたのなんて、おれが初めてだぞ！",v:"21_0026"},{w:"alek",t:"立つなって！　落ちたら、だれが拾いに行くと思ってんだよ！",v:"21_0027"},{w:"hero",t:"村のみんなに、手ぐらいふっとかないと。おーい！",v:"21_0028"},{w:null,t:"ヤマト、両手を大きくふる。"},{w:null,t:"天馬が、左へ、ゆるく曲がる。"},{w:null,t:"ヤマト、背中の上を、ずるずるすべっていく。"},{w:null,t:"エリー、ふり返って、ふき出す。"},{w:"alek",t:"だから言っただろ！　もう、そこから一歩も動くなよ！",v:"21_0034"},{w:"hero",t:"あ、ホテルだ！　アナの所の屋根！",v:"21_0036"},{w:null,t:"第21話　守り③ゴッドヘラク",v:"21_0044"}];
GR_SC.g21_02=[{w:null,t:"広場に、村の人たち。"},{w:null,t:"画面の字。「ギリシャ政府　村の古い競技場の地下で、ガス設備の事故がありました。"},{w:"x",n:"村のおじいさん",t:"あそこは、二千年前の運動場だよ。ガスなんか、通ってるもんか。",v:"21_0052"},{w:null,t:"だれも答えない。"},{w:null,t:"ずん。地面が、下から一回ゆれる。"},{w:null,t:"競技場の方から、何かが飛んでくる。"},{w:null,t:"村の人たちが、いっせいに家の中へ走る。"},{w:null,t:"ホテルの戸が開いて、アナが出てくる。"},{w:null,t:"ぶどう畑の方から、三人が歩いてくる。"},{w:null,t:"アナの足が止まる。"},{w:null,t:"天馬が、アナの前で首を下げる。"},{w:"elly",t:"お姉ちゃん、ただいま。屋根の穴、どうしたの？",v:"21_0061"},{w:"ana",t:"競技場からドローンが飛んできたの。あそこに、何かいるのよ。",v:"21_0062"},{w:"alek",t:"ぼくたちが見てきます。アナさんは、ホテルの中にいてください。",v:"21_0063"},{w:null,t:"アナ、髪を押さえたまま、エリーの顔を見る。"},{w:null,t:"ずん。また、ゆれる。"}];
GR_SC.g21_03=[{w:null,t:"土手にかこまれた、長い土の走路。"},{w:null,t:"入口の石のアーチの前に、黄色く光る立ち入り禁止の線（空中に浮かぶ光の帯）。"},{w:"x",n:"保護局の職員",t:"……はい。ドローンは、六台目です。",v:"21_0070"},{w:"x",n:"保護局の職員",t:"ロボットは、腕が一本、村まで。……いえ、近づけません。",v:"21_0071"},{w:null,t:"職員、三人に気づいて、片手を広げる。"},{w:"x",n:"保護局の職員",t:"だめ。ここから先は、入っちゃだめ。",v:"21_0073"},{w:null,t:"アーチの向こう、走路のまん中。"},{w:null,t:"金色のよろい。"},{w:null,t:"アーチのわきの石の扉。"},{w:null,t:"エリー、浮き彫りの角と、走路の王のつのを見くらべる。"},{w:null,t:"エリーの右手の指が、左手の人さし指にふれる。"},{w:null,t:"入口の柱に、観光の案内の空中の札。"},{w:"hero",t:"なんだ、でっかいカブトムシじゃん。",v:"21_0081"},{w:"elly",t:"だから、ヘラクレスは人だってば。何回言わせるの。",v:"21_0082"},{w:"x",n:"保護局の職員",t:"……七台目、です。",v:"21_0085"},{w:"x",n:"警察のロボット",t:"危険区域です。立ち止まってください。",v:"21_0087"},{w:"x",n:"保護局の職員",t:"ちょっと、きみ——",v:"21_0092"},{w:"alek",t:"すみません。ぼくたちのテリオンなら、止められるかもしれません。",v:"21_0094"}];
GR_SC.g21_07=[{w:null,t:"獣の光がほどけて、フォルンとクロッコが、並んで土の上にへたりこむ。柱の根もとで、ナルカミの光もほどけて、ピリポンが目を回している。"},{w:null,t:"ヤマト、フォルンの横にしゃがむ。フォルン、ヤマトの顔を見ないで、あくびをする。"},{w:null,t:"アレク、クロッコの頭を、指で一回、こつんとたたく。"},{w:null,t:"エリー、ピリポンをだき上げる。ピリポン、目を回したまま、エリーの肩にしがみつく。"},{w:null,t:"王は、両ひざをついたまま、肩で息をしている。"},{w:null,t:"ヤマトが、王の方へ一歩出かける。"},{w:null,t:"エリーが、ピリポンを肩にのせたまま、一人で、王の方へ歩いていく。"},{w:null,t:"王の顔は、エリーの体より大きい。"},{w:null,t:"エリーが、古代のギリシャ語で、短く話しかける。"},{w:null,t:"王の鼻息が、止まる。"},{w:null,t:"王が、エリーの顔を見る。"},{w:null,t:"王が立ち上がる。"},{w:null,t:"走路のはしで止まって、土手の向こうの、村の丘の方を向く。"},{w:null,t:"エリーも、王のとなりまで歩いていって、同じ方を見る。"},{w:null,t:"ヤマトの左の手首の画面が、ふるえる。"},{w:null,t:"アレク、土の上の割れたチップを拾う。"},{w:null,t:"アーチの外で、保護局の職員が、手首の画面に何か言いかけて、やめる。"}];
GR_SC.g21_08=[{w:null,t:"村のうしろの、オリーブ畑の丘。"},{w:null,t:"ため池の水面が、こまかくふるえている。"},{w:null,t:"オリーブの葉が、いっせいに、ざあっと鳴る。"},{w:null,t:"くずれた丸屋根の下の地面が、まん中から割れる。"},{w:null,t:"割れ目から、石の手が出る。"},{w:null,t:"石の指が、ゆっくり、地面をつかむ。"},{w:null,t:"競技場の走路のはしで、王が、低く鳴く。"},{w:null,t:"丘のふもとの道。"}];
GR_BT[21]={mid:[[{w:null,t:"ヤマトが、アレクを見る。"},{w:"hero",t:"止まったぞ！　今のうちに、みんなで撃て！",v:"21_0117"}],[{w:null,t:"アレクが、走路のはしで、足もとの土に目を落とす。"},{w:null,t:"エリーが、ふんばった前足を見る。こぶしを一度にぎって、まっすぐ横を指さす。"},{w:"elly",t:"横！",v:"21_0137"},{w:null,t:"ヤマト、聞き返さない。"},{w:"hero",t:"フォルン、横へ跳べ！",v:"21_0139"},{w:null,t:"エリーの指が、今度は、左のアーチの柱をさす。"},{w:"elly",t:"ピリポン、柱のかげへ！",v:"21_0145"},{w:"hero",t:"フォルン、下がれ！",v:"21_0148"},{w:null,t:"アレク、クロコディロスの足もとを見る。"},{w:"alek",t:"クロッコ、前足にかみつけ！",v:"21_0151"},{w:"elly",t:"ピリポン、そこから撃って！",v:"21_0155"},{w:null,t:"ヤマトは、走路の土を見ている。"}],[{w:"hero",t:"アレク、あのすみだ。あそこだけ、草が焼けてない。",v:"21_0168"},{w:null,t:"ヤマトの指が、王の通り道から少しはずれた、草の青いすみをさす。"},{w:null,t:"アレク、ヤマトを見ないで、うなずく。"},{w:"alek",t:"クロッコ、あのすみへ行け！",v:"21_0171"},{w:"hero",t:"フォルン、クロッコのとなりへ行け。",v:"21_0173"}],[{w:"hero",t:"エリー、ピリポンがねらわれてるぞ！",v:"21_0176"},{w:"elly",t:"ピリポン、柱の上へ！",v:"21_0177"},{w:null,t:"ヤマトが、となりのアレクを見る。"},{w:"hero",t:"アレク、今だ！",v:"21_0188"},{w:null,t:"アレク、王から目をはなさずに、うなずく。"},{w:"hero",t:"フォルン、クロッコに重なれ！",v:"21_0190"}]],post:[{w:null,t:"王の体が、大きくかたむく。"},{w:null,t:"胸の奥の、ひびの入ったチップ。"},{w:null,t:"二つに割れたチップが、よろいのすき間から、土の上にこぼれる。"}]};
GR_EP[21]={"t": "守り③ゴッドヘラク", "sc": [["g21_01", "空・天馬の背（昼前）", 0], ["g21_02", "オリーヴァ村・広場（昼）", 0], ["g21_03", "古代の競技場・入口のアーチ（昼）", 0], ["g21_04", "勝負・はじめ", 1], ["g21_05", "勝負・なかほど", 1], ["g21_06", "勝負・おしまい", 1], ["g21_07", "勝負のあと", 0], ["g21_08", "村の丘（昼すぎ）", 0]]};
GR_SC.g22_01=[{w:null,t:"オリーヴァ村のうしろの丘。二十年前まで、てっぺんに研究所があった。",v:"22_0021"},{w:null,t:"丘のてっぺん。"},{w:null,t:"石の手が、二本。"},{w:null,t:"立ち上がる。"},{w:null,t:"オリーブ畑いっぱいに、巨人の影が落ちる。"},{w:null,t:"村の家の戸が、あちこちで開く。"},{w:null,t:"丘のふもとのオリーブの木の下。"},{w:null,t:"アレク、丘の上を見上げる。"},{w:null,t:"アレク、思い出した絵の影と丘の上を見くらべる。"},{w:null,t:"ヤマトの口が、開いたまま。"},{w:null,t:"第22話　守り④アトラード・前編",v:"22_0032"}];
GR_SC.g22_02=[{w:null,t:"広場の柱から、政府の放送の声。"},{w:"x",n:"政府の放送の声",t:"オリーヴァ村のみなさん。北の丘で、地すべりのおそれがあります。",v:"22_0039"},{w:"x",n:"政府の放送の声",t:"南の道から、すみやかに避難してください。",v:"22_0040"},{w:null,t:"村の人たちが、荷物を持って、南の道へ歩きだす。"},{w:null,t:"ホテルの前で、アナが、泊まり客を順に送り出している。"},{w:null,t:"広場のはしの石のベンチに、おばあさん。"}];
GR_SC.g22_03=[{w:null,t:"丘へのぼる細い道。"},{w:null,t:"車の横に、三本足の台にのった細長い筒の機械。"},{w:null,t:"車のドアが開く。"},{w:"victor",t:"やあ、エリーちゃん。里帰りかな？　ここ、きみの村だったね。",v:"22_0049"},{w:"elly",t:"ヴィクターさん！　その長い筒、なんの機械なの？",v:"22_0050"},{w:"victor",t:"お薬だよ。大きい子に、よく効くんだ。",v:"22_0051"},{w:null,t:"ヴィクター、指輪の手をひさしにして、丘の上を見上げる。"},{w:"victor",t:"白い都の子も、運河の子も、王さまも、ほしかったけどね。",v:"22_0053"},{w:"victor",t:"ぼくがいちばんほしかったのは、この子なんだ。",v:"22_0054"},{w:null,t:"アレク、パーカーのポケットから、割れたチップを三つ出して、手のひらにのせて見せる。"},{w:"alek",t:"古代の胸から落ちました。三つとも、あなたの所の印です。",v:"22_0056"},{w:"victor",t:"へえ、拾い集めてるんだ。きみ、才能あるね。",v:"22_0057"},{w:null,t:"ヴィクター、作業員に、あごで合図。"},{w:null,t:"筒の先から、細い光が一本、丘の上へ走る。"},{w:null,t:"巨人の星座の線が、いっせいに赤くなる。"},{w:null,t:"巨人が、ほえる。"},{w:null,t:"巨人の頭が、ゆっくり回る。"},{w:null,t:"一歩。段々畑の石垣が、まとめてくずれる。"},{w:null,t:"作業員の空中の画面に、赤い字。"},{w:"x",n:"作業員",t:"ヴィクターさま、巨人が村の方を向いています。",v:"22_0065"},{w:"victor",t:"大きい子は、なれるのに時間がかかるんだよ。",v:"22_0066"},{w:null,t:"ヴィクター、車のわきの折りたたみのいすにすわる。"},{w:"hero",t:"前のより、でかいだけだろ！　赤と青のやつなら、三発でいける！",v:"22_0069"},{w:"alek",t:"おい、待てって！　一人で先に行くな！",v:"22_0070"},{w:"hero",f:"serious",t:"……やっぱり、四発！",v:"22_0076"},{w:"alek",t:"数の問題じゃないって！",v:"22_0077"}];
GR_SC.g22_04=[{w:null,t:"段々畑のいちばん上。"},{w:null,t:"手前の左のすみ。"},{w:null,t:"右のはしに、村へ下る細い道。"},{w:null,t:"巨人の足もとから、くずれた石垣の岩が、ごろごろと、その道の方へ転がっていく。"},{w:null,t:"巨人が、三人を見下ろす。"}];
GR_SC.g22_08=[{w:null,t:"巨人は、それから一歩も動かなかった。球を、頭の上に持ったまま。",v:"22_0159"},{w:null,t:"月。北の丘の上に、巨人の黒い影。"},{w:null,t:"南の丘の、小さな教会。入口の前に、避難してきた人たちの荷物と、たたんだ銀色のシート。"},{w:null,t:"三人が、石段のはしに並んですわっている。"},{w:null,t:"フォルンが、ヤマトのひざの上で、丸くなって眠っている。しっぽの火が、少しだけ大きくなっている。"},{w:null,t:"エリーは、ひざの上のピリポンの背中を、指でとん、とん、とたたいている。目は、ピリポンと、丘の上の巨人を、行ったり来たりしている。"},{w:null,t:"石段の下の草地で、天馬が立ったまま眠っている。"},{w:null,t:"教会の扉が開く。"},{w:null,t:"エリーが、指を止めて、おばあさんの横顔を見る。"},{w:"oba",t:"あの子、昔のお話だと、空を持たされてたのよ。ずうっと。",v:"22_0168"},{w:null,t:"それだけ言って、おばあさんは、石段を一段ずつもどっていく。"},{w:null,t:"エリー、何も聞かない。シートのはしを、にぎる。"}];
GR_SC.g22_09=[{w:null,t:"教会の窓の明かりが、一つずつ消えていく。"},{w:null,t:"ヤマトが、そっと、フォルンをひざから銀色のシートの上に下ろす。"},{w:null,t:"石段を下りて、北の丘の方へ歩きだす。"},{w:null,t:"段々畑の、いちばん下の石垣の前。"},{w:null,t:"上を見る。巨人の影。"},{w:null,t:"ヤマトの手が、石垣の石をつかむ。"},{w:null,t:"ヤマト、自分のあいた両手を見る。"},{w:null,t:"ヤマト、石垣から手をはなす。"},{w:null,t:"教会の石段。"},{w:null,t:"ヤマト、アレクの前で止まる。"},{w:null,t:"ヤマト、頭を下げる。"},{w:null,t:"遠くで、巨人の星座の線が、ゆっくりまたたく。"},{w:null,t:"アレク、ヤマトのつむじを見る。それから、木の枝で、石段の下の土に、線を引きはじめる。"},{w:null,t:"段々畑。まん中に、丸屋根の石の丸。"},{w:null,t:"アレクの枝が、左の手前のすみで止まる。"},{w:null,t:"ヤマト、顔を上げる。"},{w:"hero",f:"serious",t:"……ため池の水を、使うのか。",v:"22_0190"},{w:null,t:"アレク、答えない。"},{w:null,t:"ヤマト、丸屋根の×と、点線の×を、見くらべる。"},{w:null,t:"エリーは、銀色のシートにくるまって、ピリポンを抱いたまま眠っている。シートのはしから、ピリポンのしっぽ。"},{w:null,t:"アレクが、枝を、草の中へ放る。"},{w:"alek",t:"続きは、あしたの朝だ。今のうちに寝とけ。",v:"22_0195"}];
GR_SC.g22_10=[{w:null,t:"空のはしが、少しだけ白い。"},{w:null,t:"丘の上の巨人。"},{w:null,t:"頭の上の星の球が、ほんの少し、南へかたむく。"},{w:null,t:"巨人の腕が、ふるえはじめる。"},{w:null,t:"胸の奥で、二つのチップが、赤く、ちかちかと光る。"},{w:null,t:"村の家の屋根に、球の影が、ゆっくりかかっていく。"},{w:null,t:"丘のふもとの黒い車。"}];
GR_BT[22]={mid:[[{w:null,t:"エリー、肩のピリポンを、右のはしの道の前に下ろす。"},{w:null,t:"ヤマト、フォルンを手前のまん中に下ろす。"},{w:null,t:"ヤマトが、アレクを見る。アレク、うなずく。"},{w:"hero",t:"行け！　正面から、かみつけ！",v:"22_0102"},{w:"hero",t:"止まるな、何回でもかみつけ！",v:"22_0114"},{w:"hero",t:"押せてる！　な、押せてるだろ！",v:"22_0117"}],[{w:null,t:"ヤマト、赤い光を見る。"},{w:"hero",t:"止まってるぞ！　ひざもついてる。今だ、かみつけ！",v:"22_0126"},{w:null,t:"アレクが、赤い光のふちを見る。"},{w:"alek",t:"ヤマト、横へ——",v:"22_0128"},{w:"hero",t:"この一回でいけるって！",v:"22_0129"},{w:null,t:"アレクの口が、閉じる。"}],[{w:null,t:"エリー、ナルカミを見る。"},{w:"elly",t:"ピリポン、もういいから、こっちにもどって！",v:"22_0147"}]],post:[{w:null,t:"ナルカミ、エリーの方を見る。"},{w:"elly",t:"ピリポン、おねがい！",v:"22_0149"},{w:null,t:"ナルカミが、ゆっくり、エリーの所まで下がる。巨人から目をはなさずに、一歩ずつ。"},{w:null,t:"巨人は、追ってこない。"}]};
GR_EP[22]={"t": "守り④アトラード・前編", "sc": [["g22_01", "オリーヴァ村・丘のふもとのオリーブ畑（昼すぎ）", 0], ["g22_02", "村の広場（昼すぎ）", 0], ["g22_03", "丘のふもとの道（昼すぎ）", 0], ["g22_04", "丘の上・研究所あとの前（昼すぎ）", 0], ["g22_05", "勝負・はじめ", 1], ["g22_06", "勝負・なかほど", 1], ["g22_07", "勝負・おしまい", 1], ["g22_08", "南の丘の教会・石段（夜）", 0], ["g22_09", "同じ石段（真夜中）", 0], ["g22_10", "丘の上（夜明け前）", 0]]};
GR_SC.g23_01=[{w:null,t:"夜明け。村の人は、南の丘の教会で、眠れない夜を明かした。",v:"23_0021"},{w:null,t:"北の丘の上。巨人の腕が、ふるえている。"},{w:null,t:"オリーブ畑の中の道を、三人が丘の方へ歩いていく。"},{w:null,t:"いちばん前にアレク。"},{w:null,t:"ヤマトは走らない。"},{w:null,t:"丘の上。巨人が、ふるえる両腕を少し下げて、かたむいた球を、頭の上に持ちなおす。"},{w:null,t:"巨人の片足が、丸屋根の石から下りる。"},{w:null,t:"第23話　守り④アトラード・後編",v:"23_0029"}];
GR_SC.g23_02=[{w:null,t:"段々畑のいちばん上。"},{w:null,t:"村へ下る道の上に、運転席のない黒い車。"},{w:null,t:"車の前の折りたたみのいすに、ヴィクター。"},{w:"victor",t:"おはよう。早いね。きみたちも、見に来たのかな？",v:"23_0038"},{w:"victor",t:"この子が、うちの子になる所をね。",v:"23_0039"},{w:null,t:"ヴィクター、カップを持っていない方の手を、ひらひらふる。"},{w:null,t:"だれも答えない。エリーだけ、つい小さく手をふりかえす。"},{w:null,t:"巨人が、三人の前で、乾いた土を一回ふむ。"},{w:null,t:"ヤマト、左の手前のすみを見る。"},{w:null,t:"三体が、巨人の前に下りる。"},{w:null,t:"上の段の石垣のきわに、天馬。"}];
GR_SC.g23_06=[{w:null,t:"獣の光がほどけて、ため池のふちに、ピリポンとクロッコ。クロッコは、そのまま、ため池に顔をつけて、がぶがぶ飲む。"},{w:null,t:"赤い光のあった所で、フォルレオンの光がほどける。"},{w:null,t:"巨人の腕から、力がぬける。"},{w:null,t:"フォルン、立ち上がろうとして、前足がくずれる。"},{w:null,t:"エリーが、畑のきわから、乾いた土の上へ一歩出る。"},{w:"elly",t:"（字幕）……ちょっと、持ってて。",v:"23_0131"},{w:null,t:"巨人の目が、エリーを見る。"},{w:null,t:"巨人が、ひざをついたまま、体ごと前へのり出す。大きな両手が、落ちてくる球を、下から受け止める。"},{w:null,t:"フォルンの、耳の先の、すぐ上。"},{w:null,t:"巨人が、ゆっくり、球を持ち上げていく。"},{w:null,t:"村の屋根から、球の影がひいていく。"},{w:null,t:"フォルン、上を見上げる。それから、畑のきわのヤマトの方へ歩いてくる。"},{w:null,t:"ヤマト、にぎっていた手を、やっと開く。"},{w:null,t:"ヤマトは、近づかない。"},{w:null,t:"エリーが、ピリポンをアレクにあずけて、巨人の足もとまで歩いていく。"},{w:null,t:"エリーが、巨人の足に手をそえて、古代のギリシャ語で話しかける。"},{w:null,t:"巨人が、球を頭の上に持ったまま、ゆっくりひざをつきなおす。大きな顔が、エリーの高さまで下りてくる。"},{w:null,t:"エリーが、巨人のあごの石を、手のひらで、ぽん、とたたく。"},{w:null,t:"上の段の石垣のきわから、天馬と王が、巨人のそばへ歩いてくる。"},{w:null,t:"ヴィクターの足もとまで、割れた銀色のチップが一つ、転がってきている。"},{w:"victor",t:"……負けちゃったか。勝ち方は、分かってたんだけどな。",v:"23_0147"},{w:null,t:"ヤマトが、ヴィクターの前に出る。"},{w:"hero",t:"あんたが、ヴィクターの親玉なんだろ。もう、おしまいだぞ。",v:"23_0149"},{w:null,t:"ヴィクター、ヤマトを見て、いつもの顔で笑う。"},{w:"victor",t:"親玉？　ぼくなんか、下の一人にすぎないよ。",v:"23_0151"},{w:null,t:"ヤマトの顔が、止まる。"},{w:null,t:"ヴィクター、いすにもどって、冷めたコーヒーを、ひと口。"},{w:null,t:"ヴィクターの手首の画面が、一度だけ光る。送り主の欄は、名前も顔もない、黒いまま。"},{w:null,t:"「では、東で」"},{w:null,t:"ヴィクターの笑顔が、ほんの一瞬だけ止まる。"}];
GR_SC.g23_07=[{w:null,t:"丘のふもとから、紺色の無人の車が三台、のぼってくる。"},{w:null,t:"先頭の車から、白衣の女。"},{w:null,t:"所長が、巨人を見上げる。"},{w:null,t:"板のいちばん上の書類。"},{w:null,t:"保護局の人が、作業員の手から、空中の画面の出ている板を取り上げる。"},{w:null,t:"ヴィクター、だれにも腕をとられずに、紺色の制服のあいだを、自分の足で車の方へ歩いていく。作業員二人が、うつむいてついていく。"},{w:null,t:"保護局の人が、巨人と、王と、天馬を見上げる。"},{w:"x",n:"保護局の人",t:"……はい。三体、ここにいます。白い都の一体も、動いていません。",v:"23_0169"},{w:"x",n:"保護局の人",t:"では、古代は、上の指示どおり、もう一度、封印の手続きを——",v:"23_0170"},{w:null,t:"保護局の人が、袋に入れようとした画面の板に、目を落とす。"},{w:null,t:"「封印は、また割ればいい」"},{w:null,t:"保護局の人の声が、止まる。"},{w:null,t:"所長、自分の書類の板のいちばん下を見る。"},{w:"shocho",t:"今日お持ちした書類は、これで全部です。",v:"23_0175"},{w:null,t:"保護局の人が、所長を見る。"},{w:null,t:"巨人の足もとで、エリーが、巨人のひざにすわっている。"}];
GR_SC.g23_08=[{w:null,t:"保護局の車の横の、折りたたみの机。"},{w:null,t:"持ち主の欄。"},{w:"x",n:"保護局の人",t:"持ち主の方は……ダレデモナイさん、ですか？",v:"23_0182"},{w:"hero",t:"はい。それ、おれです。",v:"23_0183"},{w:null,t:"保護局の人、ヤマトの顔を見る。"},{w:"x",n:"保護局の人",t:"お名前の、書き直しの手続きは——",v:"23_0185"},{w:"hero",t:"それ、あとでもいい？　今、ちょっといそがしいから。",v:"23_0186"},{w:null,t:"ヤマト、もう、フォルンの方を見ている。"},{w:null,t:"巨人のひざの上で、エリーが、ふき出す。"},{w:null,t:"保護局の人、「ダレデモナイ」の横に、小さく「確認済み」の印を入れる。"}];
GR_SC.g23_09=[{w:null,t:"空中の大きな画面。"},{w:"x",n:"ニュースの声",t:"白い都の電波の塔の事故で、政府は、工事の責任者を——",v:"23_0193"},{w:null,t:"画面の字。「電波の塔の事故　設備の責任者　神崎氏」。"},{w:null,t:"待合室のいすに、レン。"},{w:null,t:"レン、画面を見ている。"},{w:null,t:"レンの手首の画面に、「父さん」からの着信。"}];
GR_SC.g23_10=[{w:null,t:"巨人が、くずれた丸屋根のあった所に、ひざをついてすわっている。"},{w:null,t:"教会から帰ってきた村の人たちが、段々畑の下から、巨人を見上げている。"},{w:null,t:"村の柱の空中の画面から、政府の放送の声。"},{w:"x",n:"政府の放送の声",t:"北の丘の地すべりのおそれは、なくなりました。",v:"23_0203"},{w:null,t:"おじいさんが、オリーブのかごを抱えたまま、巨人を見て、放送の柱を見て、また巨人を見る。"},{w:null,t:"段々畑のいちばん上の石垣に、三人がすわっている。"},{w:null,t:"ヤマトの左の手首の画面が、小さくふるえる。"},{w:null,t:"光の地図。村の丘の印が、赤から青に変わる。"},{w:null,t:"地図が、その外へ、ぐうっと広がっていく。"},{w:null,t:"ずっと東。大きな大陸の、海のそば。"},{w:null,t:"エリーが、その印を見て、ヤマトの顔を見る。"},{w:null,t:"アレクは、印を見たまま、パーカーのポケットの中で、割れたチップの欠けらを、にぎる。"},{w:null,t:"保護局の車の中。"},{w:null,t:"「古代と話せる女の子と、優勝した男の子を」"},{w:null,t:"画面が、消える。"}];
GR_SC.g23_11=[{w:null,t:"朝日。古代の競技場の、まっすぐな土の走路。"},{w:null,t:"割れた石の横に、ヤマトとフォルンが並ぶ。"},{w:null,t:"エリーが、フォルンの前にしゃがんで、手のひらを出す。"},{w:null,t:"フォルン、エリーの手のひらを見る。"},{w:null,t:"エリー、手のひらを出したまま、目を丸くする。それから、笑いだす。"},{w:null,t:"アレクは、土手の石に腰を下ろしている。"},{w:null,t:"走路のはしで、王がすわって見ている。"},{w:null,t:"エリーが、横で片手を上げる。"},{w:"elly",t:"よーい……。",v:"23_0225"},{w:null,t:"ヤマトの足が、ぴくっと前に出かける。"},{w:null,t:"エリーの手が、下りる。"},{w:"hero",t:"今度こそ、いちばん！",v:"23_0228"},{w:null,t:"ヤマト、走りだす。"},{w:null,t:"フォルンが、となりにいる。"},{w:null,t:"走路の向こう。"}];
GR_BT[23]={mid:[[{w:null,t:"エリーの目が、かがやく。"},{w:"elly",t:"ピリポン、いちばん大きいの、撃って！",v:"23_0067"},{w:"victor",t:"へえ。土に、雷を撃つんだ。",v:"23_0073"},{w:null,t:"ヴィクター、にっこり笑う。"},{w:null,t:"エリーの指が、獣の方をさしたまま、止まっている。"},{w:null,t:"ヤマトの目が、左の手前のすみに行く。"},{w:null,t:"ヤマトが、アレクを見る。"},{w:"elly",t:"わかった。ため池だね。",v:"23_0083"},{w:"alek",t:"ため池のふちまで、下がれ！",v:"23_0084"},{w:"victor",t:"逃げるのかい？　水たまりの方へ？",v:"23_0088"}],[{w:null,t:"ヤマトの口が、開く。"},{w:"hero",t:"フォルン、下が——",v:"23_0109"}]],post:[{w:null,t:"ぱきん。ぱきん。"},{w:null,t:"二つのチップが割れて、石の体のすき間から、こぼれ落ちる。"},{w:null,t:"巨人の星座の線が、赤から、青白い光にもどる。"}]};
GR_EP[23]={"t": "守り④アトラード・後編", "sc": [["g23_01", "丘の道（夜明け）", 0], ["g23_02", "丘の上（夜明け）", 0], ["g23_03", "勝負・はじめ", 1], ["g23_04", "勝負・なかほど", 1], ["g23_05", "勝負・おしまい", 1], ["g23_06", "勝負のあと", 0], ["g23_07", "丘の上（朝）", 0], ["g23_08", "保護局の車の前（朝）", 0], ["g23_09", "白い都・テリオンの病院の待合室（昼）", 0], ["g23_10", "丘の上（夕方）", 0], ["g23_11", "古代の競技場・走路（あくる朝）", 0]]};
